// 自動生成（node docs/ui-guide/build.mjs）。手で編集しない。
window.DEMOS = [{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n01","title":"01スクロール Scroll","what":"内容が枠より大きいとき、枠の中で表示位置を動かす。「枠（ビューポート）は動かず、中身が動く」。","how":"操作：枠内でホイール／ドラッグ／ボタン。右の数値が scrollTop。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <button id=\"s01-top\">先頭へ（smooth）</button>\n      <button id=\"s01-mid\">50行目へ（即時）</button>\n      <button id=\"s01-end\">末尾へ（smooth）</button>\n      <span class=\"readout\" id=\"s01-out\">scrollTop: 0</span>\n    </div>\n    <div id=\"s01-box\" class=\"s01-box\"></div>\n  </div>","css":".s01-box { height: 160px; overflow-y: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; }\n.s01-box div { padding: 4px 10px; border-bottom: 1px solid #f1f5f9; font-size: 13px; }","js":"(() => {\n  const box = $('#s01-box'), out = $('#s01-out');\n  for (let i = 1; i <= 100; i++) box.insertAdjacentHTML('beforeend', `<div>行 ${i}</div>`);\n  // scroll イベントは高頻度で発火する。重い処理は入れない。\n  box.addEventListener('scroll', () => out.textContent = `scrollTop: ${Math.round(box.scrollTop)}`);\n  $('#s01-top').onclick = () => box.scrollTo({ top: 0, behavior: 'smooth' });\n  $('#s01-mid').onclick = () => box.children[49].scrollIntoView({ block: 'start' });\n  $('#s01-end').onclick = () => box.scrollTo({ top: box.scrollHeight, behavior: 'smooth' });\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n02","title":"02パン Pan","what":"中身を「掴んで」平行移動する。スクロールと違い、境界がなく（無限に動かせる）、ドラッグ量＝移動量になる。地図・図面・キャンバスの基本操作。","how":"操作：方眼をドラッグ。transform: translate() に差分を足すだけ。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s02-view\" class=\"s02-view\">\n      <div id=\"s02-world\" class=\"s02-world grid-bg\">\n        <div class=\"s02-item\" style=\"left:60px;top:40px\">A</div>\n        <div class=\"s02-item\" style=\"left:300px;top:150px\">B</div>\n        <div class=\"s02-item\" style=\"left:520px;top:60px\">C</div>\n      </div>\n      <span class=\"readout\" id=\"s02-out\" style=\"position:absolute;left:8px;top:8px\">tx: 0, ty: 0</span>\n    </div>\n  </div>","css":".s02-view { position: relative; height: 260px; overflow: hidden; cursor: grab; touch-action: none; user-select: none; }\n.s02-view.dragging { cursor: grabbing; }\n.s02-world { position: absolute; inset: -2000px; transform-origin: 0 0; } /* 見た目上\"無限\"にする */\n.s02-item { position: absolute; margin: 2000px; width: 60px; height: 60px; background: var(--accent); color: #fff; border-radius: 8px; display: grid; place-items: center; }","js":"(() => {\n  const view = $('#s02-view'), world = $('#s02-world'), out = $('#s02-out');\n  let tx = 0, ty = 0, dragging = null;\n  view.addEventListener('pointerdown', e => {\n    dragging = { x: e.clientX - tx, y: e.clientY - ty }; // 押した瞬間の「オフセット」を覚える\n    view.setPointerCapture(e.pointerId);\n    view.classList.add('dragging');\n  });\n  view.addEventListener('pointermove', e => {\n    if (!dragging) return;\n    tx = e.clientX - dragging.x;\n    ty = e.clientY - dragging.y;\n    world.style.transform = `translate(${tx}px, ${ty}px)`;\n    out.textContent = `tx: ${Math.round(tx)}, ty: ${Math.round(ty)}`;\n  });\n  view.addEventListener('pointerup', () => { dragging = null; view.classList.remove('dragging'); });\n  view.addEventListener('pointercancel', () => { dragging = null; view.classList.remove('dragging'); });\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n03","title":"03ズーム Zoom","what":"表示倍率を変える。ここでは「枠の中心」を基準に拡大縮小する最も単純な形。ホイール位置を基準にする本格版は 44。","how":"操作：枠内でホイール（トラックパッドはピンチ＝ctrlKey 付き wheel）、またはボタン。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <button id=\"s03-minus\">−</button><button id=\"s03-plus\">＋</button><button id=\"s03-reset\">100%</button>\n      <span class=\"readout\" id=\"s03-out\">scale: 1.00</span>\n    </div>\n    <div id=\"s03-view\" class=\"s03-view grid-bg\"><div id=\"s03-content\" class=\"s03-content\"><div class=\"box\">ZOOM</div></div></div>\n  </div>","css":".s03-view { height: 180px; display: grid; place-items: center; overflow: hidden; border: 1px solid #cbd5e1; border-radius: 6px; }\n.s03-content { transition: transform .12s ease-out; }","js":"(() => {\n  const view = $('#s03-view'), content = $('#s03-content'), out = $('#s03-out');\n  let scale = 1;\n  const apply = () => {\n    scale = Math.min(5, Math.max(0.2, scale)); // 上下限を必ず設ける\n    content.style.transform = `scale(${scale})`;\n    out.textContent = `scale: ${scale.toFixed(2)}`;\n  };\n  // passive:false にしないと preventDefault が効かずページごとスクロールしてしまう\n  view.addEventListener('wheel', e => {\n    e.preventDefault();\n    const factor = Math.exp(-e.deltaY * 0.002); // 乗算で変えると上下対称になる\n    scale *= factor; apply();\n  }, { passive: false });\n  $('#s03-plus').onclick = () => { scale *= 1.25; apply(); };\n  $('#s03-minus').onclick = () => { scale /= 1.25; apply(); };\n  $('#s03-reset').onclick = () => { scale = 1; apply(); };\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n04","title":"04クリック / タップ Click / Tap","what":"最も基本の操作だが、1回の操作で複数のイベントが順に発火する。マウスとタッチで順序・種類が違うことを見て覚える。","how":"操作：青い箱をクリック／タップ。発火順がログに出る。pointer* を使えば入力装置を問わず1系統で書ける。","html":"<div class=\"stage\">\n    <div class=\"row\"><div id=\"s04-target\" class=\"box\">押す</div><button id=\"s04-clear\">ログ消去</button></div>\n    <div class=\"log\" id=\"s04-log\"></div>\n  </div>","css":"","js":"(() => {\n  const t = $('#s04-target'), log = $('#s04-log');\n  ['pointerdown','pointerup','mousedown','mouseup','touchstart','touchend','click']\n    .forEach(type => t.addEventListener(type, e => logTo(log, `${type}` + (e.pointerType ? ` (pointerType=${e.pointerType})` : ''))));\n  $('#s04-clear').onclick = () => log.textContent = '';\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n05","title":"05ダブルクリック / 長押し Double click / Long press","what":"ダブルクリックは標準イベントがある。長押しは標準イベントが無いので「押してから一定時間、動かさずに離さない」をタイマーで判定する。","how":"操作：左はダブルクリック。右は500ms押し続ける（動かすとキャンセル）。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <div id=\"s05-dbl\" class=\"box\">dblclick</div>\n      <div id=\"s05-long\" class=\"box s05-long\">長押し</div>\n      <span class=\"readout\" id=\"s05-out\">-</span>\n    </div>\n  </div>","css":".s05-long { background: linear-gradient(to top, #1e40af var(--p, 0%), var(--accent) 0); }","js":"(() => {\n  const out = $('#s05-out'), lp = $('#s05-long');\n  $('#s05-dbl').addEventListener('dblclick', () => out.textContent = 'ダブルクリック検出');\n  let timer = null, start = 0, raf = 0;\n  const cancel = () => { clearTimeout(timer); cancelAnimationFrame(raf); timer = null; lp.style.setProperty('--p', '0%'); };\n  lp.addEventListener('pointerdown', e => {\n    start = performance.now();\n    const tick = () => { lp.style.setProperty('--p', Math.min(100, (performance.now() - start) / 5) + '%'); raf = requestAnimationFrame(tick); };\n    tick();\n    timer = setTimeout(() => { cancel(); out.textContent = '長押し検出（500ms）'; }, 500);\n  });\n  lp.addEventListener('pointerup', cancel);\n  lp.addEventListener('pointerleave', cancel);\n  lp.addEventListener('pointermove', e => { if (timer && (Math.abs(e.movementX) + Math.abs(e.movementY)) > 4) cancel(); });\n  lp.addEventListener('contextmenu', e => e.preventDefault()); // タッチ長押しのOSメニュー抑止\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n06","title":"06ホバー Hover","what":"ポインタが要素上にある状態。タッチ端末には「ホバー」が存在しないため、ホバーでしか出ない情報を作らない。","how":"操作：箱にポインタを乗せる。@media (hover: hover) でホバー可能な環境か判定できる。","html":"<div class=\"stage\">\n    <div class=\"row\"><div id=\"s06-target\" class=\"box s06\">hover</div><span class=\"readout\" id=\"s06-out\"></span></div>\n  </div>","css":"@media (hover: hover) { .s06:hover { transform: translateY(-4px); box-shadow: 0 8px 16px rgba(37,99,235,.35); } }\n.s06 { transition: transform .15s, box-shadow .15s; }","js":"(() => {\n  const t = $('#s06-target'), out = $('#s06-out');\n  const canHover = matchMedia('(hover: hover)').matches;\n  out.textContent = `この環境のホバー: ${canHover ? '可能' : '不可（タッチ主体）'}`;\n  t.addEventListener('pointerenter', () => t.textContent = 'enter');\n  t.addEventListener('pointerleave', () => t.textContent = 'leave');\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n07","title":"07フォーカス Focus","what":"キーボード入力を受け取る要素は常に1つ。Tabで順に移動する。:focus-visible はキーボード操作時だけ枠を出すので、マウス時に枠が邪魔にならない。","how":"操作：最初のボタンを押した後 Tab / Shift+Tab。div は tabindex=\"0\" を付けて初めてフォーカスできる。","html":"<div class=\"stage\">\n    <div class=\"row s07\">\n      <button>1</button><button>2</button><div class=\"box\" tabindex=\"0\" style=\"width:60px;height:34px\">div(tabindex=0)</div><input type=\"text\" placeholder=\"4\" style=\"width:80px\">\n      <button id=\"s07-go\">プログラムから4へ</button>\n      <span class=\"readout\" id=\"s07-out\">activeElement: -</span>\n    </div>\n  </div>","css":".s07 :focus-visible { outline: 3px solid #f59e0b; outline-offset: 2px; }","js":"(() => {\n  const out = $('#s07-out');\n  document.addEventListener('focusin', () => {\n    const a = document.activeElement;\n    out.textContent = `activeElement: ${a.tagName.toLowerCase()}${a.textContent ? '「' + a.textContent.trim().slice(0, 12) + '」' : ''}`;\n  });\n  $('#s07-go').onclick = () => $('.s07 input').focus();\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n08","title":"08ドラッグ&ドロップ Drag and Drop（HTML標準API）","what":"要素を掴んで別の場所へ移す。ここはブラウザ標準のDnD API版。見た目のゴーストはブラウザ任せで簡単だが、タッチ非対応・細かい制御不可。自作版は 32。","how":"操作：左のカードを右へドラッグ。dragover で preventDefault() しないとドロップできない、が最大の罠。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"align-items:stretch\">\n      <div class=\"s08-zone\" id=\"s08-a\"><div draggable=\"true\" class=\"s08-card\">受注 #1001</div><div draggable=\"true\" class=\"s08-card\">受注 #1002</div><div draggable=\"true\" class=\"s08-card\">受注 #1003</div></div>\n      <div class=\"s08-zone\" id=\"s08-b\"></div>\n    </div>\n  </div>","css":".s08-zone { flex: 1; min-height: 120px; background: #fff; border: 2px dashed #cbd5e1; border-radius: 8px; padding: 8px; }\n.s08-zone.over { border-color: var(--accent); background: var(--accent-soft); }\n.s08-card { padding: 6px 10px; margin-bottom: 6px; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; cursor: grab; font-size: 13px; }\n.s08-card.dragging { opacity: .4; }","js":"(() => {\n  let dragged = null;\n  $$('.s08-card').forEach(card => {\n    card.addEventListener('dragstart', e => { dragged = card; card.classList.add('dragging'); e.dataTransfer.effectAllowed = 'move'; });\n    card.addEventListener('dragend', () => card.classList.remove('dragging'));\n  });\n  $$('.s08-zone').forEach(zone => {\n    zone.addEventListener('dragover', e => { e.preventDefault(); zone.classList.add('over'); }); // ← 必須\n    zone.addEventListener('dragleave', () => zone.classList.remove('over'));\n    zone.addEventListener('drop', e => { e.preventDefault(); zone.classList.remove('over'); if (dragged) zone.appendChild(dragged); });\n  });\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n09","title":"09スワイプ / フリック Swipe / Flick","what":"指（ポインタ）を素早く払う操作。「移動距離」と「速度」の両方を見て判定する。距離だけだとゆっくりのドラッグと区別がつかない。","how":"操作：灰色の帯を左右に素早く払う。マウスでもドラッグで再現できる。","html":"<div class=\"stage\">\n    <div id=\"s09-area\" class=\"s09-area\">ここを払う</div>\n    <div class=\"row\"><span class=\"readout\" id=\"s09-out\">-</span></div>\n  </div>","css":".s09-area { height: 90px; background: #e2e8f0; border-radius: 8px; display: grid; place-items: center; color: var(--muted); touch-action: pan-y; user-select: none; }","js":"(() => {\n  const area = $('#s09-area'), out = $('#s09-out');\n  let s = null;\n  area.addEventListener('pointerdown', e => s = { x: e.clientX, y: e.clientY, t: performance.now() });\n  area.addEventListener('pointerup', e => {\n    if (!s) return;\n    const dx = e.clientX - s.x, dy = e.clientY - s.y, dt = performance.now() - s.t;\n    const v = Math.abs(dx) / dt; // px/ms\n    let r = `dx=${Math.round(dx)}px dt=${Math.round(dt)}ms v=${v.toFixed(2)}px/ms → `;\n    if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy) && v > 0.3) r += dx > 0 ? 'スワイプ右' : 'スワイプ左';\n    else r += '判定なし（距離不足 or 遅い）';\n    out.textContent = r; s = null;\n  });\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n10","title":"10リサイズ Resize","what":"つまみ（ハンドル）をドラッグして大きさを変える。サイズ変化の検知は ResizeObserver が正解（window.resize は要素の変化を拾えない）。","how":"操作：右下の角をドラッグ。最小サイズで止まる。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <div id=\"s10-panel\" class=\"s10-panel\">パネル<div id=\"s10-handle\" class=\"s10-handle\"></div></div>\n      <span class=\"readout\" id=\"s10-out\"></span>\n    </div>\n  </div>","css":".s10-panel { position: relative; width: 200px; height: 100px; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 8px; font-size: 13px; }\n.s10-handle { position: absolute; right: 0; bottom: 0; width: 16px; height: 16px; cursor: nwse-resize; background: linear-gradient(135deg, transparent 50%, #94a3b8 50%); border-radius: 0 0 6px 0; touch-action: none; }","js":"(() => {\n  const panel = $('#s10-panel'), handle = $('#s10-handle'), out = $('#s10-out');\n  new ResizeObserver(entries => {\n    const r = entries[0].contentRect;\n    out.textContent = `ResizeObserver: ${Math.round(r.width)} × ${Math.round(r.height)}`;\n  }).observe(panel);\n  let st = null;\n  handle.addEventListener('pointerdown', e => {\n    st = { x: e.clientX, y: e.clientY, w: panel.offsetWidth, h: panel.offsetHeight };\n    handle.setPointerCapture(e.pointerId);\n  });\n  handle.addEventListener('pointermove', e => {\n    if (!st) return;\n    panel.style.width = Math.max(120, st.w + e.clientX - st.x) + 'px';\n    panel.style.height = Math.max(60, st.h + e.clientY - st.y) + 'px';\n  });\n  handle.addEventListener('pointerup', () => st = null);\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n11","title":"11選択 Select（単一 / Ctrl追加 / Shift範囲）","what":"項目を選ぶ。Excelやエクスプローラと同じ修飾キー慣習（Ctrl=追加/解除、Shift=範囲）に合わせると業務ユーザーは説明なしで使える。","how":"操作：行をクリック。Ctrl/⌘ や Shift を押しながらクリック。","html":"<div class=\"stage\">\n    <div id=\"s11-list\" class=\"s11-list\" role=\"listbox\" aria-multiselectable=\"true\"></div>\n    <div class=\"row\"><span class=\"readout\" id=\"s11-out\">選択: なし</span></div>\n  </div>","css":".s11-list { background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; user-select: none; }\n.s11-list div { padding: 5px 10px; font-size: 13px; border-bottom: 1px solid #f1f5f9; cursor: default; }\n.s11-list div[aria-selected=\"true\"] { background: var(--accent-soft); color: #1e3a8a; }","js":"(() => {\n  const list = $('#s11-list'), out = $('#s11-out');\n  for (let i = 1; i <= 8; i++) list.insertAdjacentHTML('beforeend', `<div role=\"option\" aria-selected=\"false\">品目 ${i}</div>`);\n  const items = $$('div', list);\n  let anchor = 0; const selected = new Set();\n  const paint = () => {\n    items.forEach((el, i) => el.setAttribute('aria-selected', selected.has(i)));\n    out.textContent = '選択: ' + ([...selected].sort((a, b) => a - b).map(i => i + 1).join(', ') || 'なし');\n  };\n  list.addEventListener('click', e => {\n    const i = items.indexOf(e.target); if (i < 0) return;\n    if (e.shiftKey) {                 // 範囲：アンカーからここまで\n      selected.clear();\n      for (let k = Math.min(anchor, i); k <= Math.max(anchor, i); k++) selected.add(k);\n    } else if (e.ctrlKey || e.metaKey) { // 追加/解除\n      selected.has(i) ? selected.delete(i) : selected.add(i); anchor = i;\n    } else {                           // 単一\n      selected.clear(); selected.add(i); anchor = i;\n    }\n    paint();\n  });\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n12","title":"12フェードイン / フェードアウト Fade in / out","what":"不透明度（opacity）を時間で補間する。最も安価で自然な出現・消失。注意点は「opacity:0 でも要素はそこに在る（クリックできる）」こと。消した後は display:none か visibility:hidden にする。","how":"操作：トグル。transitionend で「完全に消えた瞬間」を拾って非表示化している。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s12-btn\">フェード切替</button><span class=\"readout\" id=\"s12-out\">state: visible</span></div>\n    <div id=\"s12-box\" class=\"box s12\">通知パネル</div>\n  </div>","css":".s12 { width: 160px; transition: opacity .4s ease; }\n.s12.hidden { opacity: 0; pointer-events: none; }  /* 消えている間は操作不可に */","js":"(() => {\n  const box = $('#s12-box'), out = $('#s12-out');\n  $('#s12-btn').onclick = () => {\n    box.classList.toggle('hidden');\n    out.textContent = 'state: transitioning...';\n  };\n  box.addEventListener('transitionend', () => out.textContent = 'state: ' + (box.classList.contains('hidden') ? 'hidden（ここで display:none にしてよい）' : 'visible'));\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n13","title":"13スライドイン / スライドアウト Slide in / out","what":"画面端から滑り込む。left や margin ではなく transform を動かす（レイアウト計算が走らず滑らか）。ドロワー・サイドパネル・通知の基本。","how":"操作：ボタンで右からパネルが出る。背景クリックでも閉じる。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div class=\"s13-frame\">\n      <div class=\"row\" style=\"padding:10px\"><button id=\"s13-open\">パネルを開く</button></div>\n      <div id=\"s13-backdrop\" class=\"s13-backdrop\"></div>\n      <div id=\"s13-panel\" class=\"s13-panel\"><b>設定パネル</b><p style=\"font-size:13px\">transform: translateX(100%) → 0</p><button id=\"s13-close\">閉じる</button></div>\n    </div>\n  </div>","css":".s13-frame { position: relative; height: 260px; overflow: hidden; }\n.s13-panel { position: absolute; top: 0; right: 0; bottom: 0; width: 240px; background: #fff; border-left: 1px solid #cbd5e1; padding: 14px; box-shadow: -8px 0 24px rgba(0,0,0,.08);\n  transform: translateX(100%); transition: transform .3s cubic-bezier(.2,.8,.2,1); }\n.s13-backdrop { position: absolute; inset: 0; background: rgba(0,0,0,.25); opacity: 0; pointer-events: none; transition: opacity .3s; }\n.s13-frame.open .s13-panel { transform: translateX(0); }\n.s13-frame.open .s13-backdrop { opacity: 1; pointer-events: auto; }","js":"(() => {\n  const frame = $('.s13-frame');\n  $('#s13-open').onclick = () => frame.classList.add('open');\n  $('#s13-close').onclick = $('#s13-backdrop').onclick = () => frame.classList.remove('open');\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n14","title":"14トランジション / イージング Transition / Easing","what":"状態AからBへ「時間をかけて」変える仕組みがトランジション。その途中の速度配分がイージング。UIでは ease-out（速く出て静かに止まる）が基本。ease-in は「反応が遅い」と感じさせる。","how":"操作：ボタンで4つの玉を同時に走らせ、違いを見る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s14-run\">走らせる</button></div>\n    <div class=\"s14-lane\"><span>linear</span><div class=\"s14-ball\" style=\"transition-timing-function:linear\"></div></div>\n    <div class=\"s14-lane\"><span>ease-out</span><div class=\"s14-ball\" style=\"transition-timing-function:ease-out\"></div></div>\n    <div class=\"s14-lane\"><span>ease-in</span><div class=\"s14-ball\" style=\"transition-timing-function:ease-in\"></div></div>\n    <div class=\"s14-lane\"><span>cubic-bezier(.2,.8,.2,1)</span><div class=\"s14-ball\" style=\"transition-timing-function:cubic-bezier(.2,.8,.2,1)\"></div></div>\n  </div>","css":".s14-lane { position: relative; height: 30px; margin-bottom: 4px; background: #fff; border: 1px solid #e5e7eb; border-radius: 6px; }\n.s14-lane span { position: absolute; left: 8px; top: 5px; font-size: 12px; color: var(--muted); }\n.s14-ball { position: absolute; top: 4px; left: 4px; width: 22px; height: 22px; border-radius: 50%; background: var(--accent);\n  transition-property: transform; transition-duration: .9s; }\n.s14-lane.go .s14-ball { transform: translateX(calc(100% * 14)); }","js":"(() => {\n  $('#s14-run').onclick = () => {\n    const lanes = $$('.s14-lane');\n    lanes.forEach(l => l.classList.remove('go'));\n    void document.body.offsetWidth; // 再フロー強制：クラスを外した状態を確定させてから再付与\n    lanes.forEach(l => l.classList.add('go'));\n  };\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n15","title":"15モーダル / ダイアログ Modal / Dialog","what":"背後の操作を止めて前面で確認・入力させる。標準の &lt;dialog&gt; を showModal() で開くと、背景の暗幕・Escで閉じる・フォーカス閉じ込め・背面の不活性化が全部ついてくる。","how":"操作：開いて Esc や暗幕クリックで閉じる。戻り値は returnValue で受け取る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s15-open\" class=\"primary\">削除確認を開く</button><span class=\"readout\" id=\"s15-out\">returnValue: -</span></div>\n    <dialog id=\"s15-dlg\" class=\"s15-dlg\">\n      <form method=\"dialog\">\n        <p><b>レコードを削除しますか？</b></p>\n        <p style=\"font-size:13px;color:var(--muted)\">この操作は取り消せません。</p>\n        <div class=\"row\" style=\"justify-content:flex-end\"><button value=\"cancel\">キャンセル</button><button value=\"delete\" class=\"primary\">削除</button></div>\n      </form>\n    </dialog>\n  </div>","css":".s15-dlg { border: none; border-radius: 10px; padding: 18px 20px; width: 320px; box-shadow: 0 20px 50px rgba(0,0,0,.25); }\n.s15-dlg::backdrop { background: rgba(15,23,42,.45); }","js":"(() => {\n  const dlg = $('#s15-dlg'), out = $('#s15-out');\n  $('#s15-open').onclick = () => dlg.showModal();\n  dlg.addEventListener('close', () => out.textContent = 'returnValue: ' + (dlg.returnValue || '(Esc)'));\n  dlg.addEventListener('click', e => { if (e.target === dlg) dlg.close('backdrop'); }); // 暗幕クリックで閉じる\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n16","title":"16トースト / スナックバー Toast / Snackbar","what":"操作結果を隅に短時間表示し、自動で消える。作業を中断させない通知。読み上げ対応のため aria-live を付ける。","how":"操作：連打すると積み上がる。ホバー中は消えない（読む時間を確保）。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s16-ok\">保存成功を通知</button><button id=\"s16-ng\">エラーを通知</button></div>\n    <div id=\"s16-host\" class=\"s16-host\" aria-live=\"polite\"></div>\n  </div>","css":".s16-host { position: absolute; right: 14px; bottom: 14px; display: flex; flex-direction: column; gap: 8px; }\n.s16-toast { min-width: 200px; padding: 10px 14px; border-radius: 8px; color: #fff; background: #0f172a; font-size: 13px; box-shadow: 0 8px 20px rgba(0,0,0,.2);\n  animation: s16-in .25s ease-out; }\n.s16-toast.error { background: #dc2626; }\n.s16-toast.leaving { animation: s16-out .25s ease-in forwards; }\n@keyframes s16-in { from { opacity: 0; transform: translateY(12px); } }\n@keyframes s16-out { to { opacity: 0; transform: translateY(12px); } }","js":"(() => {\n  const host = $('#s16-host');\n  function toast(msg, { error = false, ms = 2500 } = {}) {\n    const el = document.createElement('div');\n    el.className = 's16-toast' + (error ? ' error' : ''); el.textContent = msg;\n    host.appendChild(el);\n    let timer;\n    const arm = () => timer = setTimeout(() => { el.classList.add('leaving'); el.addEventListener('animationend', () => el.remove(), { once: true }); }, ms);\n    el.addEventListener('pointerenter', () => clearTimeout(timer)); // 読んでいる間は消さない\n    el.addEventListener('pointerleave', arm);\n    arm();\n  }\n  let n = 0;\n  $('#s16-ok').onclick = () => toast(`レコード #${++n} を保存しました`);\n  $('#s16-ng').onclick = () => toast('保存に失敗しました（通信エラー）', { error: true, ms: 4000 });\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n17","title":"17ツールチップ / ポップオーバー Tooltip / Popover","what":"補足情報を小さく浮かせて出す。難しいのは位置決め：画面端では上下・左右を反転させる。getBoundingClientRect() で対象の位置を取り、はみ出すなら反対側へ。","how":"操作：ボタンにホバー／フォーカス。右端のボタンでは反転する。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"justify-content:space-between\">\n      <button data-tip=\"左側のボタン。上に出る。\">左</button>\n      <button data-tip=\"中央。これも上。\">中央</button>\n      <button data-tip=\"右端は幅が足りないので左寄せに補正される。\">右端</button>\n    </div>\n    <div id=\"s17-tip\" class=\"s17-tip\" role=\"tooltip\" hidden></div>\n  </div>","css":".s17-tip { position: absolute; max-width: 200px; padding: 6px 10px; background: #0f172a; color: #fff; font-size: 12px; border-radius: 6px; pointer-events: none; z-index: 5; }","js":"(() => {\n  const tip = $('#s17-tip'), stage = tip.parentElement;\n  const show = btn => {\n    tip.textContent = btn.dataset.tip; tip.hidden = false;\n    const b = btn.getBoundingClientRect(), s = stage.getBoundingClientRect(), t = tip.getBoundingClientRect();\n    let left = b.left - s.left + b.width / 2 - t.width / 2;   // 中央揃え\n    left = Math.max(4, Math.min(left, s.width - t.width - 4)); // 枠内に収める\n    let top = b.top - s.top - t.height - 6;                     // 上に出す\n    if (top < 0) top = b.bottom - s.top + 6;                    // 上に余白が無ければ下へ\n    tip.style.left = left + 'px'; tip.style.top = top + 'px';\n  };\n  $$('[data-tip]', stage).forEach(btn => {\n    btn.addEventListener('pointerenter', () => show(btn));\n    btn.addEventListener('focus', () => show(btn));\n    btn.addEventListener('pointerleave', () => tip.hidden = true);\n    btn.addEventListener('blur', () => tip.hidden = true);\n  });\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n18","title":"18アコーディオン / 折りたたみ Accordion / Collapse","what":"セクションの開閉。height: auto へは CSS transition が効かない、が定番の壁。解決策は grid の 0fr → 1fr（JS不要・内容の高さを知らなくてよい）。","how":"操作：見出しをクリック。","html":"<div class=\"stage\">\n    <div class=\"s18\">\n      <button class=\"s18-head\" aria-expanded=\"false\">出荷条件 <span>▾</span></button>\n      <div class=\"s18-body\"><div>納期は受注後5営業日。分納可。梱包は標準仕様。</div></div>\n    </div>\n    <div class=\"s18\">\n      <button class=\"s18-head\" aria-expanded=\"false\">支払条件 <span>▾</span></button>\n      <div class=\"s18-body\"><div>月末締め翌月末払い。<br>手形不可。</div></div>\n    </div>\n  </div>","css":".s18 { background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; margin-bottom: 6px; overflow: hidden; }\n.s18-head { width: 100%; text-align: left; border: none; border-radius: 0; display: flex; justify-content: space-between; }\n.s18-head span { transition: transform .25s; }\n.s18-head[aria-expanded=\"true\"] span { transform: rotate(180deg); }\n.s18-body { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .25s ease; }\n.s18-body > div { overflow: hidden; padding: 0 12px; font-size: 13px; }\n.s18-head[aria-expanded=\"true\"] + .s18-body { grid-template-rows: 1fr; }\n.s18-head[aria-expanded=\"true\"] + .s18-body > div { padding-bottom: 10px; }","js":"(() => {\n  $$('.s18-head').forEach(h => h.onclick = () => h.setAttribute('aria-expanded', h.getAttribute('aria-expanded') !== 'true'));\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n19","title":"19タブ Tabs","what":"同じ領域を複数のビューで切り替える。WAI-ARIAの作法：タブ列は role=tablist、Tabキーでは選択中タブに止まり、←→ で隣へ移動。","how":"操作：クリック、またはタブにフォーカスして矢印キー。","html":"<div class=\"stage\">\n    <div class=\"s19-tabs\" role=\"tablist\">\n      <button role=\"tab\" aria-selected=\"true\" aria-controls=\"s19-p1\" id=\"s19-t1\">基本情報</button>\n      <button role=\"tab\" aria-selected=\"false\" aria-controls=\"s19-p2\" id=\"s19-t2\" tabindex=\"-1\">明細</button>\n      <button role=\"tab\" aria-selected=\"false\" aria-controls=\"s19-p3\" id=\"s19-t3\" tabindex=\"-1\">履歴</button>\n    </div>\n    <div role=\"tabpanel\" id=\"s19-p1\" class=\"s19-panel\">顧客名・納品先などの基本情報。</div>\n    <div role=\"tabpanel\" id=\"s19-p2\" class=\"s19-panel\" hidden>品目・数量・単価の明細。</div>\n    <div role=\"tabpanel\" id=\"s19-p3\" class=\"s19-panel\" hidden>変更履歴のタイムライン。</div>\n  </div>","css":".s19-tabs { display: flex; gap: 2px; border-bottom: 1px solid #cbd5e1; }\n.s19-tabs [role=tab] { border: none; border-bottom: 2px solid transparent; border-radius: 0; background: none; margin-bottom: -1px; }\n.s19-tabs [role=tab][aria-selected=\"true\"] { border-bottom-color: var(--accent); color: var(--accent); font-weight: 600; }\n.s19-panel { padding: 12px 4px; font-size: 13px; }","js":"(() => {\n  const tabs = $$('.s19-tabs [role=tab]');\n  const select = i => tabs.forEach((t, k) => {\n    const on = k === i;\n    t.setAttribute('aria-selected', on); t.tabIndex = on ? 0 : -1;\n    document.getElementById(t.getAttribute('aria-controls')).hidden = !on;\n    if (on) t.focus();\n  });\n  tabs.forEach((t, i) => {\n    t.addEventListener('click', () => select(i));\n    t.addEventListener('keydown', e => {\n      if (e.key === 'ArrowRight') select((i + 1) % tabs.length);\n      if (e.key === 'ArrowLeft') select((i - 1 + tabs.length) % tabs.length);\n    });\n  });\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n20","title":"20ドロップダウン / メニュー Dropdown / Menu","what":"ボタン押下で選択肢を展開する。自作するときの必須処理は3つ：外側クリックで閉じる、Escで閉じる、項目選択で閉じる。","how":"操作：ボタンを押し、外をクリックや Esc で閉じる。","html":"<div class=\"stage\" style=\"min-height:170px\">\n    <div class=\"s20-wrap\">\n      <button id=\"s20-btn\" aria-haspopup=\"menu\" aria-expanded=\"false\">操作 ▾</button>\n      <div id=\"s20-menu\" class=\"s20-menu\" role=\"menu\" hidden>\n        <button role=\"menuitem\">複製</button><button role=\"menuitem\">CSV出力</button><button role=\"menuitem\" style=\"color:#dc2626\">削除</button>\n      </div>\n    </div>\n    <div class=\"row\"><span class=\"readout\" id=\"s20-out\">選択: -</span></div>\n  </div>","css":".s20-wrap { position: relative; display: inline-block; margin-bottom: 8px; }\n.s20-menu { position: absolute; top: 100%; left: 0; margin-top: 4px; min-width: 140px; background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 4px; box-shadow: 0 10px 24px rgba(0,0,0,.12); z-index: 5; }\n.s20-menu button { display: block; width: 100%; text-align: left; border: none; border-radius: 4px; }","js":"(() => {\n  const btn = $('#s20-btn'), menu = $('#s20-menu'), out = $('#s20-out');\n  const set = open => { menu.hidden = !open; btn.setAttribute('aria-expanded', open); };\n  btn.onclick = () => set(menu.hidden);\n  document.addEventListener('click', e => { if (!btn.contains(e.target) && !menu.contains(e.target)) set(false); }); // 外側クリック\n  document.addEventListener('keydown', e => { if (e.key === 'Escape') set(false); });\n  $$('[role=menuitem]', menu).forEach(m => m.onclick = () => { out.textContent = '選択: ' + m.textContent; set(false); });\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n21","title":"21ページネーション / 無限スクロール Pagination / Infinite scroll","what":"大量データを分割して取得・表示する2方式。ページ番号は「位置が分かる」、無限スクロールは「操作が要らない」。kintoneのレコード取得（offset/limit、またはカーソルAPI）はこの下で動く。","how":"操作：左は番号で切替。右は末尾までスクロールすると IntersectionObserver が「番兵」を検知して追加読み込みする。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <div style=\"flex:1\">\n        <div id=\"s21-page\" class=\"s21-list\"></div>\n        <div class=\"row\" id=\"s21-pager\"></div>\n      </div>\n      <div style=\"flex:1\">\n        <div id=\"s21-inf\" class=\"s21-list\" style=\"height:150px;overflow:auto\"></div>\n        <span class=\"readout\" id=\"s21-out\">読込: 0件</span>\n      </div>\n    </div>\n  </div>","css":".s21-list { background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 13px; margin-bottom: 6px; }\n.s21-list div { padding: 3px 10px; border-bottom: 1px solid #f1f5f9; }\n.s21-list .sentinel { color: var(--muted); text-align: center; }","js":"(() => {\n  // 疑似API：offset/limit で取る（kintone の records.json と同じ形）\n  const fetchRecords = (offset, limit) => new Promise(r => setTimeout(() => r(\n    Array.from({ length: limit }, (_, i) => `レコード ${offset + i + 1}`)), 300));\n\n  // --- ページネーション ---\n  const page = $('#s21-page'), pager = $('#s21-pager'), PER = 5, TOTAL = 23;\n  async function goto(p) {\n    page.innerHTML = '<div>読込中…</div>';\n    const rows = await fetchRecords((p - 1) * PER, Math.min(PER, TOTAL - (p - 1) * PER));\n    page.innerHTML = rows.map(r => `<div>${r}</div>`).join('');\n    pager.innerHTML = '';\n    for (let i = 1; i <= Math.ceil(TOTAL / PER); i++) {\n      const b = document.createElement('button'); b.textContent = i; if (i === p) b.className = 'primary';\n      b.onclick = () => goto(i); pager.appendChild(b);\n    }\n  }\n  goto(1);\n\n  // --- 無限スクロール ---\n  const inf = $('#s21-inf'), out = $('#s21-out');\n  const sentinel = document.createElement('div'); sentinel.className = 'sentinel'; sentinel.textContent = '…';\n  inf.appendChild(sentinel);\n  let loaded = 0, busy = false;\n  const io = new IntersectionObserver(async ([e]) => {\n    if (!e.isIntersecting || busy) return;\n    busy = true;\n    const rows = await fetchRecords(loaded, 10); loaded += rows.length;\n    rows.forEach(r => sentinel.insertAdjacentHTML('beforebegin', `<div>${r}</div>`));\n    out.textContent = `読込: ${loaded}件`; busy = false;\n    if (loaded >= 60) { io.disconnect(); sentinel.textContent = '終端'; }\n  }, { root: inf });\n  io.observe(sentinel);\n})();"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n22","title":"22ローディング表示 Loading / Skeleton / Spinner","what":"待ち時間を可視化する。スピナーは「何か待っている」しか伝えないが、スケルトン（内容の形の灰色）は「何が来るか」を先に見せるので体感が速い。","how":"操作：再読込で2秒待ち。どちらの待ち方が楽か比べる。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s22-reload\">再読込（2秒）</button></div>\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <div class=\"s22-card\" id=\"s22-spin\"><div class=\"s22-spinner\"></div></div>\n      <div class=\"s22-card\" id=\"s22-skel\"><div class=\"s22-line w60\"></div><div class=\"s22-line\"></div><div class=\"s22-line w80\"></div></div>\n    </div>\n  </div>","css":".s22-card { flex: 1; min-height: 90px; background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 12px; font-size: 13px; display: grid; align-content: start; gap: 8px; }\n.s22-spinner { width: 26px; height: 26px; border: 3px solid #e5e7eb; border-top-color: var(--accent); border-radius: 50%; animation: s22-spin .8s linear infinite; justify-self: center; align-self: center; margin-top: 18px; }\n@keyframes s22-spin { to { transform: rotate(360deg); } }\n.s22-line { height: 12px; border-radius: 6px; background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 50%, #e5e7eb 75%); background-size: 200% 100%; animation: s22-shimmer 1.2s infinite; }\n.s22-line.w60 { width: 60%; } .s22-line.w80 { width: 80%; }\n@keyframes s22-shimmer { to { background-position: -200% 0; } }","js":"(() => {\n  const spin = $('#s22-spin'), skel = $('#s22-skel');\n  const loading = [spin.innerHTML, skel.innerHTML];\n  const loaded = ['<b>受注 #1001</b><div>株式会社サンプル</div><div>納期 2026-09-12</div>', '<b>受注 #1001</b><div>株式会社サンプル</div><div>納期 2026-09-12</div>'];\n  const load = () => {\n    spin.innerHTML = loading[0]; skel.innerHTML = loading[1];\n    spin.setAttribute('aria-busy', 'true'); skel.setAttribute('aria-busy', 'true');\n    setTimeout(() => { spin.innerHTML = loaded[0]; skel.innerHTML = loaded[1]; spin.removeAttribute('aria-busy'); skel.removeAttribute('aria-busy'); }, 2000);\n  };\n  $('#s22-reload').onclick = load; load();\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n23","title":"23仮想スクロール Virtual scroll / Windowing","what":"10万行あっても DOM は「見えている行＋少し」だけ作る。スクロール位置から開始行を割り算で求め、上に「行高×開始行」の余白を置いて位置を合わせる。","how":"操作：スクロールしても DOM 行数は約20のまま。","html":"<div class=\"stage\">\n    <div class=\"row\"><span class=\"readout\" id=\"s23-out\"></span></div>\n    <div id=\"s23-view\" class=\"s23-view\"><div id=\"s23-spacer\"><div id=\"s23-rows\"></div></div></div>\n  </div>","css":".s23-view { height: 200px; overflow-y: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; }\n.s23-view .r { height: 28px; line-height: 28px; padding: 0 10px; font-size: 13px; border-bottom: 1px solid #f1f5f9; }\n.s23-view .r:nth-child(even) { background: #f8fafc; }","js":"(() => {\n  const TOTAL = 100000, H = 28, view = $('#s23-view'), spacer = $('#s23-spacer'), rows = $('#s23-rows'), out = $('#s23-out');\n  spacer.style.height = TOTAL * H + 'px';              // 全体の高さだけ確保（DOMは作らない）\n  function render() {\n    const start = Math.floor(view.scrollTop / H);\n    const count = Math.ceil(view.clientHeight / H) + 2;  // 画面分＋余裕\n    rows.style.transform = `translateY(${start * H}px)`; // 表示行を正しい位置へ\n    let html = '';\n    for (let i = start; i < Math.min(start + count, TOTAL); i++) html += `<div class=\"r\">行 ${i + 1}（DOMは使い回し）</div>`;\n    rows.innerHTML = html;\n    out.textContent = `全 ${TOTAL.toLocaleString()} 行 / DOM行数 ${rows.children.length} / 表示開始 ${start + 1}`;\n  }\n  view.addEventListener('scroll', render); render();\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n24","title":"24スティッキー（固定ヘッダー / 固定列） Sticky header / column","what":"スクロールしても見出しが留まる。position: sticky だけで実現でき、JSは不要。左上のセルは top と left の両方を指定して両方向に固定する。","how":"操作：表を縦横にスクロール。","html":"<div class=\"stage\">\n    <div id=\"s24-wrap\" class=\"s24-wrap\"><table id=\"s24-table\" class=\"s24\"></table></div>\n  </div>","css":".s24-wrap { height: 200px; overflow: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; }\n.s24 { border-collapse: separate; border-spacing: 0; font-size: 13px; }\n.s24 th, .s24 td { padding: 5px 12px; border-bottom: 1px solid #e5e7eb; border-right: 1px solid #e5e7eb; white-space: nowrap; background: #fff; }\n.s24 thead th { position: sticky; top: 0; background: #f1f5f9; z-index: 2; }\n.s24 td:first-child, .s24 th:first-child { position: sticky; left: 0; background: #f1f5f9; z-index: 1; }\n.s24 thead th:first-child { z-index: 3; } /* 左上：両方向固定・最前面 */","js":"(() => {\n  const t = $('#s24-table');\n  let h = '<thead><tr><th>品番</th>' + Array.from({ length: 12 }, (_, i) => `<th>${i + 1}月</th>`).join('') + '</tr></thead><tbody>';\n  for (let r = 1; r <= 30; r++) h += `<tr><td>P-${String(r).padStart(3, '0')}</td>` + Array.from({ length: 12 }, () => `<td>${Math.floor(Math.random() * 900 + 100)}</td>`).join('') + '</tr>';\n  t.innerHTML = h + '</tbody>';\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n25","title":"25スクロールスナップ Scroll snap","what":"スクロールを止めた時、区切り位置に吸着する。CSSだけで「カルーセル」「ページ単位の閲覧」ができ、慣性・タッチ対応もブラウザ任せ。","how":"操作：横にスクロール（Shift+ホイール or トラックパッド）。どこで止めてもカードの先頭に揃う。","html":"<div class=\"stage\">\n    <div class=\"s25-track\" id=\"s25-track\"></div>\n  </div>","css":".s25-track { display: flex; gap: 12px; overflow-x: auto; scroll-snap-type: x mandatory; padding: 4px; scroll-padding: 4px; }\n.s25-card { flex: 0 0 200px; height: 110px; scroll-snap-align: start; background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; display: grid; place-items: center; font-size: 15px; }","js":"(() => {\n  $('#s25-track').innerHTML = Array.from({ length: 8 }, (_, i) => `<div class=\"s25-card\">カード ${i + 1}</div>`).join('');\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n26","title":"26パララックス Parallax","what":"前景と背景を異なる速度で動かして奥行きを出す。実装は「スクロール量 × 係数」を transform に入れるだけ。業務アプリでは酔いやすいので控えめに。","how":"操作：枠内をスクロール。背景の丸は 0.3 倍の速度で動く。","html":"<div class=\"stage\" style=\"padding:0\">\n    <div id=\"s26-view\" class=\"s26-view\">\n      <div id=\"s26-bg\" class=\"s26-bg\"></div>\n      <div class=\"s26-content\"><p>前景（等速）</p><p>スクロールに合わせて…</p><p>背景がゆっくり動く</p><p>係数 0.3</p><p>終わり</p></div>\n    </div>\n  </div>","css":".s26-view { position: relative; height: 220px; overflow: auto; background: #1e293b; color: #fff; }\n.s26-bg { position: absolute; left: 0; right: 0; top: 0; height: 800px; pointer-events: none;\n  background-image: radial-gradient(circle, rgba(255,255,255,.25) 12px, transparent 13px); background-size: 120px 120px; will-change: transform; }\n.s26-content { position: relative; padding: 20px 30px; } .s26-content p { margin: 0 0 120px; font-size: 18px; }","js":"(() => {\n  const view = $('#s26-view'), bg = $('#s26-bg');\n  view.addEventListener('scroll', () => bg.style.transform = `translateY(${view.scrollTop * 0.7}px)`); // 0.7px戻す＝0.3倍で動く\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n27","title":"27スクロール連動アニメーション Scroll-driven reveal","what":"要素が画面に入った瞬間をトリガーにする。scroll イベントで毎回位置計算せず、IntersectionObserver に「入った／出た」だけ教えてもらう。","how":"操作：枠内をスクロール。入ったカードがフェード＋上昇で現れる。","html":"<div class=\"stage\" style=\"padding:0\">\n    <div id=\"s27-view\" class=\"s27-view\"></div>\n  </div>","css":".s27-view { height: 220px; overflow: auto; padding: 14px; }\n.s27-card { background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 14px; margin-bottom: 60px; font-size: 13px;\n  opacity: 0; transform: translateY(20px); transition: opacity .5s, transform .5s; }\n.s27-card.in { opacity: 1; transform: none; }","js":"(() => {\n  const view = $('#s27-view');\n  view.innerHTML = Array.from({ length: 8 }, (_, i) => `<div class=\"s27-card\">カード ${i + 1}：画面に入ると現れる</div>`).join('');\n  const io = new IntersectionObserver(es => es.forEach(e => e.target.classList.toggle('in', e.isIntersecting)), { root: view, threshold: 0.3 });\n  $$('.s27-card', view).forEach(c => io.observe(c));\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n28","title":"28慣性 / モーメンタム Inertia / Momentum","what":"指を離した後も速度を保ちながら減速して止まる。「離した瞬間の速度」を記録し、毎フレーム速度に減衰係数（0.95など）を掛けて位置を進める。パン（02）にこれを足すと「気持ちよさ」が出る。","how":"操作：方眼を素早くドラッグして離す。壁で跳ね返る。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s28-view\" class=\"s28-view grid-bg\"><div id=\"s28-ball\" class=\"box\" style=\"border-radius:50%;position:absolute;left:0;top:0\">投げる</div><span class=\"readout\" id=\"s28-out\" style=\"position:absolute;left:8px;top:8px\">v: 0</span></div>\n  </div>","css":".s28-view { position: relative; height: 260px; overflow: hidden; touch-action: none; user-select: none; }","js":"(() => {\n  const view = $('#s28-view'), ball = $('#s28-ball'), out = $('#s28-out');\n  let x = 100, y = 80, vx = 0, vy = 0, drag = null, raf = 0, last = null;\n  const paint = () => { ball.style.transform = `translate(${x}px, ${y}px)`; out.textContent = `v: ${Math.hypot(vx, vy).toFixed(2)} px/frame`; };\n  ball.addEventListener('pointerdown', e => { cancelAnimationFrame(raf); drag = { dx: e.clientX - x, dy: e.clientY - y }; last = { x: e.clientX, y: e.clientY, t: performance.now() }; ball.setPointerCapture(e.pointerId); });\n  ball.addEventListener('pointermove', e => {\n    if (!drag) return;\n    x = e.clientX - drag.dx; y = e.clientY - drag.dy;\n    const now = performance.now(), dt = Math.max(1, now - last.t);\n    vx = (e.clientX - last.x) / dt * 16; vy = (e.clientY - last.y) / dt * 16; // 1フレーム(16ms)あたりの速度\n    last = { x: e.clientX, y: e.clientY, t: now }; paint();\n  });\n  ball.addEventListener('pointerup', () => { drag = null; fling(); });\n  function fling() {\n    const W = view.clientWidth - 80, H = view.clientHeight - 80;\n    const step = () => {\n      vx *= 0.95; vy *= 0.95;                      // 減衰\n      x += vx; y += vy;\n      if (x < 0) { x = 0; vx = -vx * 0.6; } if (x > W) { x = W; vx = -vx * 0.6; } // 壁で反射\n      if (y < 0) { y = 0; vy = -vy * 0.6; } if (y > H) { y = H; vy = -vy * 0.6; }\n      paint();\n      if (Math.abs(vx) + Math.abs(vy) > 0.05) raf = requestAnimationFrame(step); // 十分遅くなったら止める\n    };\n    raf = requestAnimationFrame(step);\n  }\n  paint();\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n29","title":"29スプリング物理 Spring animation","what":"目標との差に比例した力（バネ）と速度に比例した抵抗（減衰）で動かす。時間固定のトランジションと違い、途中で目標が変わっても不自然にならない。","how":"操作：枠内をクリック。連続でクリックして途中変更の滑らかさを見る。剛性・減衰を変えてみる。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s29-view\" class=\"s29-view grid-bg\">\n      <div id=\"s29-ball\" class=\"box\" style=\"border-radius:50%;position:absolute;left:0;top:0;width:40px;height:40px\"></div>\n      <div class=\"row\" style=\"position:absolute;left:8px;top:8px;background:#fff;padding:4px 8px;border-radius:6px;font-size:12px\">\n        剛性 <input id=\"s29-k\" type=\"range\" min=\"0.02\" max=\"0.4\" step=\"0.01\" value=\"0.12\"> 減衰 <input id=\"s29-d\" type=\"range\" min=\"0.5\" max=\"0.98\" step=\"0.01\" value=\"0.8\">\n      </div>\n    </div>\n  </div>","css":".s29-view { position: relative; height: 260px; overflow: hidden; cursor: crosshair; }","js":"(() => {\n  const view = $('#s29-view'), ball = $('#s29-ball');\n  let x = 200, y = 120, tx = x, ty = y, vx = 0, vy = 0, raf = 0;\n  view.addEventListener('pointerdown', e => {\n    const r = view.getBoundingClientRect(); tx = e.clientX - r.left - 20; ty = e.clientY - r.top - 20;\n    if (!raf) tick();\n  });\n  function tick() {\n    const k = +$('#s29-k').value, d = +$('#s29-d').value;\n    vx = (vx + (tx - x) * k) * d; vy = (vy + (ty - y) * k) * d; // 力＝差×剛性、速度に減衰\n    x += vx; y += vy;\n    ball.style.transform = `translate(${x}px, ${y}px)`;\n    const settled = Math.abs(vx) + Math.abs(vy) < 0.01 && Math.abs(tx - x) + Math.abs(ty - y) < 0.1;\n    raf = settled ? 0 : requestAnimationFrame(tick);\n  }\n  ball.style.transform = `translate(${x}px, ${y}px)`;\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n30","title":"30FLIPアニメーション First-Last-Invert-Play","what":"レイアウトが変わる（並べ替え・追加・削除）ときの定石。①変更前の位置を測る（First）②DOMを変える③変更後の位置を測る（Last）④差分だけ transform で元の位置に戻す（Invert）⑤transformを0へアニメーション（Play）。","how":"操作：シャッフル。DOMは一瞬で並び替わっているが、見た目は滑らかに移動する。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s30-shuffle\">シャッフル</button><button id=\"s30-sort\">並び順に戻す</button></div>\n    <div id=\"s30-grid\" class=\"s30-grid\"></div>\n  </div>","css":".s30-grid { display: flex; flex-wrap: wrap; gap: 8px; }\n.s30-grid .box { width: 60px; height: 60px; }","js":"(() => {\n  const grid = $('#s30-grid');\n  grid.innerHTML = Array.from({ length: 10 }, (_, i) => `<div class=\"box\" data-i=\"${i}\">${i + 1}</div>`).join('');\n  function flip(mutate) {\n    const items = $$('.box', grid);\n    const first = new Map(items.map(el => [el, el.getBoundingClientRect()])); // First\n    mutate();                                                                  // DOM変更\n    items.forEach(el => {\n      const f = first.get(el), l = el.getBoundingClientRect();               // Last\n      const dx = f.left - l.left, dy = f.top - l.top;\n      if (!dx && !dy) return;\n      el.animate([{ transform: `translate(${dx}px, ${dy}px)` }, { transform: 'none' }], // Invert → Play\n        { duration: 350, easing: 'cubic-bezier(.2,.8,.2,1)' });\n    });\n  }\n  $('#s30-shuffle').onclick = () => flip(() => $$('.box', grid).sort(() => Math.random() - .5).forEach(el => grid.appendChild(el)));\n  $('#s30-sort').onclick = () => flip(() => $$('.box', grid).sort((a, b) => a.dataset.i - b.dataset.i).forEach(el => grid.appendChild(el)));\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n31","title":"31ビュー遷移 View Transitions API","what":"DOM更新の「前」と「後」をブラウザがスナップショットし、自動でクロスフェードする。view-transition-name を付けた要素は位置・サイズの移動もアニメーションする。未対応ブラウザでは即時切替にフォールバック。","how":"操作：「一覧」と「詳細」を切り替える。画像だけは同じ名前を持つので位置が繋がる。","html":"<div class=\"stage\" style=\"min-height:180px\">\n    <div class=\"row\"><button id=\"s31-toggle\">一覧 ⇄ 詳細</button><span class=\"readout\" id=\"s31-out\"></span></div>\n    <div id=\"s31-root\"></div>\n  </div>","css":".s31-thumb { width: 50px; height: 50px; background: var(--accent); border-radius: 8px; view-transition-name: hero; }\n.s31-hero { width: 100%; height: 90px; background: var(--accent); border-radius: 8px; view-transition-name: hero; }\n::view-transition-old(root), ::view-transition-new(root) { animation-duration: .35s; }","js":"(() => {\n  const root = $('#s31-root'), out = $('#s31-out');\n  let detail = false;\n  const render = () => root.innerHTML = detail\n    ? `<div class=\"s31-hero\"></div><p style=\"font-size:13px\">詳細画面：受注 #1001 の内容</p>`\n    : `<div class=\"row\"><div class=\"s31-thumb\"></div><span style=\"font-size:13px\">受注 #1001（一覧の1行）</span></div>`;\n  out.textContent = document.startViewTransition ? 'View Transitions: 対応' : 'View Transitions: 非対応 → 即時切替';\n  $('#s31-toggle').onclick = () => {\n    detail = !detail;\n    if (document.startViewTransition) document.startViewTransition(render); // 対応ブラウザ\n    else render();                                                            // フォールバック\n  };\n  render();\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n32","title":"32ドラッグ並べ替え Sortable / Reorder（Pointer Events自作）","what":"HTML標準DnD（08）を使わず Pointer Events で自作すると、タッチ対応・見た目の完全制御・FLIPとの併用ができる。掴んだ要素は transform で追従させ、他要素との重なりで挿入位置を決める。","how":"操作：行をドラッグして並べ替え。","html":"<div class=\"stage\">\n    <div id=\"s32-list\" class=\"s32-list\"></div>\n  </div>","css":".s32-list { background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; user-select: none; }\n.s32-item { padding: 8px 12px; border-bottom: 1px solid #f1f5f9; font-size: 13px; cursor: grab; touch-action: none; background: #fff; }\n.s32-item.lifted { position: relative; z-index: 2; box-shadow: 0 8px 20px rgba(0,0,0,.15); cursor: grabbing; }","js":"(() => {\n  const list = $('#s32-list');\n  list.innerHTML = ['切断', '曲げ', '溶接', '塗装', '検査', '梱包'].map(s => `<div class=\"s32-item\">⋮⋮ 工程：${s}</div>`).join('');\n  let lifted = null, startY = 0, naturalTop = 0; // naturalTop: transformなしの本来の位置\n  const animating = new WeakSet();               // FLIP 中の兄弟は判定から外す（アニメ中の rect で判定すると往復する）\n  list.addEventListener('pointerdown', e => {\n    lifted = e.target.closest('.s32-item'); if (!lifted) return;\n    startY = e.clientY; naturalTop = lifted.getBoundingClientRect().top;\n    lifted.classList.add('lifted'); lifted.setPointerCapture(e.pointerId);\n  });\n  list.addEventListener('pointermove', e => {\n    if (!lifted) return;\n    let dy = e.clientY - startY;\n    lifted.style.transform = `translateY(${dy}px)`;\n    const cy = naturalTop + dy + lifted.offsetHeight / 2; // 持ち上げ中要素の見た目の中心\n    for (const sib of list.children) {\n      if (sib === lifted || animating.has(sib)) continue;\n      const r = sib.getBoundingClientRect();\n      if (cy < r.top || cy > r.bottom) continue;\n      // 兄弟の中心を越えたので DOM 上で入れ替える\n      const before = r;\n      const liftedIsAfter = sib.compareDocumentPosition(lifted) & Node.DOCUMENT_POSITION_FOLLOWING;\n      liftedIsAfter ? list.insertBefore(lifted, sib) : list.insertBefore(lifted, sib.nextSibling);\n      const after = sib.getBoundingClientRect();\n      const anim = sib.animate([{ transform: `translateY(${before.top - after.top}px)` }, { transform: 'none' }], { duration: 150 }); // FLIP\n      animating.add(sib); anim.finished.then(() => animating.delete(sib));\n      // 持ち上げ中要素の本来位置が変わったので、見た目が飛ばないよう基準をずらす\n      const newNatural = lifted.getBoundingClientRect().top - dy;\n      startY += newNatural - naturalTop; naturalTop = newNatural;\n      lifted.style.transform = `translateY(${e.clientY - startY}px)`;\n      break;\n    }\n  });\n  const drop = () => { if (!lifted) return; lifted.style.transform = ''; lifted.classList.remove('lifted'); lifted = null; };\n  list.addEventListener('pointerup', drop); list.addEventListener('pointercancel', drop);\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n33","title":"33分割パネル / ドッキング Split pane / Dock layout","what":"境界（ガター）をドラッグして領域比率を変える。IDE風レイアウトの基礎。grid の列幅を書き換えるだけで、中身のレイアウトは自動で追従する。慣習：最小幅で止まる、ガターのダブルクリックで初期比率に戻す。","how":"操作：中央の縦棒をドラッグ。ダブルクリックでリセット。","html":"<div class=\"stage\" style=\"padding:0\">\n    <div id=\"s33-split\" class=\"s33-split\">\n      <div class=\"s33-pane\">サイドバー</div>\n      <div id=\"s33-gutter\" class=\"s33-gutter\" title=\"ドラッグ / ダブルクリックで初期化\"></div>\n      <div class=\"s33-pane\">メイン領域<br><span class=\"readout\" id=\"s33-out\"></span></div>\n    </div>\n  </div>","css":".s33-split { display: grid; grid-template-columns: 220px 6px 1fr; height: 200px; }\n.s33-pane { padding: 12px; font-size: 13px; overflow: hidden; }\n.s33-gutter { background: #cbd5e1; cursor: col-resize; touch-action: none; }\n.s33-gutter:hover, .s33-gutter.active { background: var(--accent); }","js":"(() => {\n  const split = $('#s33-split'), g = $('#s33-gutter'), out = $('#s33-out');\n  const MIN = 120, apply = w => { split.style.gridTemplateColumns = `${w}px 6px 1fr`; out.textContent = `左: ${Math.round(w)}px`; };\n  let st = null;\n  g.addEventListener('pointerdown', e => { st = { x: e.clientX, w: split.children[0].offsetWidth }; g.setPointerCapture(e.pointerId); g.classList.add('active'); });\n  g.addEventListener('pointermove', e => { if (st) apply(Math.min(split.clientWidth - MIN - 6, Math.max(MIN, st.w + e.clientX - st.x))); });\n  g.addEventListener('pointerup', () => { st = null; g.classList.remove('active'); });\n  g.addEventListener('dblclick', () => apply(220));\n  apply(220);\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n34","title":"34キーボードナビゲーション Roving tabindex","what":"ツールバーやグリッドの中は矢印キーで移動し、Tab は「グループごと」に抜ける。実現方法は「今の項目だけ tabindex=0、他は -1」に付け替え続けること（roving = 巡回）。","how":"操作：最初のボタンにフォーカス（クリック）→ ←→HomeEnd。Tab で次のグループへ一気に抜ける。","html":"<div class=\"stage\">\n    <div class=\"s34-bar\" role=\"toolbar\" aria-label=\"書式\"><button tabindex=\"0\">太字</button><button tabindex=\"-1\">斜体</button><button tabindex=\"-1\">下線</button><button tabindex=\"-1\">取消線</button></div>\n    <div class=\"s34-bar\" role=\"toolbar\" aria-label=\"配置\"><button tabindex=\"0\">左</button><button tabindex=\"-1\">中央</button><button tabindex=\"-1\">右</button></div>\n    <div class=\"row\"><span class=\"readout\" id=\"s34-out\">-</span></div>\n  </div>","css":".s34-bar { display: inline-flex; gap: 2px; padding: 4px; background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; margin: 0 8px 8px 0; }\n.s34-bar button:focus-visible { outline: 3px solid #f59e0b; }","js":"(() => {\n  $$('.s34-bar').forEach(bar => {\n    const btns = $$('button', bar);\n    const go = i => { btns.forEach((b, k) => b.tabIndex = k === i ? 0 : -1); btns[i].focus(); $('#s34-out').textContent = `${bar.getAttribute('aria-label')} → ${btns[i].textContent}`; };\n    bar.addEventListener('keydown', e => {\n      const i = btns.indexOf(document.activeElement); if (i < 0) return;\n      const map = { ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: btns.length - 1 };\n      if (e.key in map) { e.preventDefault(); go((map[e.key] + btns.length) % btns.length); }\n    });\n    btns.forEach((b, i) => b.addEventListener('focus', () => go(i)));\n  });\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n35","title":"35ショートカットキー Hotkeys","what":"キー組合せで機能を呼ぶ。要点：①ブラウザ既定動作を preventDefault() で止める ②入力欄にフォーカス中は単独キーのショートカットを無効化 ③Mac は metaKey、Windows は ctrlKey。","how":"操作：このページ上で Ctrl/⌘+S、Ctrl/⌘+K（36へ）、単独 N。入力欄内で N を打つと無視される。","html":"<div class=\"stage\">\n    <div class=\"row\"><input type=\"text\" placeholder=\"ここで N を打っても発火しない\"><span class=\"readout\" id=\"s35-out\">-</span></div>\n  </div>","css":"","js":"(() => {\n  const out = $('#s35-out');\n  const isTyping = () => /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName) || document.activeElement.isContentEditable;\n  document.addEventListener('keydown', e => {\n    const mod = e.ctrlKey || e.metaKey;\n    if (mod && e.key.toLowerCase() === 's') { e.preventDefault(); out.textContent = 'Ctrl/⌘+S → 保存（ブラウザの保存ダイアログは抑止）'; }\n    else if (!mod && e.key.toLowerCase() === 'n' && !isTyping()) { out.textContent = 'N → 新規作成'; }\n  });\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n36","title":"36コマンドパレット Command palette","what":"Ctrl+K で検索窓を開き、機能を文字で呼び出す。あいまい検索 → 矢印で選択 → Enter で実行。機能が増えてもメニューを掘らずに済む。","how":"操作：ボタンか Ctrl/⌘+K。「csv」「削」などで絞り込み。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s36-open\">コマンドパレットを開く</button><span class=\"readout\" id=\"s36-out\">-</span></div>\n    <dialog id=\"s36-dlg\" class=\"s36-dlg\">\n      <input id=\"s36-q\" type=\"text\" placeholder=\"コマンドを検索…\" autocomplete=\"off\">\n      <div id=\"s36-list\" class=\"s36-list\"></div>\n    </dialog>\n  </div>","css":".s36-dlg { border: none; border-radius: 10px; padding: 0; width: 380px; box-shadow: 0 20px 50px rgba(0,0,0,.3); }\n.s36-dlg::backdrop { background: rgba(15,23,42,.35); }\n.s36-dlg input { width: 100%; border: none; border-bottom: 1px solid #e5e7eb; border-radius: 10px 10px 0 0; padding: 12px 14px; font-size: 15px; outline: none; }\n.s36-list div { padding: 8px 14px; font-size: 13px; cursor: pointer; }\n.s36-list div.active { background: var(--accent-soft); }","js":"(() => {\n  const CMDS = ['新規レコード作成', 'CSV出力', 'CSV取込', '選択行を削除', '選択行を複製', '設定を開く', 'ログアウト'];\n  const dlg = $('#s36-dlg'), q = $('#s36-q'), list = $('#s36-list'), out = $('#s36-out');\n  let idx = 0, hits = [];\n  const render = () => {\n    const s = q.value.trim().toLowerCase();\n    hits = CMDS.filter(c => c.toLowerCase().includes(s)); idx = Math.min(idx, Math.max(0, hits.length - 1));\n    list.innerHTML = hits.map((c, i) => `<div class=\"${i === idx ? 'active' : ''}\">${c}</div>`).join('') || '<div style=\"color:#6b7280\">該当なし</div>';\n  };\n  const open = () => { q.value = ''; idx = 0; render(); dlg.showModal(); };\n  const run = () => { if (hits[idx]) out.textContent = '実行: ' + hits[idx]; dlg.close(); };\n  $('#s36-open').onclick = open;\n  document.addEventListener('keydown', e => { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); open(); } });\n  q.addEventListener('input', e => { if (e.isComposing) return; idx = 0; render(); });\n  q.addEventListener('compositionend', () => { idx = 0; render(); });\n  q.addEventListener('keydown', e => {\n    if (e.isComposing) return;                      // 日本語の変換中は矢印も Enter も無視する（18 章の 107）\n    if (e.key === 'ArrowDown') { idx = (idx + 1) % hits.length; render(); e.preventDefault(); }\n    if (e.key === 'ArrowUp') { idx = (idx - 1 + hits.length) % hits.length; render(); e.preventDefault(); }\n    if (e.key === 'Enter') run();\n  });\n  list.addEventListener('click', e => { idx = [...list.children].indexOf(e.target); run(); });\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n37","title":"37アンドゥ / リドゥ Undo / Redo","what":"操作履歴を積んで巻き戻す。ここは「状態のスナップショット」方式（過去の状態を丸ごと配列に保存）。単純で確実。状態が大きいなら「逆操作コマンド」方式を検討する。","how":"操作：丸を追加／色替え → Ctrl/⌘+Z / Ctrl/⌘+Shift+Z またはボタン。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <button id=\"s37-add\">丸を追加</button><button id=\"s37-color\">全部の色を変える</button><button id=\"s37-clear\">全消去</button>\n      <button id=\"s37-undo\">↶ Undo</button><button id=\"s37-redo\">↷ Redo</button><span class=\"readout\" id=\"s37-out\"></span>\n    </div>\n    <div id=\"s37-canvas\" class=\"s37-canvas\"></div>\n  </div>","css":".s37-canvas { height: 90px; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; display: flex; gap: 6px; padding: 8px; flex-wrap: wrap; }\n.s37-canvas i { width: 24px; height: 24px; border-radius: 50%; }","js":"(() => {\n  let state = [], past = [], future = [];\n  const canvas = $('#s37-canvas'), out = $('#s37-out');\n  const render = () => { canvas.innerHTML = state.map(c => `<i style=\"background:${c}\"></i>`).join(''); out.textContent = `past:${past.length} future:${future.length}`; };\n  const commit = next => { past.push(state); future = []; state = next; render(); };  // 新操作で redo 履歴は捨てる\n  const undo = () => { if (!past.length) return; future.push(state); state = past.pop(); render(); };\n  const redo = () => { if (!future.length) return; past.push(state); state = future.pop(); render(); };\n  const rnd = () => `hsl(${Math.random() * 360},70%,55%)`;\n  $('#s37-add').onclick = () => commit([...state, rnd()]);\n  $('#s37-color').onclick = () => commit(state.map(rnd));\n  $('#s37-clear').onclick = () => commit([]);\n  $('#s37-undo').onclick = undo; $('#s37-redo').onclick = redo;\n  document.addEventListener('keydown', e => {\n    if (!(e.ctrlKey || e.metaKey) || e.key.toLowerCase() !== 'z') return;\n    e.preventDefault(); e.shiftKey ? redo() : undo();\n  });\n  render();\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n38","title":"38インライン編集 Inline editing","what":"表示中の値をその場で編集状態に切り替える。終了経路を3つ揃える：Enter=確定、Esc=取消、フォーカスが外れた=確定。どれか欠けると「戻れない」UIになる。","how":"操作：セルをダブルクリック（またはフォーカスして Enter）。","html":"<div class=\"stage\">\n    <table class=\"s38\"><tr><th>品名</th><th>数量</th></tr><tr><td tabindex=\"0\">六角ボルト M8</td><td tabindex=\"0\">120</td></tr><tr><td tabindex=\"0\">平ワッシャー</td><td tabindex=\"0\">300</td></tr></table>\n    <div class=\"row\"><span class=\"readout\" id=\"s38-out\">-</span></div>\n  </div>","css":".s38 { border-collapse: collapse; background: #fff; font-size: 13px; margin-bottom: 8px; }\n.s38 th, .s38 td { border: 1px solid #cbd5e1; padding: 4px 10px; min-width: 120px; }\n.s38 td input { width: 100%; font: inherit; border: 2px solid var(--accent); padding: 2px 4px; margin: -4px -6px; }","js":"(() => {\n  const out = $('#s38-out');\n  function edit(td) {\n    const old = td.textContent;\n    const input = document.createElement('input'); input.value = old;\n    td.textContent = ''; td.appendChild(input); input.focus(); input.select();\n    let done = false;\n    const finish = (commit) => {\n      if (done) return; done = true;\n      td.textContent = commit ? input.value : old;\n      out.textContent = commit ? `確定: 「${old}」→「${input.value}」` : '取消';\n      td.focus();\n    };\n    // 変換確定の Enter を「確定」と誤認しないよう isComposing を見る（18 章の 107）\n    input.addEventListener('keydown', e => { if (e.isComposing) return; if (e.key === 'Enter') finish(true); if (e.key === 'Escape') finish(false); });\n    input.addEventListener('blur', () => finish(true));\n  }\n  $$('.s38 td').forEach(td => {\n    td.addEventListener('dblclick', () => edit(td));\n    // Enter は td 自身に来たときだけ編集開始。入力欄から上がってきた確定の Enter で再び開かないようにする\n    // check-ime-ignore : e.target === td で入力欄からの確定 Enter を除外済み（td 上では変換が起きない）\n    td.addEventListener('keydown', e => { if (e.target === td && e.key === 'Enter' && !td.querySelector('input')) edit(td); });\n  });\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n39","title":"39カスタムコンテキストメニュー Custom context menu","what":"右クリックで独自メニューを出す。contextmenu イベントを止め、クリック位置に出す。画面端では反転して枠内に収める。","how":"操作：灰色の領域で右クリック（タッチは長押し）。端の方で試す。","html":"<div class=\"stage\" style=\"padding:0\">\n    <div id=\"s39-area\" class=\"s39-area\">右クリック</div>\n    <div id=\"s39-menu\" class=\"s39-menu\" role=\"menu\" hidden><button>コピー</button><button>貼り付け</button><button>行を挿入</button></div>\n    <span class=\"readout\" id=\"s39-out\" style=\"position:absolute;left:8px;bottom:8px\">-</span>\n  </div>","css":".s39-area { height: 180px; display: grid; place-items: center; color: var(--muted); }\n.s39-menu { position: absolute; background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 4px; box-shadow: 0 10px 24px rgba(0,0,0,.15); z-index: 5; }\n.s39-menu button { display: block; width: 100%; text-align: left; border: none; }","js":"(() => {\n  const area = $('#s39-area'), menu = $('#s39-menu'), stage = area.parentElement, out = $('#s39-out');\n  area.addEventListener('contextmenu', e => {\n    e.preventDefault();\n    menu.hidden = false;\n    const s = stage.getBoundingClientRect();\n    let x = e.clientX - s.left, y = e.clientY - s.top;\n    if (x + menu.offsetWidth > s.width) x -= menu.offsetWidth;    // 右にはみ出す → 左へ\n    if (y + menu.offsetHeight > s.height) y -= menu.offsetHeight; // 下にはみ出す → 上へ\n    menu.style.left = x + 'px'; menu.style.top = y + 'px';\n  });\n  const close = () => menu.hidden = true;\n  document.addEventListener('click', close);\n  document.addEventListener('keydown', e => e.key === 'Escape' && close());\n  $$('button', menu).forEach(b => b.onclick = () => out.textContent = '実行: ' + b.textContent);\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n40","title":"40進捗表示 Progress（determinate / indeterminate）","what":"完了率が分かるなら確定型（バー）、分からないなら不定型（流れるだけ）。長い処理には必ずキャンセル手段を添える。AbortController で中断できる作りにしておく。","how":"操作：開始 → 途中でキャンセル。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s40-start\">1000件処理を開始</button><button id=\"s40-cancel\" disabled>キャンセル</button><span class=\"readout\" id=\"s40-out\">待機</span></div>\n    <progress id=\"s40-bar\" max=\"100\" value=\"0\" style=\"width:100%\"></progress>\n    <div class=\"s40-indet\" id=\"s40-indet\" hidden></div>\n  </div>","css":".s40-indet { height: 6px; margin-top: 8px; border-radius: 3px; background: linear-gradient(90deg, transparent, var(--accent), transparent); background-size: 40% 100%; animation: s40 1s linear infinite; }\n@keyframes s40 { from { background-position: -40% 0; } to { background-position: 140% 0; } }","js":"(() => {\n  const bar = $('#s40-bar'), out = $('#s40-out'), indet = $('#s40-indet'), start = $('#s40-start'), cancel = $('#s40-cancel');\n  let ctrl = null;\n  start.onclick = async () => {\n    ctrl = new AbortController(); start.disabled = true; cancel.disabled = false; indet.hidden = false; out.textContent = '準備中（不定型）';\n    await new Promise(r => setTimeout(r, 800));\n    indet.hidden = true;\n    for (let i = 1; i <= 100; i++) {\n      if (ctrl.signal.aborted) { out.textContent = `キャンセル（${i * 10}件で中断）`; break; }\n      await new Promise(r => setTimeout(r, 30));\n      bar.value = i; out.textContent = `${i * 10} / 1000 件`;\n    }\n    start.disabled = false; cancel.disabled = true;\n  };\n  cancel.onclick = () => ctrl?.abort();\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n41","title":"41ジェスチャー競合の解決 touch-action / 方向ロック","what":"「縦にスクロールしたいのか、横にスワイプしたいのか」をブラウザと取り合わない。touch-action: pan-y で縦はブラウザに任せ、横は自分で取る。さらに初動数pxの方向で「今回はどちらか」を確定（方向ロック）する。","how":"操作：カードを横にドラッグ（削除アクションが出る）。縦に動かすと枠がスクロールする。タッチ端末で差がよく分かる。","html":"<div class=\"stage\" style=\"padding:0\">\n    <div id=\"s41-list\" class=\"s41-list\"></div>\n  </div>","css":".s41-list { height: 200px; overflow-y: auto; }\n.s41-row { position: relative; background: #dc2626; color: #fff; }\n.s41-row::after { content: '削除'; position: absolute; right: 14px; top: 10px; font-size: 13px; }\n.s41-card { position: relative; background: #fff; padding: 10px 14px; border-bottom: 1px solid #e5e7eb; font-size: 13px; color: var(--text); touch-action: pan-y; user-select: none; }\n.s41-card.snap { transition: transform .2s; }","js":"(() => {\n  const list = $('#s41-list');\n  list.innerHTML = Array.from({ length: 8 }, (_, i) => `<div class=\"s41-row\"><div class=\"s41-card\">通知 ${i + 1}：横スワイプで削除、縦でスクロール</div></div>`).join('');\n  $$('.s41-card', list).forEach(card => {\n    let st = null, lock = null; // lock: 'x' | 'y' | null\n    card.addEventListener('pointerdown', e => { st = { x: e.clientX, y: e.clientY }; lock = null; card.classList.remove('snap'); });\n    card.addEventListener('pointermove', e => {\n      if (!st) return;\n      const dx = e.clientX - st.x, dy = e.clientY - st.y;\n      if (!lock && Math.hypot(dx, dy) > 6) lock = Math.abs(dx) > Math.abs(dy) ? 'x' : 'y'; // 初動で方向確定\n      if (lock !== 'x') return;                    // 縦ならブラウザのスクロールに任せる\n      card.setPointerCapture(e.pointerId);\n      card.style.transform = `translateX(${Math.min(0, dx)}px)`;\n    });\n    const end = e => {\n      if (!st) return;\n      const dx = e.clientX - st.x; st = null; card.classList.add('snap');\n      if (lock === 'x' && dx < -100) card.style.transform = 'translateX(-100%)'; else card.style.transform = '';\n    };\n    card.addEventListener('pointerup', end); card.addEventListener('pointercancel', end);\n  });\n})();"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n42","title":"42モーション低減対応 prefers-reduced-motion","what":"OS設定で「視覚効果を減らす」を選んだユーザーには、動きを短縮・省略する。CSSのメディアクエリ1つで全アニメーションを止められる。JSからも matchMedia で判定できる。","how":"操作：ボタンで動かす。OS設定を変えるとこのページの動きが止まる（右の表示で確認）。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s42-run\">動かす</button><span class=\"readout\" id=\"s42-out\"></span></div>\n    <div id=\"s42-ball\" class=\"box s42-ball\">●</div>\n  </div>","css":".s42-ball { transition: transform .8s cubic-bezier(.2,.8,.2,1); }\n.s42-ball.moved { transform: translateX(300px) rotate(360deg); }\n@media (prefers-reduced-motion: reduce) {\n  .s42-ball { transition: none; }  /* 移動はするが、動きは付けない */\n}","js":"(() => {\n  const mq = matchMedia('(prefers-reduced-motion: reduce)'), out = $('#s42-out');\n  const show = () => out.textContent = `OS設定: ${mq.matches ? 'モーション低減 ON（アニメーション省略）' : '通常'}`;\n  mq.addEventListener('change', show); show();\n  $('#s42-run').onclick = () => $('#s42-ball').classList.toggle('moved');\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n43","title":"43無限キャンバス Infinite canvas（パン＋ズーム＋座標変換）","what":"画面座標（ピクセル）とワールド座標（図面上の位置）を分けて持つ。表示は screen = world × scale + offset、入力は逆算 world = (screen − offset) ÷ scale。この2つの式だけで、パン・ズーム・クリック位置の特定が全部つながる。","how":"操作：ドラッグでパン、ホイールでズーム（カーソル基準）、ダブルクリックでその位置に点を置く。右上にカーソルのワールド座標が出る。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s43-view\" class=\"s43-view\">\n      <div id=\"s43-world\" class=\"s43-world\"></div>\n      <span class=\"readout\" id=\"s43-out\" style=\"position:absolute;right:8px;top:8px\">-</span>\n    </div>\n  </div>","css":".s43-view { position: relative; height: 300px; overflow: hidden; background: #fff; touch-action: none; user-select: none; cursor: grab;\n  background-image: radial-gradient(#cbd5e1 1px, transparent 1px); background-size: 24px 24px; }\n.s43-world { position: absolute; left: 0; top: 0; transform-origin: 0 0; }\n.s43-node { position: absolute; width: 80px; height: 40px; margin: -20px 0 0 -40px; background: var(--accent); color: #fff; border-radius: 6px; display: grid; place-items: center; font-size: 12px; }\n.s43-dot { position: absolute; width: 10px; height: 10px; margin: -5px 0 0 -5px; border-radius: 50%; background: #dc2626; }","js":"(() => {\n  const view = $('#s43-view'), world = $('#s43-world'), out = $('#s43-out');\n  const cam = { x: 40, y: 40, s: 1 };                               // offset と scale ＝「カメラ」\n  const toWorld = (sx, sy) => ({ x: (sx - cam.x) / cam.s, y: (sy - cam.y) / cam.s });\n  const apply = () => world.style.transform = `translate(${cam.x}px, ${cam.y}px) scale(${cam.s})`;\n  const local = e => { const r = view.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; };\n\n  [[100, 80, '受注'], [320, 160, '製造'], [540, 90, '出荷']].forEach(([x, y, t]) =>\n    world.insertAdjacentHTML('beforeend', `<div class=\"s43-node\" style=\"left:${x}px;top:${y}px\">${t}<br>(${x},${y})</div>`));\n\n  let drag = null;\n  view.addEventListener('pointerdown', e => { const p = local(e); drag = { x: p.x - cam.x, y: p.y - cam.y }; view.setPointerCapture(e.pointerId); });\n  view.addEventListener('pointermove', e => {\n    const p = local(e), w = toWorld(p.x, p.y);\n    out.textContent = `screen(${Math.round(p.x)},${Math.round(p.y)}) → world(${Math.round(w.x)},${Math.round(w.y)}) scale=${cam.s.toFixed(2)}`;\n    if (drag) { cam.x = p.x - drag.x; cam.y = p.y - drag.y; apply(); }\n  });\n  view.addEventListener('pointerup', () => drag = null);\n  view.addEventListener('wheel', e => {                                // ズーム：カーソル位置を不動点にする（44参照）\n    e.preventDefault();\n    const p = local(e), before = toWorld(p.x, p.y);\n    cam.s = Math.min(4, Math.max(0.25, cam.s * Math.exp(-e.deltaY * 0.002)));\n    cam.x = p.x - before.x * cam.s; cam.y = p.y - before.y * cam.s;  // 同じワールド点がカーソル下に来るよう offset を補正\n    apply(); out.textContent = `scale=${cam.s.toFixed(2)}（カーソル下の world は不変）`;\n  }, { passive: false });\n  view.addEventListener('dblclick', e => { const w = toWorld(local(e).x, local(e).y); world.insertAdjacentHTML('beforeend', `<div class=\"s43-dot\" style=\"left:${w.x}px;top:${w.y}px\"></div>`); });\n  apply();\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n44","title":"44ズーム中心の維持 Zoom-to-cursor","what":"「ズームすると見ていた場所がズレる」の正体は、原点基準で scale しているから。カーソル下のワールド座標を先に求め、scale 変更後も同じ点がカーソル下に来るよう offset を計算し直す。式：offset = cursor − world × newScale。","how":"操作：方式を切り替えて、同じ位置でホイールしてみる。「原点基準」だと図がカーソルから逃げる。","html":"<div class=\"stage\" style=\"padding:0\">\n    <div class=\"row\" style=\"padding:8px\"><label><input type=\"radio\" name=\"s44\" value=\"cursor\" checked> カーソル基準（正）</label><label><input type=\"radio\" name=\"s44\" value=\"origin\"> 原点基準（ズレる）</label><button id=\"s44-reset\">リセット</button></div>\n    <div id=\"s44-view\" class=\"s44-view\"><div id=\"s44-world\" class=\"s44-world grid-bg\"><div class=\"box\" style=\"position:absolute;left:150px;top:60px\">ここで<br>ホイール</div></div></div>\n  </div>","css":".s44-view { position: relative; height: 220px; overflow: hidden; background: #fff; }\n.s44-world { position: absolute; left: 0; top: 0; width: 600px; height: 400px; transform-origin: 0 0; border: 2px solid #94a3b8; }","js":"(() => {\n  const view = $('#s44-view'), world = $('#s44-world');\n  const cam = { x: 0, y: 0, s: 1 };\n  const apply = () => world.style.transform = `translate(${cam.x}px, ${cam.y}px) scale(${cam.s})`;\n  view.addEventListener('wheel', e => {\n    e.preventDefault();\n    const r = view.getBoundingClientRect(), cx = e.clientX - r.left, cy = e.clientY - r.top;\n    const newS = Math.min(4, Math.max(0.3, cam.s * Math.exp(-e.deltaY * 0.002)));\n    if ($('input[name=s44]:checked').value === 'cursor') {\n      const wx = (cx - cam.x) / cam.s, wy = (cy - cam.y) / cam.s;  // カーソル下のワールド座標\n      cam.x = cx - wx * newS; cam.y = cy - wy * newS;               // その点が同じ画面位置に来る offset\n    }\n    cam.s = newS; apply();\n  }, { passive: false });\n  $('#s44-reset').onclick = () => { cam.x = cam.y = 0; cam.s = 1; apply(); };\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n45","title":"45ミニマップ Minimap","what":"全体を縮小して描き、現在の表示範囲を枠で示す。枠のドラッグでも移動できる。同じワールド座標を「別の縮尺」で描いているだけなので、43 の式がそのまま使える。","how":"操作：大きい方をドラッグでパン、または右下のミニマップの枠をドラッグ。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s45-view\" class=\"s45-view\">\n      <div id=\"s45-world\" class=\"s45-world grid-bg\"></div>\n      <div id=\"s45-mini\" class=\"s45-mini\"><div id=\"s45-rect\" class=\"s45-rect\"></div></div>\n    </div>\n  </div>","css":".s45-view { position: relative; height: 280px; overflow: hidden; background: #fff; touch-action: none; user-select: none; cursor: grab; }\n.s45-world { position: absolute; left: 0; top: 0; width: 1600px; height: 1000px; }\n.s45-world i { position: absolute; width: 60px; height: 40px; background: var(--accent); border-radius: 6px; opacity: .8; }\n.s45-mini { position: absolute; right: 10px; bottom: 10px; width: 160px; height: 100px; background: rgba(255,255,255,.9); border: 1px solid #94a3b8; border-radius: 4px; overflow: hidden; cursor: move; }\n.s45-mini i { position: absolute; width: 6px; height: 4px; background: var(--accent); }\n.s45-rect { position: absolute; border: 2px solid #dc2626; background: rgba(220,38,38,.1); box-sizing: border-box; }","js":"(() => {\n  const view = $('#s45-view'), world = $('#s45-world'), mini = $('#s45-mini'), rect = $('#s45-rect');\n  const W = 1600, H = 1000, K = 160 / W;                             // ミニマップの縮尺\n  const items = Array.from({ length: 25 }, () => [Math.random() * (W - 60), Math.random() * (H - 40)]);\n  world.innerHTML = items.map(([x, y]) => `<i style=\"left:${x}px;top:${y}px\"></i>`).join('');\n  mini.insertAdjacentHTML('afterbegin', items.map(([x, y]) => `<i style=\"left:${x * K}px;top:${y * K}px\"></i>`).join(''));\n  const cam = { x: -300, y: -200 };\n  const clamp = () => { cam.x = Math.min(0, Math.max(view.clientWidth - W, cam.x)); cam.y = Math.min(0, Math.max(view.clientHeight - H, cam.y)); };\n  const apply = () => {\n    clamp(); world.style.transform = `translate(${cam.x}px, ${cam.y}px)`;\n    rect.style.left = -cam.x * K + 'px'; rect.style.top = -cam.y * K + 'px';   // 表示範囲 ＝ (-offset, viewサイズ) を縮尺で\n    rect.style.width = view.clientWidth * K + 'px'; rect.style.height = view.clientHeight * K + 'px';\n  };\n  let drag = null;\n  view.addEventListener('pointerdown', e => { if (mini.contains(e.target)) return; drag = { x: e.clientX - cam.x, y: e.clientY - cam.y }; view.setPointerCapture(e.pointerId); });\n  view.addEventListener('pointermove', e => { if (drag) { cam.x = e.clientX - drag.x; cam.y = e.clientY - drag.y; apply(); } });\n  view.addEventListener('pointerup', () => drag = null);\n  let mdrag = null;                                                   // ミニマップ側：動きを 1/K 倍して逆向きに\n  mini.addEventListener('pointerdown', e => { mdrag = { x: e.clientX, y: e.clientY, cx: cam.x, cy: cam.y }; mini.setPointerCapture(e.pointerId); e.stopPropagation(); });\n  mini.addEventListener('pointermove', e => { if (mdrag) { cam.x = mdrag.cx - (e.clientX - mdrag.x) / K; cam.y = mdrag.cy - (e.clientY - mdrag.y) / K; apply(); } });\n  mini.addEventListener('pointerup', () => mdrag = null);\n  apply();\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n46","title":"46ノードエディタ Node graph / Wiring","what":"ノード（箱）のポート同士を線で結ぶ。線は SVG のベジェ曲線 M x1 y1 C x1+d y1, x2−d y2, x2 y2。出力ポートからドラッグ→入力ポートで離すと接続。ノードを動かすと線を引き直す。","how":"操作：右側の●から左側の●へドラッグして接続。ノード本体をドラッグで移動。線をクリックで削除。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s46-view\" class=\"s46-view grid-bg\">\n      <svg id=\"s46-svg\" class=\"s46-svg\"></svg>\n    </div>\n  </div>","css":".s46-view { position: relative; height: 300px; overflow: hidden; user-select: none; touch-action: none; }\n.s46-svg { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }\n.s46-svg path { fill: none; stroke: #475569; stroke-width: 2.5; pointer-events: stroke; cursor: pointer; }\n.s46-svg path:hover { stroke: #dc2626; } .s46-svg path.temp { stroke: var(--accent); stroke-dasharray: 6 4; }\n.s46-node { position: absolute; width: 140px; background: #fff; border: 1px solid #94a3b8; border-radius: 8px; font-size: 12px; box-shadow: 0 4px 12px rgba(0,0,0,.08); }\n.s46-node header { padding: 6px 10px; background: #f1f5f9; border-radius: 8px 8px 0 0; cursor: grab; font-weight: 600; }\n.s46-node .ports { display: flex; justify-content: space-between; padding: 8px 0; }\n.s46-port { width: 12px; height: 12px; border-radius: 50%; background: #fff; border: 2px solid var(--accent); cursor: crosshair; }\n.s46-port.in { margin-left: -7px; } .s46-port.out { margin-right: -7px; }","js":"(() => {\n  const view = $('#s46-view'), svg = $('#s46-svg');\n  const nodes = [['n1', 30, 40, '受注データ'], ['n2', 230, 140, '在庫引当'], ['n3', 430, 60, '出荷指示']];\n  nodes.forEach(([id, x, y, t]) => view.insertAdjacentHTML('beforeend',\n    `<div class=\"s46-node\" id=\"${id}\" style=\"left:${x}px;top:${y}px\"><header>${t}</header><div class=\"ports\"><div class=\"s46-port in\" data-node=\"${id}\"></div><div class=\"s46-port out\" data-node=\"${id}\"></div></div></div>`));\n  const edges = [['n1', 'n2']];\n  const portPos = (id, side) => { const p = $(`#${id} .s46-port.${side}`).getBoundingClientRect(), v = view.getBoundingClientRect(); return { x: p.left - v.left + 6, y: p.top - v.top + 6 }; };\n  const curve = (a, b) => `M ${a.x} ${a.y} C ${a.x + 60} ${a.y}, ${b.x - 60} ${b.y}, ${b.x} ${b.y}`;\n  const draw = () => {\n    svg.innerHTML = edges.map(([f, t], i) => `<path data-i=\"${i}\" d=\"${curve(portPos(f, 'out'), portPos(t, 'in'))}\"></path>`).join('') + '<path class=\"temp\" id=\"s46-temp\" d=\"\"></path>';\n  };\n  svg.addEventListener('click', e => { if (e.target.dataset.i) { edges.splice(+e.target.dataset.i, 1); draw(); } });\n  let mode = null;\n  view.addEventListener('pointerdown', e => {\n    const v = view.getBoundingClientRect();\n    if (e.target.classList.contains('out')) mode = { type: 'wire', from: e.target.dataset.node, start: portPos(e.target.dataset.node, 'out') };\n    else if (e.target.tagName === 'HEADER') { const n = e.target.parentElement; mode = { type: 'move', node: n, dx: e.clientX - n.offsetLeft, dy: e.clientY - n.offsetTop }; }\n    if (mode) view.setPointerCapture(e.pointerId);\n  });\n  view.addEventListener('pointermove', e => {\n    if (!mode) return;\n    const v = view.getBoundingClientRect();\n    if (mode.type === 'wire') $('#s46-temp').setAttribute('d', curve(mode.start, { x: e.clientX - v.left, y: e.clientY - v.top }));\n    else { mode.node.style.left = e.clientX - mode.dx + 'px'; mode.node.style.top = e.clientY - mode.dy + 'px'; draw(); }\n  });\n  view.addEventListener('pointerup', e => {\n    if (mode?.type === 'wire') {\n      const t = document.elementFromPoint(e.clientX, e.clientY);            // 離した場所の要素を調べる\n      if (t?.classList.contains('in') && t.dataset.node !== mode.from) edges.push([mode.from, t.dataset.node]);\n    }\n    mode = null; draw();\n  });\n  draw();\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n47","title":"47スナップ / スマートガイド Snapping / Smart guides","what":"ドラッグ中、他要素の端・中心と一定距離（しきい値）以内なら、その座標に吸着してガイド線を出す。候補座標を全部列挙して「最も近いものが閾値内か」を見るだけ。","how":"操作：青い箱をドラッグして灰色の箱の端・中心に近づける。Ctrl を押しながらだとスナップ無効。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s47-view\" class=\"s47-view\">\n      <div class=\"s47-fixed\" style=\"left:60px;top:40px;width:120px;height:80px\"></div>\n      <div class=\"s47-fixed\" style=\"left:340px;top:150px;width:100px;height:100px\"></div>\n      <div id=\"s47-box\" class=\"s47-box\">drag</div>\n      <div id=\"s47-gx\" class=\"s47-guide v\" hidden></div><div id=\"s47-gy\" class=\"s47-guide h\" hidden></div>\n    </div>\n  </div>","css":".s47-view { position: relative; height: 280px; background: #fff; overflow: hidden; touch-action: none; user-select: none; }\n.s47-fixed { position: absolute; background: #e2e8f0; border-radius: 6px; }\n.s47-box { position: absolute; left: 200px; top: 180px; width: 80px; height: 60px; background: var(--accent); color: #fff; border-radius: 6px; display: grid; place-items: center; cursor: grab; font-size: 12px; }\n.s47-guide { position: absolute; background: #ec4899; pointer-events: none; }\n.s47-guide.v { top: 0; bottom: 0; width: 1px; } .s47-guide.h { left: 0; right: 0; height: 1px; }","js":"(() => {\n  const view = $('#s47-view'), box = $('#s47-box'), gx = $('#s47-gx'), gy = $('#s47-gy'), TH = 6;\n  const targets = $$('.s47-fixed', view).map(f => ({ l: f.offsetLeft, t: f.offsetTop, w: f.offsetWidth, h: f.offsetHeight }));\n  const xs = [], ys = [];                                               // スナップ候補（端と中心）\n  targets.forEach(r => { xs.push(r.l, r.l + r.w / 2, r.l + r.w); ys.push(r.t, r.t + r.h / 2, r.t + r.h); });\n  const snap = (val, cands, size) => {                                  // 自分の左端/中心/右端のどれかが候補に近いか\n    let best = null;\n    for (const c of cands) for (const off of [0, size / 2, size]) { const d = c - (val + off); if (Math.abs(d) <= TH && (!best || Math.abs(d) < Math.abs(best.d))) best = { d, line: c }; }\n    return best;\n  };\n  let drag = null;\n  box.addEventListener('pointerdown', e => { drag = { dx: e.clientX - box.offsetLeft, dy: e.clientY - box.offsetTop }; box.setPointerCapture(e.pointerId); });\n  box.addEventListener('pointermove', e => {\n    if (!drag) return;\n    let x = e.clientX - drag.dx, y = e.clientY - drag.dy;\n    const sx = e.ctrlKey ? null : snap(x, xs, box.offsetWidth), sy = e.ctrlKey ? null : snap(y, ys, box.offsetHeight);\n    if (sx) { x += sx.d; gx.style.left = sx.line + 'px'; } gx.hidden = !sx;\n    if (sy) { y += sy.d; gy.style.top = sy.line + 'px'; } gy.hidden = !sy;\n    box.style.left = x + 'px'; box.style.top = y + 'px';\n  });\n  box.addEventListener('pointerup', () => { drag = null; gx.hidden = gy.hidden = true; });\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n48","title":"48矩形選択 Rubber band selection","what":"空白からドラッグして矩形を描き、重なった要素をまとめて選ぶ。判定は「矩形同士が交差するか」の4比較。Shift 併用で既存選択に追加。","how":"操作：空白からドラッグ。Shift+ドラッグで追加選択。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s48-view\" class=\"s48-view\"><div id=\"s48-band\" class=\"s48-band\" hidden></div></div>\n    <span class=\"readout\" id=\"s48-out\" style=\"position:absolute;left:8px;bottom:8px\">選択: 0</span>\n  </div>","css":".s48-view { position: relative; height: 280px; background: #fff; overflow: hidden; touch-action: none; user-select: none; }\n.s48-item { position: absolute; width: 44px; height: 44px; border-radius: 8px; background: #e2e8f0; display: grid; place-items: center; font-size: 12px; }\n.s48-item.sel { background: var(--accent); color: #fff; }\n.s48-band { position: absolute; border: 1px solid var(--accent); background: rgba(37,99,235,.15); pointer-events: none; }","js":"(() => {\n  const view = $('#s48-view'), band = $('#s48-band'), out = $('#s48-out');\n  for (let i = 0; i < 24; i++) view.insertAdjacentHTML('afterbegin', `<div class=\"s48-item\" style=\"left:${20 + (i % 8) * 70}px;top:${30 + Math.floor(i / 8) * 80}px\">${i + 1}</div>`);\n  const items = $$('.s48-item', view);\n  const hit = (a, b) => !(a.right < b.left || a.left > b.right || a.bottom < b.top || a.top > b.bottom); // 交差判定\n  let st = null, keep = new Set();\n  view.addEventListener('pointerdown', e => {\n    if (e.target !== view) return;\n    keep = e.shiftKey ? new Set(items.filter(i => i.classList.contains('sel'))) : new Set();\n    const r = view.getBoundingClientRect(); st = { x: e.clientX - r.left, y: e.clientY - r.top }; band.hidden = false; view.setPointerCapture(e.pointerId);\n  });\n  view.addEventListener('pointermove', e => {\n    if (!st) return;\n    const r = view.getBoundingClientRect(), x = e.clientX - r.left, y = e.clientY - r.top;\n    const b = { left: Math.min(st.x, x), top: Math.min(st.y, y), right: Math.max(st.x, x), bottom: Math.max(st.y, y) };\n    Object.assign(band.style, { left: b.left + 'px', top: b.top + 'px', width: b.right - b.left + 'px', height: b.bottom - b.top + 'px' });\n    items.forEach(it => {\n      const ir = { left: it.offsetLeft, top: it.offsetTop, right: it.offsetLeft + it.offsetWidth, bottom: it.offsetTop + it.offsetHeight };\n      it.classList.toggle('sel', keep.has(it) || hit(b, ir));\n    });\n    out.textContent = '選択: ' + items.filter(i => i.classList.contains('sel')).length;\n  });\n  view.addEventListener('pointerup', () => { st = null; band.hidden = true; });\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n49","title":"49ポインタキャプチャ setPointerCapture","what":"ドラッグ中にポインタが要素の外に出ても、その要素がイベントを受け続けるようにする。これが無いと「速く動かすと箱が置いていかれる」「外で離すと pointerup が来ない」が起きる。","how":"操作：2つの箱を素早くドラッグして比べる。左はキャプチャなし（外に出た瞬間止まる）。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div class=\"s49-view\">\n      <div id=\"s49-a\" class=\"box s49-box\" style=\"left:40px\">なし</div>\n      <div id=\"s49-b\" class=\"box s49-box\" style=\"left:200px\">capture</div>\n      <span class=\"readout\" id=\"s49-out\" style=\"position:absolute;left:8px;bottom:8px\">-</span>\n    </div>\n  </div>","css":".s49-view { position: relative; height: 240px; }\n.s49-box { position: absolute; top: 60px; cursor: grab; }","js":"(() => {\n  const out = $('#s49-out');\n  const setup = (el, capture) => {\n    let d = null, moves = 0;\n    el.addEventListener('pointerdown', e => { d = { x: e.clientX - el.offsetLeft, y: e.clientY - el.offsetTop }; moves = 0; if (capture) el.setPointerCapture(e.pointerId); });\n    el.addEventListener('pointermove', e => { if (!d) return; moves++; el.style.left = e.clientX - d.x + 'px'; el.style.top = e.clientY - d.y + 'px'; });\n    el.addEventListener('pointerup', () => { d = null; out.textContent = `${el.textContent}: pointermove ${moves} 回, pointerup 受信`; });\n    el.addEventListener('lostpointercapture', () => d = null);\n  };\n  setup($('#s49-a'), false); setup($('#s49-b'), true);\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n50","title":"50マルチタッチジェスチャー Pinch / Rotate / 2-finger pan","what":"2本の指の「距離」「角度」「中点」の変化量から、拡大率・回転角・移動量を同時に求める。pointerId ごとに座標を Map で持てば、Pointer Events だけで書ける。","how":"操作：タッチ端末なら2本指でピンチ／回転。マウスなら Shift を押しながらドラッグすると「2本目の指が箱の中心に固定されている」扱いで模擬できる。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s50-view\" class=\"s50-view grid-bg\"><div id=\"s50-box\" class=\"box\" style=\"width:120px;height:120px;position:absolute;left:180px;top:70px\">multi<br>touch</div><span class=\"readout\" id=\"s50-out\" style=\"position:absolute;left:8px;top:8px\">-</span></div>\n  </div>","css":".s50-view { position: relative; height: 280px; overflow: hidden; touch-action: none; user-select: none; }","js":"(() => {\n  const view = $('#s50-view'), box = $('#s50-box'), out = $('#s50-out');\n  const pts = new Map(); let base = null, anchor = null;   // anchor: マウス模擬用の「固定された2本目の指」\n  const T = { x: 0, y: 0, s: 1, r: 0 };\n  const apply = () => { box.style.transform = `translate(${T.x}px, ${T.y}px) rotate(${T.r}deg) scale(${T.s})`; out.textContent = `scale=${T.s.toFixed(2)} rotate=${T.r.toFixed(0)}° pointers=${pts.size}`; };\n  const center = () => { const r = box.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; };\n  const gesture = () => {                                  // 2点から「距離・角度・中点」を出す\n    const p = [...pts.values()], a = p[0], b = p.length >= 2 ? p[1] : anchor;  // 1本なら固定点を2本目に\n    return { d: Math.hypot(b.x - a.x, b.y - a.y), ang: Math.atan2(b.y - a.y, b.x - a.x) * 180 / Math.PI, mx: (a.x + b.x) / 2, my: (a.y + b.y) / 2, p0: { ...a } };\n  };\n  const rebase = () => base = pts.size ? { g: gesture(), T: { ...T } } : null;\n  view.addEventListener('pointerdown', e => { if (!pts.size) anchor = center(); pts.set(e.pointerId, { x: e.clientX, y: e.clientY }); view.setPointerCapture(e.pointerId); rebase(); });\n  view.addEventListener('pointermove', e => {\n    if (!pts.has(e.pointerId) || !base) return;\n    pts.set(e.pointerId, { x: e.clientX, y: e.clientY });\n    const g = gesture();\n    if (pts.size >= 2 || e.shiftKey) {                       // ピンチ・回転・2本指パン\n      T.s = base.T.s * g.d / base.g.d; T.r = base.T.r + (g.ang - base.g.ang);\n      T.x = base.T.x + (g.mx - base.g.mx); T.y = base.T.y + (g.my - base.g.my);\n    } else {                                                 // 1本指：パンのみ\n      T.x = base.T.x + (g.p0.x - base.g.p0.x); T.y = base.T.y + (g.p0.y - base.g.p0.y);\n    }\n    apply();\n  });\n  const up = e => { pts.delete(e.pointerId); rebase(); apply(); };\n  view.addEventListener('pointerup', up); view.addEventListener('pointercancel', up);\n  apply();\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n51","title":"51修飾キーによる制約 Constrained drag（Shift / Alt / Ctrl）","what":"ツール系アプリの共通作法：Shift=軸固定（水平か垂直のみ）、Alt=グリッド吸着、Ctrl=吸着解除。移動量の計算の最後に、押されているキーで補正を掛けるだけ。","how":"操作：箱をドラッグしながら Shift / Alt を押す。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div class=\"s51-view grid-bg\" style=\"background-size:20px 20px\"><div id=\"s51-box\" class=\"box\" style=\"position:absolute;left:100px;top:60px\">drag</div><span class=\"readout\" id=\"s51-out\" style=\"position:absolute;left:8px;top:8px\">-</span></div>\n  </div>","css":".s51-view { position: relative; height: 240px; overflow: hidden; touch-action: none; user-select: none; }","js":"(() => {\n  const box = $('#s51-box'), out = $('#s51-out'), GRID = 20;\n  let st = null;\n  box.addEventListener('pointerdown', e => { st = { x: e.clientX, y: e.clientY, l: box.offsetLeft, t: box.offsetTop }; box.setPointerCapture(e.pointerId); });\n  box.addEventListener('pointermove', e => {\n    if (!st) return;\n    let dx = e.clientX - st.x, dy = e.clientY - st.y, mods = [];\n    if (e.shiftKey) { Math.abs(dx) > Math.abs(dy) ? dy = 0 : dx = 0; mods.push('Shift: 軸固定'); } // 大きい方の軸だけ残す\n    let x = st.l + dx, y = st.t + dy;\n    if (e.altKey) { x = Math.round(x / GRID) * GRID; y = Math.round(y / GRID) * GRID; mods.push('Alt: グリッド吸着'); }\n    box.style.left = x + 'px'; box.style.top = y + 'px';\n    out.textContent = `(${x}, ${y}) ${mods.join(' / ') || '制約なし'}`;\n  });\n  box.addEventListener('pointerup', () => st = null);\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n52","title":"52状態機械駆動UI State-machine driven interaction","what":"「押した」「動かした」「離した」を場当たり的に処理するとバグが出る。状態を明示（idle → pressed → dragging → idle）し、各イベントで「今の状態で何が起きたら次はどこか」だけを書く。押しただけ（pressed→idle）はクリック、閾値を超えたらドラッグ、と分岐が自然に決まる。","how":"操作：箱をクリック／少しだけ動かす／大きく動かす。右の図で現在状態が光る。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <div class=\"s52-view grid-bg\"><div id=\"s52-box\" class=\"box\" style=\"position:absolute;left:40px;top:40px\">箱</div></div>\n      <div style=\"flex:1\">\n        <div class=\"s52-states\"><span data-s=\"idle\" class=\"on\">idle</span>→<span data-s=\"pressed\">pressed</span>→<span data-s=\"dragging\">dragging</span></div>\n        <div class=\"log\" id=\"s52-log\"></div>\n      </div>\n    </div>\n  </div>","css":".s52-view { position: relative; width: 240px; height: 170px; touch-action: none; user-select: none; }\n.s52-states { font-family: ui-monospace, monospace; font-size: 13px; margin-bottom: 6px; }\n.s52-states span { padding: 2px 8px; border-radius: 4px; background: #e2e8f0; margin: 0 4px; }\n.s52-states span.on { background: var(--accent); color: #fff; }","js":"(() => {\n  const box = $('#s52-box'), log = $('#s52-log'), TH = 5;\n  let state = 'idle', ctx = {};\n  const go = (next, why) => { logTo(log, `${state} --(${why})--> ${next}`); state = next; $$('.s52-states span').forEach(s => s.classList.toggle('on', s.dataset.s === next)); };\n  box.addEventListener('pointerdown', e => {\n    if (state !== 'idle') return;\n    ctx = { x: e.clientX, y: e.clientY, l: box.offsetLeft, t: box.offsetTop }; box.setPointerCapture(e.pointerId); go('pressed', 'pointerdown');\n  });\n  box.addEventListener('pointermove', e => {\n    const dx = e.clientX - ctx.x, dy = e.clientY - ctx.y;\n    if (state === 'pressed' && Math.hypot(dx, dy) > TH) go('dragging', `移動 > ${TH}px`);\n    if (state === 'dragging') { box.style.left = ctx.l + dx + 'px'; box.style.top = ctx.t + dy + 'px'; }\n  });\n  box.addEventListener('pointerup', () => {\n    if (state === 'pressed') { go('idle', 'pointerup → クリック扱い'); }\n    else if (state === 'dragging') { go('idle', 'pointerup → ドロップ確定'); }\n  });\n  box.addEventListener('pointercancel', () => { if (state !== 'idle') { box.style.left = ctx.l + 'px'; box.style.top = ctx.t + 'px'; go('idle', 'cancel → 元に戻す'); } });\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n53","title":"53Web Animations API WAAPI","what":"JS からアニメーションを生成し、一時停止・逆再生・速度変更・完了待ち（Promise）ができる。CSS transition では「途中で止めて戻す」が書きにくいが、WAAPI なら animation.reverse() の1行。","how":"操作：ボタンで制御。「完了待ち」は await anim.finished の後にログが出る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s53-play\">再生</button><button id=\"s53-pause\">一時停止</button><button id=\"s53-reverse\">逆再生</button><button id=\"s53-fast\">速度×3</button><span class=\"readout\" id=\"s53-out\">-</span></div>\n    <div id=\"s53-box\" class=\"box\">WAAPI</div>\n  </div>","css":"","js":"(() => {\n  const box = $('#s53-box'), out = $('#s53-out');\n  const anim = box.animate(\n    [{ transform: 'translateX(0) rotate(0)' }, { transform: 'translateX(320px) rotate(360deg)' }],\n    { duration: 1500, easing: 'ease-in-out', fill: 'both' });\n  anim.pause();\n  const watch = async () => { out.textContent = `state: ${anim.playState}`; try { await anim.finished; out.textContent = 'finished（Promise 解決）'; } catch { /* cancel 時 */ } };\n  $('#s53-play').onclick = () => { anim.playbackRate = 1; anim.play(); watch(); };\n  $('#s53-pause').onclick = () => { anim.pause(); out.textContent = `state: ${anim.playState} @ ${Math.round(anim.currentTime)}ms`; };\n  $('#s53-reverse').onclick = () => { anim.reverse(); watch(); };\n  $('#s53-fast').onclick = () => { anim.playbackRate = 3; anim.play(); watch(); };\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n54","title":"54描画ループ最適化 rAF batching","what":"pointermove は 1フレームに複数回来ることがある（高レートマウス・タッチ）。イベントごとに描画すると無駄。「最新の値だけ保存し、描画は requestAnimationFrame で1フレーム1回」にまとめる。","how":"操作：方眼の上でマウスを素早く動かす。イベント回数と描画回数の差を見る。","html":"<div class=\"stage\">\n    <div class=\"row\"><label><input type=\"checkbox\" id=\"s54-batch\" checked> rAF でまとめる</label><span class=\"readout\" id=\"s54-out\">-</span></div>\n    <div id=\"s54-view\" class=\"s54-view grid-bg\"><div id=\"s54-dot\" class=\"s54-dot\"></div></div>\n  </div>","css":".s54-view { position: relative; height: 140px; overflow: hidden; }\n.s54-dot { position: absolute; width: 16px; height: 16px; margin: -8px; border-radius: 50%; background: #dc2626; pointer-events: none; }","js":"(() => {\n  const view = $('#s54-view'), dot = $('#s54-dot'), out = $('#s54-out'), batch = $('#s54-batch');\n  let events = 0, paints = 0, pending = false, last = null;\n  const paint = () => { paints++; dot.style.transform = `translate(${last.x}px, ${last.y}px)`; out.textContent = `pointermove ${events} 回 / 描画 ${paints} 回`; pending = false; };\n  view.addEventListener('pointermove', e => {\n    events++;\n    const r = view.getBoundingClientRect(); last = { x: e.clientX - r.left, y: e.clientY - r.top }; // 最新値だけ保持\n    if (!batch.checked) return paint();                     // 毎イベント描画（比較用）\n    if (!pending) { pending = true; requestAnimationFrame(paint); } // 1フレーム1回だけ\n  });\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n55","title":"55Canvas 描画 Canvas rendering + ヒットテスト + devicePixelRatio","what":"DOM要素を数万個作ると重いが、Canvas ならビットマップに描くだけなので軽い。代わりに「どれをクリックしたか」は自分で計算する（ヒットテスト）。高解像度画面では devicePixelRatio 分だけ内部解像度を上げないとぼやける。","how":"操作：点の上にマウスを乗せると赤くなる（距離計算でヒット判定）。","html":"<div class=\"stage\" style=\"padding:0\">\n    <canvas id=\"s55-c\" class=\"s55-c\"></canvas>\n    <span class=\"readout\" id=\"s55-out\" style=\"position:absolute;left:8px;top:8px\">-</span>\n  </div>","css":".s55-c { display: block; width: 100%; height: 240px; background: #fff; }","js":"(() => {\n  const c = $('#s55-c'), ctx = c.getContext('2d'), out = $('#s55-out'), N = 20000;\n  const dpr = devicePixelRatio || 1;\n  let W, H, pts = [], hover = -1;\n  const resize = () => {\n    W = c.clientWidth; H = c.clientHeight;\n    c.width = W * dpr; c.height = H * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0);  // 内部解像度を DPR 倍に\n    pts = Array.from({ length: N }, () => ({ x: Math.random() * W, y: Math.random() * H }));\n    draw();\n  };\n  const draw = () => {\n    const t0 = performance.now();\n    ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#93c5fd';\n    for (const p of pts) ctx.fillRect(p.x, p.y, 2, 2);\n    if (hover >= 0) { ctx.fillStyle = '#dc2626'; ctx.beginPath(); ctx.arc(pts[hover].x + 1, pts[hover].y + 1, 6, 0, Math.PI * 2); ctx.fill(); }\n    out.textContent = `${N.toLocaleString()} 点を ${(performance.now() - t0).toFixed(1)}ms で描画 / dpr=${dpr}` + (hover >= 0 ? ` / hit #${hover}` : '');\n  };\n  c.addEventListener('pointermove', e => {\n    const r = c.getBoundingClientRect(), x = e.clientX - r.left, y = e.clientY - r.top;\n    let best = -1, bd = 64;                                              // 8px 以内で最も近い点\n    for (let i = 0; i < pts.length; i++) { const d = (pts[i].x - x) ** 2 + (pts[i].y - y) ** 2; if (d < bd) { bd = d; best = i; } }\n    if (best !== hover) { hover = best; draw(); }\n  });\n  new ResizeObserver(resize).observe(c);\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n56","title":"56データグリッド操作 セル範囲選択 / 列幅変更 / フィルハンドル / 貼り付け","what":"業務アプリの中核。Excel の作法をどこまで再現するかで使い勝手が決まる。ここでは4つ：①ドラッグでセル範囲選択 ②列見出しの境界ドラッグで列幅変更 ③選択範囲右下の■を下にドラッグで値を埋める ④Excelからコピーした表を Ctrl+V で流し込む（TSV解析）。","how":"操作：セルをドラッグ、列境界をドラッグ、右下■を下へドラッグ、Excel等の表をコピーしてグリッド上で貼り付け。","html":"<div class=\"stage\">\n    <div class=\"row\"><span class=\"readout\" id=\"s56-out\">-</span></div>\n    <div id=\"s56-wrap\" class=\"s56-wrap\" tabindex=\"0\"><table id=\"s56-t\" class=\"s56\"></table><div id=\"s56-fill\" class=\"s56-fill\" hidden></div></div>\n  </div>","css":".s56-wrap { position: relative; overflow: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; outline: none; user-select: none; }\n.s56 { border-collapse: collapse; font-size: 13px; table-layout: fixed; }\n.s56 th, .s56 td { border: 1px solid #e5e7eb; padding: 3px 8px; overflow: hidden; white-space: nowrap; position: relative; }\n.s56 th { background: #f1f5f9; font-weight: 600; }\n.s56 th .rs { position: absolute; right: 0; top: 0; bottom: 0; width: 6px; cursor: col-resize; touch-action: none; }\n.s56 td.sel { background: var(--accent-soft); }\n.s56-fill { position: absolute; width: 8px; height: 8px; background: var(--accent); cursor: crosshair; touch-action: none; }","js":"(() => {\n  const wrap = $('#s56-wrap'), t = $('#s56-t'), fill = $('#s56-fill'), out = $('#s56-out');\n  const COLS = ['品番', '品名', '数量', '単価'], data = Array.from({ length: 6 }, (_, r) => [`P-${100 + r}`, `部品${r + 1}`, String((r + 1) * 10), '250']);\n  let sel = null; // {r1,c1,r2,c2}\n  const render = () => {\n    t.innerHTML = '<tr>' + COLS.map((c, i) => `<th style=\"width:${[80, 120, 70, 70][i]}px\">${c}<span class=\"rs\" data-c=\"${i}\"></span></th>`).join('') + '</tr>' +\n      data.map((row, r) => '<tr>' + row.map((v, c) => `<td data-r=\"${r}\" data-c=\"${c}\">${v}</td>`).join('') + '</tr>').join('');\n    paintSel();\n  };\n  const norm = s => ({ r1: Math.min(s.r1, s.r2), r2: Math.max(s.r1, s.r2), c1: Math.min(s.c1, s.c2), c2: Math.max(s.c1, s.c2) });\n  const paintSel = () => {\n    $$('td', t).forEach(td => td.classList.remove('sel')); fill.hidden = !sel; if (!sel) return;\n    const n = norm(sel);\n    $$('td', t).forEach(td => { const r = +td.dataset.r, c = +td.dataset.c; if (r >= n.r1 && r <= n.r2 && c >= n.c1 && c <= n.c2) td.classList.add('sel'); });\n    const last = $(`td[data-r=\"${n.r2}\"][data-c=\"${n.c2}\"]`, t);\n    fill.style.left = last.offsetLeft + last.offsetWidth - 5 + 'px'; fill.style.top = last.offsetTop + last.offsetHeight - 5 + 'px';\n    out.textContent = `選択: R${n.r1 + 1}C${n.c1 + 1} 〜 R${n.r2 + 1}C${n.c2 + 1}`;\n  };\n  let mode = null;\n  wrap.addEventListener('pointerdown', e => {\n    const td = e.target.closest('td');\n    if (e.target.classList.contains('rs')) { const th = e.target.parentElement; mode = { type: 'resize', th, x: e.clientX, w: th.offsetWidth }; }\n    else if (e.target === fill) { mode = { type: 'fill', from: norm(sel) }; }\n    else if (td) { sel = { r1: +td.dataset.r, c1: +td.dataset.c, r2: +td.dataset.r, c2: +td.dataset.c }; mode = { type: 'select' }; paintSel(); }\n    if (mode) wrap.setPointerCapture(e.pointerId);\n    wrap.focus();\n  });\n  wrap.addEventListener('pointermove', e => {\n    if (!mode) return;\n    const td = document.elementFromPoint(e.clientX, e.clientY)?.closest('td');\n    if (mode.type === 'resize') mode.th.style.width = Math.max(40, mode.w + e.clientX - mode.x) + 'px';\n    else if (mode.type === 'select' && td) { sel.r2 = +td.dataset.r; sel.c2 = +td.dataset.c; paintSel(); }\n    else if (mode.type === 'fill' && td) { sel = { ...mode.from, r2: Math.max(mode.from.r2, +td.dataset.r) }; paintSel(); }\n  });\n  wrap.addEventListener('pointerup', () => {\n    if (mode?.type === 'fill') {                                            // 選択範囲の最終行の値を下へコピー\n      const f = mode.from, n = norm(sel);\n      for (let r = f.r2 + 1; r <= n.r2; r++) for (let c = f.c1; c <= f.c2; c++) data[r][c] = data[f.r2][c];\n      render();\n    }\n    mode = null;\n  });\n  wrap.addEventListener('paste', e => {                                     // Excel → TSV\n    if (!sel) return; e.preventDefault();\n    const rows = e.clipboardData.getData('text/plain').replace(/\\r/g, '').split('\\n').filter(Boolean).map(l => l.split('\\t'));\n    const n = norm(sel);\n    rows.forEach((row, i) => row.forEach((v, j) => { if (data[n.r1 + i] && n.c1 + j < COLS.length) data[n.r1 + i][n.c1 + j] = v; }));\n    sel = { r1: n.r1, c1: n.c1, r2: Math.min(data.length - 1, n.r1 + rows.length - 1), c2: Math.min(COLS.length - 1, n.c1 + rows[0].length - 1) };\n    render(); out.textContent += `（${rows.length}行貼り付け）`;\n  });\n  render();\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n57","title":"57楽観的更新 Optimistic UI","what":"サーバ応答を待たずに画面を先に更新し、失敗したら元に戻す。kintone の PUT /k/v1/record.json のような更新系で、体感の遅さを消す。ロールバックとエラー通知が必須。","how":"操作：チェックを切り替える（即反映）。「失敗させる」をONにすると 1.2秒後に巻き戻る。","html":"<div class=\"stage\">\n    <div class=\"row\"><label><input type=\"checkbox\" id=\"s57-fail\"> API を失敗させる</label><span class=\"readout\" id=\"s57-out\">-</span></div>\n    <div id=\"s57-list\" class=\"s57-list\"></div>\n  </div>","css":".s57-list label { display: flex; gap: 8px; padding: 6px 10px; background: #fff; border: 1px solid #e5e7eb; border-radius: 6px; margin-bottom: 4px; font-size: 13px; }\n.s57-list label.pending { opacity: .6; }\n.s57-list label.error { border-color: #dc2626; background: #fef2f2; }","js":"(() => {\n  const list = $('#s57-list'), out = $('#s57-out');\n  const items = [{ id: 1, name: '図面確認', done: true }, { id: 2, name: '材料手配', done: false }, { id: 3, name: '治具準備', done: false }];\n  const fakeApi = (id, done) => new Promise((ok, ng) => setTimeout(() => $('#s57-fail').checked ? ng(new Error('500')) : ok(), 1200));\n  const render = () => list.innerHTML = items.map(i => `<label data-id=\"${i.id}\" class=\"${i.state || ''}\"><input type=\"checkbox\" ${i.done ? 'checked' : ''}> ${i.name}</label>`).join('');\n  list.addEventListener('change', async e => {\n    const item = items.find(i => i.id === +e.target.closest('label').dataset.id);\n    const prev = item.done;\n    item.done = e.target.checked; item.state = 'pending'; render();        // ① 先に画面を更新\n    out.textContent = `#${item.id} を送信中…（画面は更新済み）`;\n    try { await fakeApi(item.id, item.done); item.state = ''; out.textContent = `#${item.id} 保存成功`; }\n    catch (err) { item.done = prev; item.state = 'error'; out.textContent = `#${item.id} 失敗 → 元に戻しました (${err.message})`; } // ② 失敗なら巻き戻す\n    render();\n  });\n  render();\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n58","title":"58フォーカス管理 / ライブリージョン Focus trap / inert / aria-live","what":"自作モーダルでは3つ必要：①開いたら中にフォーカスを移す ②背面を inert にして Tab が抜けないようにする ③閉じたら元の要素へフォーカスを戻す。非同期の結果は aria-live 領域に書くと読み上げソフトが通知する。","how":"操作：開いて Tab を連打（外に出ない）→ 閉じると「開く」ボタンにフォーカスが戻る。","html":"<div class=\"stage\" style=\"min-height:160px\">\n    <div id=\"s58-main\">\n      <div class=\"row\"><button id=\"s58-open\">自作モーダルを開く</button><button>背面のボタン（開いている間は inert）</button></div>\n      <div id=\"s58-live\" aria-live=\"polite\" class=\"readout\">（ここが aria-live 領域）</div>\n    </div>\n    <div id=\"s58-modal\" class=\"s58-modal\" role=\"dialog\" aria-modal=\"true\" hidden>\n      <div class=\"s58-panel\"><b>自作モーダル</b><div class=\"row\" style=\"margin-top:8px\"><input type=\"text\" placeholder=\"項目\"><button id=\"s58-save\">保存</button><button id=\"s58-close\">閉じる</button></div></div>\n    </div>\n  </div>","css":".s58-modal { position: absolute; inset: 0; background: rgba(15,23,42,.4); display: grid; place-items: center; }\n.s58-modal[hidden] { display: none; }  /* display を指定すると hidden 属性が負けるので明示する */\n.s58-panel { background: #fff; padding: 16px; border-radius: 10px; width: 300px; }\n.s58-panel :focus-visible { outline: 3px solid #f59e0b; }","js":"(() => {\n  const main = $('#s58-main'), modal = $('#s58-modal'), live = $('#s58-live');\n  let opener = null;\n  const open = () => { opener = document.activeElement; modal.hidden = false; main.inert = true; $('input', modal).focus(); };  // ①②\n  const close = () => { modal.hidden = true; main.inert = false; opener?.focus(); };                                         // ③\n  $('#s58-open').onclick = open; $('#s58-close').onclick = close;\n  modal.addEventListener('keydown', e => e.key === 'Escape' && close());\n  $('#s58-save').onclick = () => { close(); live.textContent = `保存しました（${new Date().toLocaleTimeString()}）← 読み上げ対象`; };\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n59","title":"59ファイルドロップ File drop / DataTransfer","what":"OSのエクスプローラからファイルをドラッグして受け取る。dragover で preventDefault() しないとブラウザがファイルを開いてしまう。ドロップ領域のハイライトと、種別・サイズの検証をここで行う。","how":"操作：デスクトップからファイルを枠に落とす（クリックで選択も可）。","html":"<div class=\"stage\">\n    <div id=\"s59-zone\" class=\"s59-zone\">ここにファイルをドロップ（またはクリック）<input id=\"s59-input\" type=\"file\" multiple hidden></div>\n    <div class=\"log\" id=\"s59-log\"></div>\n  </div>","css":".s59-zone { border: 2px dashed #94a3b8; border-radius: 8px; padding: 24px; text-align: center; color: var(--muted); cursor: pointer; margin-bottom: 8px; }\n.s59-zone.over { border-color: var(--accent); background: var(--accent-soft); color: var(--accent); }","js":"(() => {\n  const zone = $('#s59-zone'), input = $('#s59-input'), log = $('#s59-log');\n  const accept = files => [...files].forEach(f => {\n    const ok = f.size < 5 * 1024 * 1024;                                       // 検証例：5MB 未満\n    logTo(log, `${ok ? '✔' : '✖'} ${f.name}  ${(f.size / 1024).toFixed(1)} KB  ${f.type || '(type不明)'}` + (ok ? '' : '  → サイズ超過'));\n  });\n  zone.addEventListener('dragover', e => { e.preventDefault(); zone.classList.add('over'); }); // ← 必須\n  zone.addEventListener('dragleave', () => zone.classList.remove('over'));\n  zone.addEventListener('drop', e => { e.preventDefault(); zone.classList.remove('over'); accept(e.dataTransfer.files); });\n  zone.addEventListener('click', () => input.click());\n  input.addEventListener('change', () => accept(input.files));\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n60","title":"60コンテナクエリ Container queries","what":"画面幅ではなく「自分が置かれた枠の幅」でレイアウトを切り替える。同じカード部品を、広いメイン領域では横並び、狭いサイドパネルでは縦積みにできる。ドッキングレイアウト（33）の中身に必須。","how":"操作：枠の右下をドラッグして幅を変える。420px を境にカード内のレイアウトが変わる。","html":"<div class=\"stage\">\n    <div id=\"s60-box\" class=\"s60-box\">\n      <div class=\"s60-card\"><div class=\"s60-img\"></div><div><b>受注 #1001</b><p>株式会社サンプル / 納期 2026-09-12 / 数量 120</p></div></div>\n      <span class=\"readout\" id=\"s60-out\"></span>\n    </div>\n  </div>","css":".s60-box { container-type: inline-size; resize: horizontal; overflow: auto; width: 520px; max-width: 100%; min-width: 200px; padding: 10px; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; }\n.s60-card { display: flex; gap: 12px; align-items: center; font-size: 13px; } .s60-card p { margin: 2px 0 0; color: var(--muted); }\n.s60-img { flex: 0 0 90px; height: 60px; background: var(--accent); border-radius: 6px; }\n@container (max-width: 420px) {\n  .s60-card { flex-direction: column; align-items: stretch; }   /* 枠が狭ければ縦積み */\n  .s60-img { flex-basis: auto; height: 40px; }\n}","js":"(() => {\n  const box = $('#s60-box'), out = $('#s60-out');\n  new ResizeObserver(([e]) => out.textContent = `枠の幅: ${Math.round(e.contentRect.width)}px → ${e.contentRect.width <= 420 ? '縦積み' : '横並び'}`).observe(box);\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n61","title":"61Electron：フレームレスウィンドウの操作 -webkit-app-region","what":"OS標準のタイトルバーを消して自前のヘッダーを作る場合、「ここを掴んだらウィンドウごと動く」領域を CSS で宣言する。ボタンなど押したい要素は no-drag で除外しないとクリックできなくなる。ブラウザでは効かないため、ここでは同じCSSを当てたモック（枠内でウィンドウを動かす模擬）を置いている。","how":"操作：模擬ウィンドウのタイトルバーをドラッグ（Electron では本物のウィンドウが動く）。ボタン部分は掴めない。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div class=\"s61-desktop\">\n      <div id=\"s61-win\" class=\"s61-win\">\n        <div class=\"s61-titlebar\" id=\"s61-tb\"><span>Mission Bridge</span><span class=\"s61-btns\"><button>—</button><button>▢</button><button>✕</button></span></div>\n        <div class=\"s61-body\">frameless window（模擬）</div>\n      </div>\n    </div>\n  </div>","css":"/* Electron の renderer にそのまま使える CSS */\n.s61-titlebar { -webkit-app-region: drag; }            /* ここを掴むとウィンドウが動く */\n.s61-titlebar button { -webkit-app-region: no-drag; }  /* ボタンは除外（さもないと押せない） */\n\n/* 以下はこのページ用の見た目・模擬 */\n.s61-desktop { position: relative; height: 280px; background: #334155; overflow: hidden; }\n.s61-win { position: absolute; left: 60px; top: 40px; width: 360px; background: #fff; border-radius: 8px; box-shadow: 0 20px 40px rgba(0,0,0,.4); overflow: hidden; }\n.s61-titlebar { display: flex; justify-content: space-between; align-items: center; padding: 6px 10px; background: #0f172a; color: #fff; font-size: 13px; cursor: default; user-select: none; touch-action: none; }\n.s61-btns button { background: none; border: none; color: #fff; padding: 2px 8px; }\n.s61-body { padding: 24px; font-size: 13px; color: var(--muted); }","js":"(() => {\n  const win = $('#s61-win'), tb = $('#s61-tb'); let d = null;\n  tb.addEventListener('pointerdown', e => { if (e.target.tagName === 'BUTTON') return; d = { x: e.clientX - win.offsetLeft, y: e.clientY - win.offsetTop }; tb.setPointerCapture(e.pointerId); });\n  tb.addEventListener('pointermove', e => { if (d) { win.style.left = e.clientX - d.x + 'px'; win.style.top = e.clientY - d.y + 'px'; } });\n  tb.addEventListener('pointerup', () => d = null);\n})();"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n62","title":"62Electron：ネイティブメニュー / ショートカット Menu / accelerator / IPC","what":"OSのメニューバー（ファイル・編集…）とショートカットはメインプロセスで定義し、押されたら IPC で renderer に通知する。renderer 側は「メニューから来た」「ボタンから来た」を区別せず同じ関数を呼ぶ設計にする。ブラウザでは動かないため、下のボタンで「メニューが押された通知が来た」状況を模擬している。","how":"操作：「メニュー: 新規作成 を模擬」を押すと、renderer の受信ハンドラが動く。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s62-sim\">メニュー: 新規作成 を模擬（Ctrl+N）</button><button id=\"s62-btn\">画面のボタンから新規作成</button></div>\n    <div class=\"log\" id=\"s62-log\"></div>\n  </div>","css":"","js":"(() => {\n  const log = $('#s62-log');\n  const createNew = from => logTo(log, `新規作成を実行（呼び出し元: ${from}）`);\n  // Electron では: window.api.onMenu('new', () => createNew('メニュー'));\n  // ブラウザ模擬: ボタンで同じハンドラを呼ぶ\n  const api = window.api || { onMenu: (name, h) => $('#s62-sim').addEventListener('click', h) };\n  api.onMenu('new', () => createNew('メニュー / Ctrl+N'));\n  $('#s62-btn').onclick = () => createNew('画面のボタン');\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n71","title":"71大規模グリッドの複合 仮想スクロール＋固定列＋列並べ替え＋範囲コピー","what":"数千〜数万行を扱う一覧の完成形。①行は仮想化（23）②先頭列は固定（24）③見出しをドラッグで列順変更（32の応用）④セル範囲をドラッグ選択して Ctrl+C でTSVとしてコピー（Excelにそのまま貼れる）。データは列順とは独立に保持し、表示時に「列順の配列」を通して並べる。","how":"操作：スクロール／見出しをドラッグして列を入れ替え／セルをドラッグ選択して Ctrl+C。コピー内容は下に表示。","html":"<div class=\"stage\">\n    <div class=\"row\"><span class=\"readout\" id=\"s71-out\">-</span></div>\n    <div id=\"s71-view\" class=\"s71-view\" tabindex=\"0\">\n      <div id=\"s71-head\" class=\"s71-head\"></div>\n      <div id=\"s71-spacer\"><div id=\"s71-rows\"></div></div>\n    </div>\n    <textarea id=\"s71-clip\" class=\"s71-clip\" readonly placeholder=\"Ctrl+C でコピーした TSV がここに表示される\"></textarea>\n  </div>","css":".s71-view { position: relative; height: 240px; overflow: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; outline: none; user-select: none; font-size: 12.5px; }\n.s71-head { position: sticky; top: 0; z-index: 3; display: flex; background: #f1f5f9; border-bottom: 1px solid #cbd5e1; width: max-content; min-width: 100%; }\n.s71-head div { flex: 0 0 110px; padding: 4px 8px; font-weight: 600; cursor: grab; border-right: 1px solid #e5e7eb; box-sizing: border-box; }\n.s71-head div.drag { opacity: .5; }\n.s71-head div.over { box-shadow: inset 3px 0 0 var(--accent); }\n.s71-head div:first-child, .s71-row div:first-child { position: sticky; left: 0; z-index: 2; background: #f8fafc; cursor: default; }\n.s71-row { display: flex; height: 26px; line-height: 26px; width: max-content; min-width: 100%; }\n.s71-row div { flex: 0 0 110px; padding: 0 8px; border-right: 1px solid #f1f5f9; border-bottom: 1px solid #f1f5f9; white-space: nowrap; overflow: hidden; box-sizing: border-box; }\n.s71-row div.sel { background: var(--accent-soft); }\n.s71-clip { width: 100%; height: 60px; margin-top: 6px; font: 12px ui-monospace, monospace; }","js":"(() => {\n  const ROWS = 5000, H = 26, COLS = ['品番', '品名', '在庫', '単価', '納期', '担当', '拠点', '備考'];\n  const data = Array.from({ length: ROWS }, (_, r) => [`P-${String(r + 1).padStart(5, '0')}`, `部品${r + 1}`, String((r * 37) % 500), String(100 + (r % 9) * 50), `2026-10-${String(r % 28 + 1).padStart(2, '0')}`, ['佐藤', '鈴木', '高橋'][r % 3], ['本社', '第2工場'][r % 2], r % 7 === 0 ? '要確認' : '']);\n  let order = COLS.map((_, i) => i);           // 表示上の列順（データ側は不変）\n  const view = $('#s71-view'), head = $('#s71-head'), spacer = $('#s71-spacer'), rows = $('#s71-rows'), out = $('#s71-out'), clip = $('#s71-clip');\n  spacer.style.height = ROWS * H + 'px';\n  let sel = null; // {r1,c1,r2,c2} c は「表示上の列位置」\n  const norm = s => ({ r1: Math.min(s.r1, s.r2), r2: Math.max(s.r1, s.r2), c1: Math.min(s.c1, s.c2), c2: Math.max(s.c1, s.c2) });\n  const inSel = (r, c) => { if (!sel) return false; const n = norm(sel); return r >= n.r1 && r <= n.r2 && c >= n.c1 && c <= n.c2; };\n  const renderHead = () => head.innerHTML = order.map((ci, pos) => `<div draggable=\"false\" data-pos=\"${pos}\">${COLS[ci]}</div>`).join('');\n  const render = () => {\n    const start = Math.floor(view.scrollTop / H), count = Math.ceil(view.clientHeight / H) + 2;\n    rows.style.transform = `translateY(${start * H}px)`;\n    let html = '';\n    for (let r = start; r < Math.min(start + count, ROWS); r++)\n      html += `<div class=\"s71-row\" data-r=\"${r}\">` + order.map((ci, pos) => `<div data-c=\"${pos}\" class=\"${inSel(r, pos) ? 'sel' : ''}\">${data[r][ci]}</div>`).join('') + '</div>';\n    rows.innerHTML = html;\n    out.textContent = `${ROWS.toLocaleString()} 行 / DOM ${rows.children.length} 行 / 列順 [${order.map(i => COLS[i]).join(',')}]` + (sel ? ` / 選択 ${norm(sel).r2 - norm(sel).r1 + 1}×${norm(sel).c2 - norm(sel).c1 + 1}` : '');\n  };\n  view.addEventListener('scroll', render);\n  // 列の並べ替え（見出しドラッグ）\n  let hdrag = null;\n  head.addEventListener('pointerdown', e => { const h = e.target.closest('[data-pos]'); if (!h || h.dataset.pos === '0') return; hdrag = { from: +h.dataset.pos, el: h }; h.classList.add('drag'); head.setPointerCapture(e.pointerId); });\n  head.addEventListener('pointermove', e => { if (!hdrag) return; const t = document.elementFromPoint(e.clientX, e.clientY)?.closest('[data-pos]'); $$('div', head).forEach(d => d.classList.toggle('over', d === t && t !== hdrag.el)); });\n  head.addEventListener('pointerup', e => {\n    if (!hdrag) return;\n    const t = document.elementFromPoint(e.clientX, e.clientY)?.closest('[data-pos]');\n    if (t && +t.dataset.pos !== hdrag.from && t.dataset.pos !== '0') { const [m] = order.splice(hdrag.from, 1); order.splice(+t.dataset.pos, 0, m); sel = null; }\n    hdrag = null; renderHead(); render();\n  });\n  // 範囲選択\n  let selecting = false;\n  const cellAt = e => { const c = document.elementFromPoint(e.clientX, e.clientY)?.closest('[data-c]'); const row = c?.closest('[data-r]'); return row ? { r: +row.dataset.r, c: +c.dataset.c } : null; };\n  rows.addEventListener('pointerdown', e => { const p = cellAt(e); if (!p) return; sel = { r1: p.r, c1: p.c, r2: p.r, c2: p.c }; selecting = true; view.setPointerCapture(e.pointerId); render(); });\n  view.addEventListener('pointermove', e => { if (!selecting) return; const p = cellAt(e); if (p) { sel.r2 = p.r; sel.c2 = p.c; render(); } });\n  view.addEventListener('pointerup', () => selecting = false);\n  // Ctrl+C → TSV（DOMに無い行もデータから直接組み立てる）\n  view.addEventListener('keydown', e => {\n    if (!sel || !(e.ctrlKey || e.metaKey) || e.key.toLowerCase() !== 'c') return;\n    e.preventDefault(); const n = norm(sel); const lines = [];\n    for (let r = n.r1; r <= n.r2; r++) lines.push(order.slice(n.c1, n.c2 + 1).map(ci => data[r][ci]).join('\\t'));\n    const tsv = lines.join('\\n'); clip.value = tsv;\n    navigator.clipboard?.writeText(tsv).catch(() => {}); // file:// では失敗することがあるので表示も残す\n  });\n  renderHead(); render();\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n74","title":"74検索の型 インクリメンタル / デバウンス / ハイライト / あいまい検索","what":"入力のたびに検索するが、①デバウンス（打鍵が止まって250ms後に実行）で無駄な処理を省き、②一致箇所を &lt;mark&gt; で強調し、③あいまい検索は「文字が順番に現れるか」をスコア化して並べる（先頭一致・連続一致を高得点に）。kintone API へ投げる場合もデバウンスは必須。","how":"操作：「部品12」「p12鈴」「高橋 倉庫」などを入力。「p12鈴」は部分一致では0件、あいまいでは「P-0012 部品12 鈴木…」が上位に来る。","html":"<div class=\"stage\">\n    <div class=\"row\"><input id=\"s74-q\" type=\"search\" placeholder=\"検索…\" style=\"width:220px\"><label><input type=\"radio\" name=\"s74\" value=\"sub\" checked> 部分一致</label><label><input type=\"radio\" name=\"s74\" value=\"fuzzy\"> あいまい（スコア順）</label><span class=\"readout\" id=\"s74-out\">-</span></div>\n    <div id=\"s74-list\" class=\"s74-list\"></div>\n  </div>","css":".s74-list { height: 170px; overflow: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 13px; }\n.s74-list div { padding: 3px 10px; border-bottom: 1px solid #f1f5f9; display: flex; justify-content: space-between; }\n.s74-list mark { background: #fde68a; padding: 0; }\n.s74-list small { color: var(--muted); }","js":"(() => {\n  const N = 3000, recs = Array.from({ length: N }, (_, i) => `P-${String(i + 1).padStart(4, '0')} 部品${i + 1} ${['佐藤', '鈴木', '高橋'][i % 3]} ${['本社', '第2工場', '倉庫'][i % 3]}`);\n  const q = $('#s74-q'), list = $('#s74-list'), out = $('#s74-out');\n  const debounce = (fn, ms) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };\n  const esc = s => s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));\n  // 部分一致：位置で <mark>\n  const sub = (text, needle) => { const i = text.toLowerCase().indexOf(needle); return i < 0 ? null : { score: 1000 - i, html: esc(text.slice(0, i)) + '<mark>' + esc(text.slice(i, i + needle.length)) + '</mark>' + esc(text.slice(i + needle.length)) }; };\n  // あいまい：文字を順に探し、連続・先頭で加点\n  const fuzzy = (text, needle) => {\n    const t = text.toLowerCase(); let ti = 0, score = 0, prev = -2, html = '';\n    for (const ch of needle) {\n      const i = t.indexOf(ch, ti); if (i < 0) return null;\n      score += (i === prev + 1 ? 8 : 1) + (i === 0 ? 10 : 0) - (i - ti) * 0.1; // 連続+8、先頭+10、飛び越し減点\n      html += esc(text.slice(ti, i)) + '<mark>' + esc(text[i]) + '</mark>'; prev = i; ti = i + 1;\n    }\n    return { score: score - text.length * 0.01, html: html + esc(text.slice(ti)) };  // 同点なら短い方を上に\n  };\n  const run = () => {\n    const needle = q.value.trim().toLowerCase(), t0 = performance.now();\n    const mode = $('input[name=s74]:checked').value;\n    if (!needle) { list.innerHTML = recs.slice(0, 50).map(r => `<div>${esc(r)}</div>`).join(''); out.textContent = `全 ${N} 件（先頭50表示）`; return; }\n    const hits = [];\n    for (const r of recs) { const m = (mode === 'sub' ? sub : fuzzy)(r, needle); if (m) hits.push({ ...m, r }); }\n    hits.sort((a, b) => b.score - a.score);\n    list.innerHTML = hits.slice(0, 100).map(h => `<div><span>${h.html}</span><small>${h.score.toFixed(1)}</small></div>`).join('') || '<div style=\"color:#6b7280\">該当なし</div>';\n    out.textContent = `${hits.length} 件 / ${(performance.now() - t0).toFixed(1)}ms（上位100表示）`;\n  };\n  const runDebounced = debounce(run, 250);\n  // 日本語入力の変換中（isComposing）は走らせない。確定した瞬間に1回だけ実行する（108 章の 107 参照）\n  q.addEventListener('input', e => { if (!e.isComposing) runDebounced(); });\n  q.addEventListener('compositionend', () => runDebounced());\n  $$('input[name=s74]').forEach(r => r.addEventListener('change', run));\n  run();\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n75","title":"75フォームの型 ステッパー / 条件分岐 / 途中保存 / 離脱警告","what":"長い入力を①段階に分け（ステッパー）②回答に応じて項目を出し分け（条件分岐）③入力のたびに下書きを保存し（localStorage）④未保存のまま離れようとしたら警告する（beforeunload）。状態は「1つのオブジェクト」に集約し、画面はそれを描画するだけにすると分岐が破綻しない。","how":"操作：入力して次へ。「分納あり」を選ぶと項目が増える。ページを再読込しても下書きが復元される。入力途中でタブを閉じようとすると警告が出る。","html":"<div class=\"stage\">\n    <div class=\"s75-steps\" id=\"s75-steps\"></div>\n    <div id=\"s75-body\" class=\"s75-body\"></div>\n    <div class=\"row\"><button id=\"s75-prev\">← 戻る</button><button id=\"s75-next\" class=\"primary\">次へ →</button><button id=\"s75-clear\">下書きを破棄</button><span class=\"readout\" id=\"s75-out\">-</span></div>\n  </div>","css":".s75-steps { display: flex; gap: 6px; margin-bottom: 10px; font-size: 12px; }\n.s75-steps span { flex: 1; padding: 4px 8px; border-radius: 4px; background: #e2e8f0; text-align: center; }\n.s75-steps span.on { background: var(--accent); color: #fff; } .s75-steps span.done { background: #bbf7d0; }\n.s75-body { background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 12px; margin-bottom: 8px; font-size: 13px; min-height: 90px; }\n.s75-body label { display: block; margin-bottom: 6px; } .s75-body input[type=text], .s75-body select { margin-left: 6px; }\n.s75-body .err { color: #dc2626; font-size: 12px; }","js":"(() => {\n  const KEY = 'ui-guide.s75.draft';\n  const STEPS = ['顧客', '納品', '確認'];\n  let form = { step: 0, customer: '', qty: '', split: 'no', splitCount: '', note: '' };\n  let dirty = false;\n  try { Object.assign(form, JSON.parse(localStorage.getItem(KEY) || '{}')); } catch {}   // 復元\n  const steps = $('#s75-steps'), body = $('#s75-body'), out = $('#s75-out');\n  const save = () => { localStorage.setItem(KEY, JSON.stringify(form)); out.textContent = `下書き保存 ${new Date().toLocaleTimeString()}`; };\n  const validate = () => form.step === 0 && !form.customer ? '顧客名は必須' : form.step === 1 && !(+form.qty > 0) ? '数量は1以上' : form.step === 1 && form.split === 'yes' && !(+form.splitCount > 1) ? '分納回数は2以上' : '';\n  const render = () => {\n    steps.innerHTML = STEPS.map((s, i) => `<span class=\"${i === form.step ? 'on' : i < form.step ? 'done' : ''}\">${i + 1}. ${s}</span>`).join('');\n    body.innerHTML = [\n      `<label>顧客名 <input type=\"text\" data-k=\"customer\" value=\"${form.customer}\"></label><label>備考 <input type=\"text\" data-k=\"note\" value=\"${form.note}\"></label>`,\n      `<label>数量 <input type=\"text\" data-k=\"qty\" value=\"${form.qty}\"></label>\n       <label>分納 <select data-k=\"split\"><option value=\"no\" ${form.split === 'no' ? 'selected' : ''}>なし</option><option value=\"yes\" ${form.split === 'yes' ? 'selected' : ''}>あり</option></select></label>\n       ${form.split === 'yes' ? `<label>分納回数 <input type=\"text\" data-k=\"splitCount\" value=\"${form.splitCount}\"></label>` : ''}`,   // ← 条件分岐\n      `<b>確認</b><br>顧客: ${form.customer} / 数量: ${form.qty} / 分納: ${form.split === 'yes' ? form.splitCount + '回' : 'なし'} / 備考: ${form.note || '-'}<br><br><button id=\"s75-submit\" class=\"primary\">送信</button>`\n    ][form.step] + `<div class=\"err\" id=\"s75-err\"></div>`;\n    $('#s75-prev').disabled = form.step === 0; $('#s75-next').hidden = form.step === 2;\n    $('#s75-submit')?.addEventListener('click', () => { localStorage.removeItem(KEY); dirty = false; form = { step: 0, customer: '', qty: '', split: 'no', splitCount: '', note: '' }; out.textContent = '送信完了（下書き削除）'; render(); });\n  };\n  // check-ime-ignore : 下書き保存のみ。未確定の文字が一時的に保存されても確定時に上書きされる\n  body.addEventListener('input', e => { const k = e.target.dataset.k; if (!k) return; form[k] = e.target.value; dirty = true; save(); if (k === 'split') render(); });\n  $('#s75-next').onclick = () => { const err = validate(); if (err) { $('#s75-err').textContent = err; return; } form.step++; save(); render(); };\n  $('#s75-prev').onclick = () => { form.step--; save(); render(); };\n  $('#s75-clear').onclick = () => { localStorage.removeItem(KEY); dirty = false; form = { step: 0, customer: '', qty: '', split: 'no', splitCount: '', note: '' }; out.textContent = '破棄'; render(); };\n  window.addEventListener('beforeunload', e => { if (dirty) { e.preventDefault(); e.returnValue = ''; } });  // 離脱警告（文言はブラウザ固定）\n  render(); if (localStorage.getItem(KEY)) out.textContent = '下書きを復元しました';\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n76","title":"76バッチ操作UI 複数選択 → 一括変更 → プレビュー → 確定 → 進捗と部分失敗","what":"一括更新は「取り消しにくい」ので、確定前にプレビュー（何が何に変わるか）を必ず見せる。実行中は進捗を出し、一部失敗しても止めずに完走させ、最後に「失敗分だけ再試行」を提供する。kintone の PUT /k/v1/records.json（100件上限）に合わせてチャンク分割する形。","how":"操作：行をチェック → ステータスを選ぶ → プレビュー → 実行。約20%が失敗するので再試行を試す。","html":"<div class=\"stage\">\n    <div class=\"row\"><label><input type=\"checkbox\" id=\"s76-all\"> 全選択</label><select id=\"s76-status\"><option value=\"\">変更後ステータス…</option><option>受注</option><option>製造中</option><option>出荷済</option></select><button id=\"s76-preview\">プレビュー</button><span class=\"readout\" id=\"s76-out\">-</span></div>\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <table class=\"mini\" id=\"s76-t\" style=\"flex:1\"></table>\n      <div id=\"s76-panel\" style=\"flex:1;font-size:13px\"></div>\n    </div>\n  </div>","css":"","js":"(() => {\n  const recs = Array.from({ length: 8 }, (_, i) => ({ id: 1001 + i, name: `受注 #${1001 + i}`, status: ['受注', '製造中', '受注', '出荷済'][i % 4] }));\n  const t = $('#s76-t'), panel = $('#s76-panel'), out = $('#s76-out'), sel = new Set();\n  const fakeUpdate = rec => new Promise((ok, ng) => setTimeout(() => Math.random() < 0.2 ? ng(new Error('timeout')) : ok(), 150 + Math.random() * 200));\n  const render = () => t.innerHTML = '<tr><th></th><th>ID</th><th>名称</th><th>ステータス</th></tr>' + recs.map(r => `<tr><td><input type=\"checkbox\" data-id=\"${r.id}\" ${sel.has(r.id) ? 'checked' : ''}></td><td>${r.id}</td><td>${r.name}</td><td>${r.status}</td></tr>`).join('');\n  t.addEventListener('change', e => { const id = +e.target.dataset.id; e.target.checked ? sel.add(id) : sel.delete(id); out.textContent = `${sel.size} 件選択`; });\n  $('#s76-all').onchange = e => { recs.forEach(r => e.target.checked ? sel.add(r.id) : sel.delete(r.id)); render(); out.textContent = `${sel.size} 件選択`; };\n  $('#s76-preview').onclick = () => {\n    const to = $('#s76-status').value; if (!to || !sel.size) { out.textContent = '選択とステータスが必要'; return; }\n    const changes = recs.filter(r => sel.has(r.id) && r.status !== to).map(r => ({ r, from: r.status, to }));\n    panel.innerHTML = `<b>プレビュー（${changes.length} 件が変わる、${sel.size - changes.length} 件は変更なし）</b><table class=\"mini\">` + changes.map(c => `<tr><td>${c.r.name}</td><td>${c.from}</td><td>→</td><td>${c.to}</td></tr>`).join('') + `</table><div class=\"row\" style=\"margin-top:6px\"><button id=\"s76-run\" class=\"primary\">実行</button></div><progress id=\"s76-p\" max=\"${changes.length}\" value=\"0\" style=\"width:100%\" hidden></progress><div id=\"s76-res\"></div>`;\n    $('#s76-run').onclick = () => run(changes);\n  };\n  async function run(changes) {\n    const p = $('#s76-p'), res = $('#s76-res'); p.hidden = false; p.value = 0; $('#s76-run').disabled = true;\n    const failed = [];\n    const CHUNK = 3;                                                     // API上限に合わせて分割\n    for (let i = 0; i < changes.length; i += CHUNK) {\n      const chunk = changes.slice(i, i + CHUNK);\n      await Promise.all(chunk.map(c => fakeUpdate(c.r).then(() => { c.r.status = c.to; }).catch(err => failed.push({ ...c, err }))));\n      p.value = Math.min(changes.length, i + CHUNK); render();\n    }\n    res.innerHTML = `<b>完了：成功 ${changes.length - failed.length} / 失敗 ${failed.length}</b>` + (failed.length ? `<ul style=\"margin:4px 0\">${failed.map(f => `<li>${f.r.name}（${f.err.message}）</li>`).join('')}</ul><button id=\"s76-retry\">失敗分だけ再試行</button>` : '');\n    $('#s76-retry')?.addEventListener('click', () => run(failed.map(f => ({ r: f.r, from: f.from, to: f.to }))));\n  }\n  render();\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n77","title":"77差分表示 変更前後のハイライト / 変更履歴の切替","what":"レコードの版（リビジョン）を並べ、①項目単位で「変更あり」を色分けし、②長文は単語単位の差分（LCS）で削除・追加を示す。kintone の変更履歴を「何がどう変わったか」まで見せる形。差分アルゴリズムは単語配列のLCSで十分（数百語規模なら瞬時）。","how":"操作：比較する版を左右で選ぶ。","html":"<div class=\"stage\">\n    <div class=\"row\">比較元 <select id=\"s77-a\"></select> → 比較先 <select id=\"s77-b\"></select></div>\n    <table class=\"mini\" id=\"s77-t\" style=\"width:100%\"></table>\n  </div>","css":"#s77-t td.chg { background: #fef3c7; }\n#s77-t del { background: #fecaca; text-decoration: line-through; } #s77-t ins { background: #bbf7d0; text-decoration: none; }","js":"(() => {\n  const revs = [\n    { rev: 1, at: '09-01 10:12', by: '佐藤', f: { 顧客: '株式会社サンプル', 数量: '100', 納期: '2026-09-20', 備考: '通常納品。梱包は 標準 仕様で 依頼。' } },\n    { rev: 2, at: '09-02 15:40', by: '鈴木', f: { 顧客: '株式会社サンプル', 数量: '120', 納期: '2026-09-20', 備考: '通常納品。梱包は 強化 仕様で 依頼。分納可。' } },\n    { rev: 3, at: '09-04 09:05', by: '高橋', f: { 顧客: '株式会社サンプル 本社', 数量: '120', 納期: '2026-09-25', 備考: '梱包は 強化 仕様で 依頼。分納可。' } },\n  ];\n  const a = $('#s77-a'), b = $('#s77-b'), t = $('#s77-t');\n  a.innerHTML = b.innerHTML = revs.map(r => `<option value=\"${r.rev}\">rev${r.rev} ${r.at} ${r.by}</option>`).join('');\n  a.value = 1; b.value = 3;\n  const esc = s => s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));\n  // 単語単位の差分（LCS）\n  const wordDiff = (x, y) => {\n    const A = x.split(/(\\s+)/), B = y.split(/(\\s+)/), n = A.length, m = B.length;\n    const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));\n    for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) L[i][j] = A[i] === B[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1]);\n    let i = 0, j = 0, html = '';\n    while (i < n && j < m) {\n      if (A[i] === B[j]) { html += esc(A[i]); i++; j++; }\n      else if (L[i + 1][j] >= L[i][j + 1]) { html += `<del>${esc(A[i])}</del>`; i++; }\n      else { html += `<ins>${esc(B[j])}</ins>`; j++; }\n    }\n    while (i < n) html += `<del>${esc(A[i++])}</del>`; while (j < m) html += `<ins>${esc(B[j++])}</ins>`;\n    return html;\n  };\n  const render = () => {\n    const ra = revs.find(r => r.rev == a.value), rb = revs.find(r => r.rev == b.value);\n    t.innerHTML = '<tr><th>項目</th><th>比較元</th><th>比較先</th><th>差分</th></tr>' + Object.keys(ra.f).map(k => {\n      const chg = ra.f[k] !== rb.f[k];\n      return `<tr><td>${k}</td><td class=\"${chg ? 'chg' : ''}\">${esc(ra.f[k])}</td><td class=\"${chg ? 'chg' : ''}\">${esc(rb.f[k])}</td><td>${chg ? wordDiff(ra.f[k], rb.f[k]) : '<span style=\"color:#9ca3af\">変更なし</span>'}</td></tr>`;\n    }).join('');\n  };\n  a.onchange = b.onchange = render; render();\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n80","title":"80ドッキングレイアウト完成形 タブ移動 / 分割リサイズ / 分離（フローティング） / レイアウト保存","what":"IDE風の骨格。「パネル（内容）」と「ゾーン（置き場所）」を分けて考え、レイアウト状態を1つのJSONで持つ：{ zones: { left:[...], center:[...], right:[...] }, float:[...], widths:[...] }。描画はこのJSONから毎回組み立て直す。保存・復元はJSONを localStorage に入れるだけ。","how":"操作：タブを別ゾーンへドラッグ／境界をドラッグ／タブの「⧉」で分離、フローティングの「⊡」で戻す／「保存」→再読込で復元。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div class=\"row\" style=\"padding:6px 8px;border-bottom:1px solid #e5e7eb;background:#fff\"><button id=\"s80-save\">レイアウト保存</button><button id=\"s80-reset\">初期化</button><span class=\"readout\" id=\"s80-out\">-</span></div>\n    <div id=\"s80-dock\" class=\"s80-dock\"></div>\n    <div id=\"s80-float\"></div>\n  </div>","css":".s80-dock { display: grid; height: 300px; grid-template-columns: var(--cols); position: relative; user-select: none; }\n.s80-zone { display: flex; flex-direction: column; min-width: 0; background: #fff; }\n.s80-zone.over { outline: 2px dashed var(--accent); outline-offset: -2px; }\n.s80-tabs { display: flex; background: #f1f5f9; border-bottom: 1px solid #cbd5e1; min-height: 28px; }\n.s80-tab { padding: 4px 10px; font-size: 12px; border-right: 1px solid #cbd5e1; cursor: grab; display: flex; gap: 6px; align-items: center; touch-action: none; }\n.s80-tab.on { background: #fff; font-weight: 600; } .s80-tab.drag { opacity: .4; }\n.s80-tab i { font-style: normal; cursor: pointer; color: var(--muted); }\n.s80-content { flex: 1; padding: 10px; font-size: 13px; color: var(--muted); overflow: auto; }\n.s80-gutter { background: #cbd5e1; cursor: col-resize; touch-action: none; }\n.s80-win { position: absolute; width: 220px; background: #fff; border: 1px solid #94a3b8; border-radius: 8px; box-shadow: 0 12px 30px rgba(0,0,0,.25); overflow: hidden; z-index: 10; }\n.s80-win .s80-tabs { cursor: move; touch-action: none; }","js":"(() => {\n  const KEY = 'ui-guide.s80.layout';\n  const PANELS = { list: '一覧', detail: '詳細', log: 'ログ', props: 'プロパティ', tree: 'ツリー' };\n  const DEFAULT = () => ({ zones: { left: ['tree'], center: ['list', 'detail'], right: ['props', 'log'] }, active: { left: 'tree', center: 'list', right: 'props' }, float: [], widths: [180, 180] });\n  let L; try { L = JSON.parse(localStorage.getItem(KEY)) || DEFAULT(); } catch { L = DEFAULT(); }\n  const dock = $('#s80-dock'), fl = $('#s80-float'), out = $('#s80-out');\n  const render = () => {\n    dock.style.setProperty('--cols', `${L.widths[0]}px 6px 1fr 6px ${L.widths[1]}px`);\n    dock.innerHTML = ['left', 'center', 'right'].map((z, i) => `${i ? `<div class=\"s80-gutter\" data-g=\"${i - 1}\"></div>` : ''}<div class=\"s80-zone\" data-zone=\"${z}\">\n      <div class=\"s80-tabs\">${L.zones[z].map(p => `<div class=\"s80-tab ${L.active[z] === p ? 'on' : ''}\" data-p=\"${p}\" data-zone=\"${z}\">${PANELS[p]}<i data-pop=\"${p}\" title=\"分離\">⧉</i></div>`).join('')}</div>\n      <div class=\"s80-content\">${L.active[z] && L.zones[z].includes(L.active[z]) ? PANELS[L.active[z]] + ' の内容' : '（空）'}</div></div>`).join('');\n    fl.innerHTML = L.float.map(f => `<div class=\"s80-win\" data-p=\"${f.p}\" style=\"left:${f.x}px;top:${f.y}px\"><div class=\"s80-tabs\"><div class=\"s80-tab on\" data-p=\"${f.p}\" data-float=\"1\">${PANELS[f.p]}<i data-dock=\"${f.p}\" title=\"ドックへ戻す\">⊡</i></div></div><div class=\"s80-content\">${PANELS[f.p]} の内容（分離）</div></div>`).join('');\n    out.textContent = JSON.stringify({ zones: L.zones, float: L.float.map(f => f.p) });\n  };\n  const removeEverywhere = p => { for (const z in L.zones) L.zones[z] = L.zones[z].filter(x => x !== p); L.float = L.float.filter(f => f.p !== p); };\n  // タブ操作：クリックで切替、ドラッグでゾーン移動、⧉で分離、⊡で戻す\n  let drag = null;\n  dock.parentElement.addEventListener('pointerdown', e => {\n    if (e.target.dataset.pop) { const p = e.target.dataset.pop; removeEverywhere(p); L.float.push({ p, x: 60 + L.float.length * 20, y: 60 + L.float.length * 20 }); render(); return; }\n    if (e.target.dataset.dock) { const p = e.target.dataset.dock; removeEverywhere(p); L.zones.center.push(p); L.active.center = p; render(); return; }\n    const g = e.target.closest('[data-g]'); if (g) { drag = { type: 'gutter', g: +g.dataset.g, x: e.clientX, w: [...L.widths] }; g.setPointerCapture(e.pointerId); return; }\n    const tab = e.target.closest('.s80-tab');\n    if (tab && tab.dataset.float) { const win = tab.closest('.s80-win'), f = L.float.find(f => f.p === tab.dataset.p); drag = { type: 'win', f, dx: e.clientX - f.x, dy: e.clientY - f.y, win }; tab.setPointerCapture(e.pointerId); return; }\n    if (tab) { L.active[tab.dataset.zone] = tab.dataset.p; render(); drag = { type: 'tab', p: tab.dataset.p, from: tab.dataset.zone, moved: false }; $(`.s80-tab[data-p=\"${tab.dataset.p}\"]`, dock)?.setPointerCapture(e.pointerId); }\n  });\n  dock.parentElement.addEventListener('pointermove', e => {\n    if (!drag) return;\n    if (drag.type === 'gutter') { const d = e.clientX - drag.x; L.widths[drag.g] = Math.max(100, drag.w[drag.g] + (drag.g === 0 ? d : -d)); dock.style.setProperty('--cols', `${L.widths[0]}px 6px 1fr 6px ${L.widths[1]}px`); }\n    else if (drag.type === 'win') { drag.f.x = e.clientX - drag.dx; drag.f.y = e.clientY - drag.dy; drag.win.style.left = drag.f.x + 'px'; drag.win.style.top = drag.f.y + 'px'; }\n    else if (drag.type === 'tab') { drag.moved = true; const z = document.elementFromPoint(e.clientX, e.clientY)?.closest('[data-zone]'); $$('.s80-zone', dock).forEach(el => el.classList.toggle('over', el === z && z.dataset.zone !== drag.from)); $(`.s80-tab[data-p=\"${drag.p}\"]`, dock)?.classList.add('drag'); }\n  });\n  dock.parentElement.addEventListener('pointerup', e => {\n    if (drag?.type === 'tab' && drag.moved) {\n      const z = document.elementFromPoint(e.clientX, e.clientY)?.closest('[data-zone]')?.dataset.zone;\n      if (z && z !== drag.from) { removeEverywhere(drag.p); L.zones[z].push(drag.p); L.active[z] = drag.p; if (L.active[drag.from] === drag.p) L.active[drag.from] = L.zones[drag.from][0]; }\n      render();\n    }\n    drag = null; $$('.s80-zone', dock).forEach(el => el.classList.remove('over')); $$('.s80-tab', dock).forEach(t => t.classList.remove('drag'));\n  });\n  $('#s80-save').onclick = () => { localStorage.setItem(KEY, JSON.stringify(L)); out.textContent = '保存しました（再読込で復元）'; };\n  $('#s80-reset').onclick = () => { localStorage.removeItem(KEY); L = DEFAULT(); render(); };\n  render();\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n81","title":"81ワークスペース永続化 画面状態の保存と復元","what":"「どのタブを開いていたか」「どこまでスクロールしていたか」「何を選んでいたか」「絞り込み条件」を1つのオブジェクトにまとめ、変更のたびに（デバウンスして）保存する。起動時にそれを読み、描画してから scrollTop を戻す。ユーザーは「昨日の続き」から始められる。","how":"操作：タブ・絞り込み・選択・スクロールを変えてからページを再読込（F5）。同じ状態に戻る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button data-tab=\"orders\">受注</button><button data-tab=\"parts\">部品</button><input id=\"s81-filter\" type=\"text\" placeholder=\"絞り込み\" style=\"width:120px\"><button id=\"s81-clear\">状態を消す</button></div>\n    <div id=\"s81-list\" class=\"s81-list\"></div>\n    <div class=\"readout\" id=\"s81-out\" style=\"margin-top:6px;white-space:pre-wrap\"></div>\n  </div>","css":".s81-list { height: 130px; overflow: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 13px; }\n.s81-list div { padding: 3px 10px; border-bottom: 1px solid #f1f5f9; cursor: default; } .s81-list div.sel { background: var(--accent-soft); }","js":"(() => {\n  const KEY = 'ui-guide.s81.workspace';\n  let ws = { tab: 'orders', filter: '', selected: null, scroll: 0 };\n  try { Object.assign(ws, JSON.parse(localStorage.getItem(KEY) || '{}')); } catch {}\n  const list = $('#s81-list'), out = $('#s81-out'), filter = $('#s81-filter');\n  const debounce = (fn, ms) => { let t; return () => { clearTimeout(t); t = setTimeout(fn, ms); }; };\n  const persist = debounce(() => { localStorage.setItem(KEY, JSON.stringify(ws)); out.textContent = 'saved: ' + JSON.stringify(ws); }, 200);\n  const rows = tab => Array.from({ length: 60 }, (_, i) => tab === 'orders' ? `受注 #${1001 + i}` : `部品 P-${String(i + 1).padStart(3, '0')}`);\n  const render = () => {\n    $$('[data-tab]').forEach(b => b.classList.toggle('primary', b.dataset.tab === ws.tab));\n    filter.value = ws.filter;\n    list.innerHTML = rows(ws.tab).filter(r => r.includes(ws.filter)).map(r => `<div class=\"${r === ws.selected ? 'sel' : ''}\">${r}</div>`).join('');\n    list.scrollTop = ws.scroll;                     // 描画後にスクロール位置を戻す\n    out.textContent = 'state: ' + JSON.stringify(ws);\n  };\n  $$('[data-tab]').forEach(b => b.onclick = () => { ws.tab = b.dataset.tab; ws.scroll = 0; ws.selected = null; render(); persist(); });\n  const applyFilter = () => { ws.filter = filter.value; ws.scroll = 0; render(); persist(); };\n  filter.addEventListener('input', e => { if (e.isComposing) return; applyFilter(); });   // 変換中は絞り込まない\n  filter.addEventListener('compositionend', applyFilter);                                  // 確定で1回だけ\n  list.addEventListener('click', e => { if (e.target.tagName === 'DIV') { ws.selected = e.target.textContent; render(); persist(); } });\n  list.addEventListener('scroll', () => { ws.scroll = list.scrollTop; persist(); });\n  $('#s81-clear').onclick = () => { localStorage.removeItem(KEY); ws = { tab: 'orders', filter: '', selected: null, scroll: 0 }; render(); };\n  render();\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n85","title":"85マルチウィンドウ同期 BroadcastChannel / Electron IPC","what":"同じアプリを複数ウィンドウ（タブ）で開いたとき、片方の変更をもう片方へ即時に反映する。ブラウザ／Electron renderer 同士なら BroadcastChannel が最も簡単（同一オリジン内で全ウィンドウに届く）。Electron でメインプロセスが「真実の状態」を持つ設計なら、IPC で全ウィンドウへ配信する。","how":"操作：「別ウィンドウで開く」でこのページをもう1つ開き、片方でカウンタや選択を変えると、もう片方に即反映される。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s85-open\">別ウィンドウで開く</button><button id=\"s85-inc\">カウンタ +1</button><select id=\"s85-sel\"><option>受注</option><option>製造中</option><option>出荷済</option></select><span class=\"readout\" id=\"s85-out\">-</span></div>\n    <div class=\"log\" id=\"s85-log\"></div>\n  </div>","css":"","js":"(() => {\n  // 経路1: BroadcastChannel（同一オリジンの全ウィンドウへ）。経路2: localStorage の storage イベント（file:// など BroadcastChannel が届かない環境の保険）\n  const ch = new BroadcastChannel('ui-guide.s85'), KEY = 'ui-guide.s85.msg';\n  const me = Math.random().toString(36).slice(2, 6), log = $('#s85-log'), out = $('#s85-out'), sel = $('#s85-sel'), seen = new Set();\n  let state = { count: 0, status: '受注' };\n  const apply = (s, from) => { state = s; sel.value = s.status; out.textContent = `count=${s.count} status=${s.status} (this window: ${me})`; if (from) logTo(log, `← ${from} から受信: ${JSON.stringify(s)}`); };\n  const send = msg => { msg.id = me + ':' + Date.now() + Math.random(); ch.postMessage(msg); try { localStorage.setItem(KEY, JSON.stringify(msg)); } catch {} };\n  const receive = msg => {\n    if (!msg || msg.from === me || seen.has(msg.id)) return; seen.add(msg.id);   // 2経路で届いても1回だけ処理\n    if (msg.type === 'hello') { send({ from: me, state }); return; }             // 新規ウィンドウには現状を返す\n    apply(msg.state, msg.from);\n  };\n  ch.onmessage = e => receive(e.data);\n  window.addEventListener('storage', e => { if (e.key === KEY && e.newValue) receive(JSON.parse(e.newValue)); });\n  const publish = () => { send({ from: me, state }); apply(state); logTo(log, `→ 送信: ${JSON.stringify(state)}`); };\n  send({ type: 'hello', from: me });                        // 起動時：誰かいれば状態をもらう\n  $('#s85-inc').onclick = () => { state.count++; publish(); };\n  sel.onchange = () => { state.status = sel.value; publish(); };\n  $('#s85-open').onclick = () => window.open(location.href.split('#')[0] + '#n85', '_blank', 'width=900,height=600');\n  apply(state);\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n72","title":"72ツリー / 階層グリッド Tree grid with virtual scroll","what":"部品表（BOM）や組織のような階層を、展開状態を持ったまま仮想スクロールする。コツは「木」をそのまま描かず、展開中のノードだけを平坦な配列に変換してから 23 の仮想スクロールに渡すこと。展開／折りたたみは平坦化をやり直すだけ。","how":"操作：▶ で展開。全展開（2,440ノード）しても DOM 行数は増えない。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s72-expand\">全展開</button><button id=\"s72-collapse\">全折りたたみ</button><span class=\"readout\" id=\"s72-out\"></span></div>\n    <div id=\"s72-view\" class=\"s72-view\"><div id=\"s72-spacer\"><div id=\"s72-rows\"></div></div></div>\n  </div>","css":".s72-view { height: 200px; overflow-y: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 13px; user-select: none; }\n.s72-row { height: 26px; line-height: 26px; border-bottom: 1px solid #f1f5f9; white-space: nowrap; }\n.s72-row .tg { display: inline-block; width: 18px; text-align: center; cursor: pointer; color: var(--muted); }","js":"(() => {\n  // 3階層のツリー（40 × 10 × 5 = 2,000ノード）\n  const tree = Array.from({ length: 40 }, (_, i) => ({ name: `製品 ${i + 1}`, open: false, children: Array.from({ length: 10 }, (_, j) => ({ name: `ユニット ${i + 1}-${j + 1}`, open: false, children: Array.from({ length: 5 }, (_, k) => ({ name: `部品 ${i + 1}-${j + 1}-${k + 1}`, children: [] })) })) }));\n  const H = 26, view = $('#s72-view'), spacer = $('#s72-spacer'), rows = $('#s72-rows'), out = $('#s72-out');\n  const TOTAL = (c => { const walk = ns => ns.reduce((a, n) => a + 1 + walk(n.children), 0); return walk(c); })(tree);\n  let flat = [];\n  const flatten = () => { flat = []; const walk = (nodes, depth) => nodes.forEach(n => { flat.push({ n, depth }); if (n.open) walk(n.children, depth + 1); }); walk(tree, 0); spacer.style.height = flat.length * H + 'px'; };\n  const render = () => {\n    const start = Math.floor(view.scrollTop / H), count = Math.ceil(view.clientHeight / H) + 2;\n    rows.style.transform = `translateY(${start * H}px)`;\n    rows.innerHTML = flat.slice(start, start + count).map(({ n, depth }, i) => `<div class=\"s72-row\" style=\"padding-left:${depth * 18 + 6}px\"><span class=\"tg\" data-i=\"${start + i}\">${n.children.length ? (n.open ? '▼' : '▶') : '·'}</span>${n.name}</div>`).join('');\n    out.textContent = `表示中ノード ${flat.length.toLocaleString()} / 全 ${TOTAL.toLocaleString()} / DOM ${rows.children.length} 行`;\n  };\n  rows.addEventListener('click', e => { const i = e.target.dataset.i; if (i == null) return; const n = flat[i].n; if (n.children.length) { n.open = !n.open; flatten(); render(); } });\n  view.addEventListener('scroll', render);\n  const setAll = open => { const walk = ns => ns.forEach(n => { if (n.children.length) { n.open = open; walk(n.children); } }); walk(tree); flatten(); render(); };\n  $('#s72-expand').onclick = () => setAll(true); $('#s72-collapse').onclick = () => setAll(false);\n  flatten(); render();\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n73","title":"73ピボット集計ビュー Pivot with drag-to-assign axes","what":"レコード一覧を「行の軸」「列の軸」「集計値」に振り分けて集計表を作る。項目チップを枠へドラッグして軸を組み替える。集計は Map に「行キー｜列キー」で足し込むだけ。kintone のレコードを取得した後の分析ビューとして使える。","how":"操作：チップを「行」「列」の枠へドラッグ（HTML標準DnD）。「値」は数量/金額を切替。","html":"<div class=\"stage\">\n    <div class=\"row\"><span>項目：</span><span id=\"s73-fields\"></span></div>\n    <div class=\"row\"><span>行：</span><span class=\"s73-zone\" data-axis=\"row\"></span><span>列：</span><span class=\"s73-zone\" data-axis=\"col\"></span><span>値：</span><select id=\"s73-val\"><option value=\"qty\">数量</option><option value=\"amount\">金額</option></select></div>\n    <div style=\"overflow:auto\"><table class=\"mini\" id=\"s73-t\"></table></div>\n  </div>","css":".s73-chip { display: inline-block; padding: 2px 10px; margin: 2px; border-radius: 999px; background: #e0e7ff; color: #3730a3; font-size: 12px; cursor: grab; }\n.s73-zone { display: inline-block; min-width: 90px; min-height: 26px; padding: 2px; border: 1px dashed #94a3b8; border-radius: 6px; vertical-align: middle; margin-right: 12px; }\n.s73-zone.over { border-color: var(--accent); background: var(--accent-soft); }\n#s73-t td.num { text-align: right; } #s73-t .tot { font-weight: 600; background: #f8fafc; }","js":"(() => {\n  const FIELDS = { site: '拠点', person: '担当', month: '月', status: 'ステータス' };\n  const recs = Array.from({ length: 200 }, (_, i) => ({ site: ['本社', '第2工場', '倉庫'][i % 3], person: ['佐藤', '鈴木', '高橋', '田中'][i % 4], month: `${(i % 6) + 4}月`, status: ['受注', '製造中', '出荷済'][(i * 7) % 3], qty: (i % 9 + 1) * 10, amount: (i % 9 + 1) * 10 * (100 + (i % 5) * 50) }));\n  const axes = { row: 'site', col: 'month' };\n  const fields = $('#s73-fields'), t = $('#s73-t');\n  fields.innerHTML = Object.entries(FIELDS).map(([k, v]) => `<span class=\"s73-chip\" draggable=\"true\" data-f=\"${k}\">${v}</span>`).join('');\n  fields.addEventListener('dragstart', e => e.dataTransfer.setData('text/plain', e.target.dataset.f));\n  $$('.s73-zone').forEach(z => {\n    z.addEventListener('dragover', e => { e.preventDefault(); z.classList.add('over'); });\n    z.addEventListener('dragleave', () => z.classList.remove('over'));\n    z.addEventListener('drop', e => { e.preventDefault(); z.classList.remove('over'); axes[z.dataset.axis] = e.dataTransfer.getData('text/plain'); render(); });\n  });\n  const render = () => {\n    $$('.s73-zone').forEach(z => z.innerHTML = `<span class=\"s73-chip\">${FIELDS[axes[z.dataset.axis]]}</span>`);\n    const val = $('#s73-val').value, sum = new Map(), rows = new Set(), cols = new Set();\n    for (const r of recs) { const rk = r[axes.row], ck = r[axes.col]; rows.add(rk); cols.add(ck); const k = rk + '|' + ck; sum.set(k, (sum.get(k) || 0) + r[val]); } // 足し込むだけ\n    const R = [...rows].sort(), C = [...cols].sort(), tot = k => [...sum].filter(([kk]) => kk.startsWith(k + '|')).reduce((a, [, v]) => a + v, 0);\n    t.innerHTML = `<tr><th>${FIELDS[axes.row]} \\\\ ${FIELDS[axes.col]}</th>${C.map(c => `<th>${c}</th>`).join('')}<th>合計</th></tr>` +\n      R.map(r => `<tr><th>${r}</th>${C.map(c => `<td class=\"num\">${(sum.get(r + '|' + c) || 0).toLocaleString()}</td>`).join('')}<td class=\"num tot\">${tot(r).toLocaleString()}</td></tr>`).join('');\n  };\n  $('#s73-val').onchange = render; render();\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n78","title":"78競合解決 Conflict resolution（楽観ロック）","what":"自分が編集している間に他の人が同じレコードを更新していたら、保存時に検知して「上書き／マージ／破棄」を選ばせる。検知はリビジョン番号で行う（kintone は revision を持ち、不一致なら PUT が失敗する）。3方向比較（元・自分・相手）で、片方しか変えていない項目は自動マージできる。","how":"操作：「他ユーザーが更新」を押してから保存すると競合ダイアログが出る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s78-other\">他ユーザーが「数量」と「担当」を更新</button><button id=\"s78-save\" class=\"primary\">保存</button><span class=\"readout\" id=\"s78-out\"></span></div>\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <div style=\"flex:1;font-size:13px\"><b>自分の編集</b><div id=\"s78-form\"></div></div>\n      <div style=\"flex:1;font-size:13px\"><b>サーバ</b><pre class=\"readout\" id=\"s78-server\" style=\"white-space:pre-wrap\"></pre></div>\n    </div>\n    <dialog id=\"s78-dlg\" class=\"s78-dlg\"><b>他のユーザーが先に更新しています</b><table class=\"mini\" id=\"s78-cmp\" style=\"margin:8px 0\"></table><div class=\"row\"><button data-act=\"merge\" class=\"primary\">自動マージ</button><button data-act=\"overwrite\">自分の内容で上書き</button><button data-act=\"discard\">自分の変更を破棄</button></div></dialog>\n  </div>","css":".s78-dlg { border: none; border-radius: 10px; padding: 16px; font-size: 13px; } .s78-dlg::backdrop { background: rgba(15,23,42,.4); }\n#s78-form label { display: block; margin: 4px 0; } #s78-form input { margin-left: 6px; }\n#s78-cmp td.c { background: #fecaca; } #s78-cmp td.m { background: #bbf7d0; }","js":"(() => {\n  let server = { revision: 5, 数量: '100', 担当: '佐藤', 備考: '通常' };\n  let base = { ...server }, mine = { ...server };                      // base: 自分が開いた時点、mine: 編集中\n  const form = $('#s78-form'), sv = $('#s78-server'), out = $('#s78-out'), dlg = $('#s78-dlg');\n  const F = ['数量', '担当', '備考'];\n  const render = () => { form.innerHTML = F.map(k => `<label>${k} <input data-k=\"${k}\" value=\"${mine[k]}\"></label>`).join(''); sv.textContent = JSON.stringify(server, null, 1); };\n  form.addEventListener('input', e => mine[e.target.dataset.k] = e.target.value);\n  $('#s78-other').onclick = () => { server = { ...server, revision: server.revision + 1, 数量: '150', 担当: '鈴木' }; render(); out.textContent = `サーバが rev ${server.revision} に進んだ`; };\n  const put = (data) => { server = { ...server, ...data, revision: server.revision + 1 }; base = { ...server }; mine = { ...server }; render(); out.textContent = `保存成功 → rev ${server.revision}`; };\n  $('#s78-save').onclick = () => {\n    if (base.revision === server.revision) return put(mine);          // 競合なし\n    $('#s78-cmp').innerHTML = '<tr><th>項目</th><th>元</th><th>自分</th><th>相手</th><th>判定</th></tr>' + F.map(k => {\n      const me = mine[k] !== base[k], other = server[k] !== base[k];\n      const j = me && other && mine[k] !== server[k] ? '<td class=\"c\">競合</td>' : me ? '<td class=\"m\">自分を採用</td>' : other ? '<td class=\"m\">相手を採用</td>' : '<td>変更なし</td>';\n      return `<tr><td>${k}</td><td>${base[k]}</td><td>${mine[k]}</td><td>${server[k]}</td>${j}</tr>`;\n    }).join('');\n    dlg.showModal();\n  };\n  dlg.addEventListener('click', e => {\n    const act = e.target.dataset.act; if (!act) return; dlg.close();\n    if (act === 'overwrite') put(mine);\n    else if (act === 'discard') { base = { ...server }; mine = { ...server }; render(); out.textContent = '自分の変更を破棄してサーバ版を表示'; }\n    else {                                                             // 3方向マージ：片方だけ変えた項目はそれを採用、両方なら自分を優先\n      const merged = {}; F.forEach(k => merged[k] = mine[k] !== base[k] ? mine[k] : server[k]);\n      base = { ...server }; put(merged); out.textContent += '（自動マージ）';\n    }\n  });\n  render();\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n79","title":"79オフライン対応 Offline queue and sync status","what":"通信できない間の操作をキューに溜め、復帰したら順に再送する。画面には「未同期 n 件」を常に見せ、ユーザーが不安にならないようにする。判定は navigator.onLine と online/offline イベント、ただし「繋がっているがAPIが落ちている」も同じ扱いにする（送信失敗→キューに戻す）。","how":"操作：「オフライン」にして操作を数回 → 「オンライン」に戻すとキューが流れる。","html":"<div class=\"stage\">\n    <div class=\"row\"><label><input type=\"checkbox\" id=\"s79-off\"> オフライン（模擬）</label><button id=\"s79-do\">レコード更新（操作）</button><span class=\"readout\" id=\"s79-status\">-</span></div>\n    <div class=\"log\" id=\"s79-log\"></div>\n  </div>","css":"","js":"(() => {\n  const KEY = 'ui-guide.s79.queue';\n  let queue = JSON.parse(localStorage.getItem(KEY) || '[]'), busy = false, n = 0;\n  const log = $('#s79-log'), status = $('#s79-status'), off = $('#s79-off');\n  const online = () => navigator.onLine && !off.checked;\n  const api = job => new Promise((ok, ng) => setTimeout(() => online() ? ok() : ng(new Error('offline')), 300));\n  const save = () => { localStorage.setItem(KEY, JSON.stringify(queue)); status.textContent = `${online() ? 'オンライン' : 'オフライン'} / 未同期 ${queue.length} 件`; };\n  async function flush() {                                             // 復帰時に先頭から順に送る。失敗したら止めて次の機会へ\n    if (busy) return; busy = true;\n    while (queue.length && online()) {\n      const job = queue[0];\n      try { await api(job); queue.shift(); logTo(log, `✔ 同期: ${job.name}`); save(); }\n      catch { logTo(log, `✖ 送信失敗、待機: ${job.name}`); break; }\n    }\n    busy = false;\n  }\n  $('#s79-do').onclick = () => { const job = { id: Date.now(), name: `更新 #${++n}` }; queue.push(job); logTo(log, `+ 操作をキューへ: ${job.name}`); save(); flush(); };\n  off.onchange = () => { save(); logTo(log, off.checked ? '-- オフラインになった' : '-- オンラインに復帰'); flush(); };\n  window.addEventListener('online', () => { save(); flush(); }); window.addEventListener('offline', save);\n  save(); if (queue.length) logTo(log, `前回の未同期 ${queue.length} 件を復元`); flush();\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n82","title":"82ルーティングと履歴 History API / 戻る・進むで状態復元","what":"SPA でも「戻る」ボタンが効くように、画面遷移を history.pushState で履歴に積む。state オブジェクトにスクロール位置や絞り込みを入れておけば、popstate で戻ったときにその状態ごと復元できる。Electron でも同じ仕組みが使える。","how":"操作：絞り込み→スクロール→行をクリックで詳細へ→ブラウザの「戻る」（または枠内の←）。一覧が同じ位置・同じ絞り込みで戻る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s82-back\">← 戻る（history.back）</button><span class=\"readout\" id=\"s82-out\"></span></div>\n    <div id=\"s82-app\"></div>\n  </div>","css":".s82-list { height: 130px; overflow: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 13px; }\n.s82-list div { padding: 3px 10px; border-bottom: 1px solid #f1f5f9; cursor: pointer; }","js":"(() => {\n  const app = $('#s82-app'), out = $('#s82-out');\n  let ui = { filter: '', scroll: 0 };                                   // 一覧画面の状態（履歴に保存する）\n  const routes = {\n    list: () => {\n      app.innerHTML = `<div class=\"row\"><input id=\"s82-f\" placeholder=\"絞り込み\" value=\"${ui.filter}\" style=\"width:120px\"></div><div class=\"s82-list\" id=\"s82-l\"></div>`;\n      const l = $('#s82-l'), f = $('#s82-f');\n      const fill = () => l.innerHTML = Array.from({ length: 80 }, (_, i) => `受注 #${1001 + i}`).filter(r => r.includes(ui.filter)).map(r => `<div data-id=\"${r}\">${r}</div>`).join('');\n      fill(); l.scrollTop = ui.scroll;\n      const apply = () => { ui.filter = f.value; fill(); };\n      f.oninput = e => { if (e.isComposing) return; apply(); };   // 変換中は絞り込まない\n      f.addEventListener('compositionend', apply);\n      l.onscroll = () => ui.scroll = l.scrollTop;\n      l.onclick = e => { if (e.target.dataset.id) { history.replaceState({ route: 'list', ui }, '');                 // 離れる前に一覧の状態を保存\n        history.pushState({ route: 'detail', id: e.target.dataset.id }, '', '#n82'); render(history.state); } };\n    },\n    detail: st => app.innerHTML = `<div style=\"font-size:13px;padding:8px;background:#fff;border:1px solid #cbd5e1;border-radius:6px\"><b>${st.id}</b> の詳細<br>ブラウザの「戻る」で一覧の位置と絞り込みが復元される。</div>`,\n  };\n  const render = st => { const s = st?.route ? st : { route: 'list', ui }; if (s.ui) ui = s.ui; routes[s.route](s); out.textContent = `route=${s.route} history.length=${history.length}`; };\n  window.addEventListener('popstate', e => render(e.state));            // 戻る/進む\n  $('#s82-back').onclick = () => history.back();\n  render(history.state?.route ? history.state : null);\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n83","title":"83スマートプレビュー Hover prefetch and preview card","what":"リンクにホバーして一定時間（300ms）留まったら、先読みしてカードで内容を出す。カーソルが通り過ぎただけでは取得しない（遅延＋キャンセル）。取得結果はキャッシュし、2回目は即表示。kintone なら GET /k/v1/record.json をここで叩く。","how":"操作：リンクにホバーして少し待つ。同じリンクに戻ると即表示（キャッシュ）。","html":"<div class=\"stage\" style=\"min-height:150px\">\n    <div class=\"row\" style=\"font-size:13px\">関連レコード：<a href=\"#n83\" data-id=\"1001\">受注 #1001</a><a href=\"#n83\" data-id=\"1002\">受注 #1002</a><a href=\"#n83\" data-id=\"1003\">受注 #1003</a><span class=\"readout\" id=\"s83-out\">-</span></div>\n    <div id=\"s83-card\" class=\"s83-card\" hidden></div>\n  </div>","css":".s83-card { position: absolute; background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 10px 12px; font-size: 12.5px; box-shadow: 0 10px 24px rgba(0,0,0,.12); width: 220px; z-index: 5; }","js":"(() => {\n  const card = $('#s83-card'), out = $('#s83-out'), cache = new Map();\n  const fetchRecord = id => cache.get(id) || (cache.set(id, new Promise(r => setTimeout(() => r({ id, customer: '株式会社サンプル', qty: 100 + +id % 100, due: '2026-09-20' }), 600))), cache.get(id)); // Promise ごとキャッシュ\n  let timer = null, current = null;\n  $$('a[data-id]').forEach(a => {\n    a.addEventListener('pointerenter', () => {\n      const id = a.dataset.id; current = id;\n      timer = setTimeout(async () => {                                 // 300ms 留まったら取得開始\n        const t0 = performance.now(); const rec = await fetchRecord(id);\n        if (current !== id) return;                                     // 待っている間に離れたら表示しない\n        const r = a.getBoundingClientRect(), s = card.parentElement.getBoundingClientRect();\n        card.style.left = r.left - s.left + 'px'; card.style.top = r.bottom - s.top + 6 + 'px';\n        card.innerHTML = `<b>受注 #${rec.id}</b><br>${rec.customer}<br>数量 ${rec.qty} / 納期 ${rec.due}`; card.hidden = false;\n        out.textContent = `#${id}: ${(performance.now() - t0).toFixed(0)}ms${performance.now() - t0 < 50 ? '（キャッシュ）' : '（取得）'}`;\n      }, 300);\n    });\n    a.addEventListener('pointerleave', () => { clearTimeout(timer); current = null; card.hidden = true; });\n    a.addEventListener('click', e => e.preventDefault());\n  });\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n84","title":"84ズーム可能タイムライン / ガント Time axis with pan, zoom, drag","what":"43 の座標変換を「横軸＝時間」に適用したもの。x = (t − t0) × pxPerDay + offset と逆変換だけで、パン・ズーム・バーのドラッグ（日付変更）・日単位スナップが全部書ける。目盛りはズーム倍率に応じて「日／週／月」を切り替える。","how":"操作：背景ドラッグでパン、ホイールでズーム（カーソル基準）、バーをドラッグで日程変更（日単位に吸着）。","html":"<div class=\"stage\" style=\"padding:0\">\n    <div id=\"s84-view\" class=\"s84-view\"><svg id=\"s84-svg\" class=\"s84-svg\"></svg><span class=\"readout\" id=\"s84-out\" style=\"position:absolute;right:8px;top:8px\">-</span></div>\n  </div>","css":".s84-view { position: relative; height: 240px; background: #fff; overflow: hidden; touch-action: none; user-select: none; cursor: grab; }\n.s84-svg { width: 100%; height: 100%; display: block; }\n.s84-svg .tick { stroke: #e5e7eb; } .s84-svg .tick.major { stroke: #94a3b8; } .s84-svg text { font-size: 11px; fill: #64748b; }\n.s84-svg .bar { fill: var(--accent); rx: 4; cursor: ew-resize; } .s84-svg .bar:hover { fill: #1d4ed8; } .s84-svg .label { fill: #fff; font-size: 11px; pointer-events: none; }","js":"(() => {\n  const view = $('#s84-view'), svg = $('#s84-svg'), out = $('#s84-out'), DAY = 86400000;\n  const t0 = new Date('2026-09-01').getTime();\n  const tasks = [{ name: '設計', s: 0, d: 5 }, { name: '材料手配', s: 3, d: 7 }, { name: '加工', s: 9, d: 10 }, { name: '組立', s: 18, d: 6 }, { name: '検査', s: 23, d: 3 }, { name: '出荷', s: 26, d: 1 }];\n  let ppd = 24, off = 40;                                              // px/日, オフセット\n  const x = day => day * ppd + off, day = px => (px - off) / ppd;      // 変換と逆変換\n  const render = () => {\n    const W = view.clientWidth, H = view.clientHeight; let s = '';\n    const step = ppd > 40 ? 1 : ppd > 12 ? 7 : 30;                    // ズームに応じた目盛り（日/週/月）\n    for (let d = Math.floor(day(0) / step) * step; x(d) < W; d += step) {\n      const dt = new Date(t0 + d * DAY), major = step === 1 ? dt.getDay() === 1 : true;\n      s += `<line class=\"tick ${major ? 'major' : ''}\" x1=\"${x(d)}\" x2=\"${x(d)}\" y1=\"24\" y2=\"${H}\"/><text x=\"${x(d) + 3}\" y=\"16\">${step === 30 ? `${dt.getMonth() + 1}月` : `${dt.getMonth() + 1}/${dt.getDate()}`}</text>`;\n    }\n    tasks.forEach((t, i) => s += `<rect class=\"bar\" data-i=\"${i}\" x=\"${x(t.s)}\" y=\"${36 + i * 32}\" width=\"${t.d * ppd}\" height=\"24\"/><text class=\"label\" x=\"${x(t.s) + 6}\" y=\"${52 + i * 32}\">${t.name} ${new Date(t0 + t.s * DAY).getDate()}日〜</text>`);\n    svg.innerHTML = s; out.textContent = `${ppd.toFixed(1)} px/日（目盛り: ${step === 1 ? '日' : step === 7 ? '週' : '月'}）`;\n  };\n  let drag = null;\n  view.addEventListener('pointerdown', e => { const bar = e.target.closest('.bar'); drag = bar ? { type: 'bar', t: tasks[+bar.dataset.i], s0: tasks[+bar.dataset.i].s, x0: e.clientX } : { type: 'pan', x0: e.clientX, off0: off }; view.setPointerCapture(e.pointerId); });\n  view.addEventListener('pointermove', e => {\n    if (!drag) return;\n    if (drag.type === 'pan') off = drag.off0 + e.clientX - drag.x0;\n    else drag.t.s = Math.round(drag.s0 + (e.clientX - drag.x0) / ppd);  // 日単位にスナップ\n    render();\n  });\n  view.addEventListener('pointerup', () => drag = null);\n  view.addEventListener('wheel', e => { e.preventDefault(); const cx = e.clientX - view.getBoundingClientRect().left, d = day(cx); ppd = Math.min(120, Math.max(3, ppd * Math.exp(-e.deltaY * 0.002))); off = cx - d * ppd; render(); }, { passive: false }); // カーソル基準ズーム\n  new ResizeObserver(render).observe(view);\n})();"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n86","title":"86監視ボード型UI Polling / 変化点のフラッシュ / 通知集約","what":"現場の状況を常時表示する画面。①一定間隔で取得（タブが隠れている間は止める：visibilitychange）②前回との差分だけをフラッシュ表示 ③通知は1件ずつ出さず「n件更新」に集約し、ミュートできる。ポーリング間隔は「取得にかかった時間」より十分長くする。","how":"操作：2秒ごとに値が変わり、変わったセルが光る。タブを切り替えると停止し、戻ると再開する。","html":"<div class=\"stage\">\n    <div class=\"row\"><label><input type=\"checkbox\" id=\"s86-run\" checked> ポーリング（2s）</label><label><input type=\"checkbox\" id=\"s86-mute\"> 通知ミュート</label><span class=\"readout\" id=\"s86-out\">-</span><span class=\"pill\" id=\"s86-badge\" hidden>0</span></div>\n    <table class=\"mini\" id=\"s86-t\" style=\"width:100%\"></table>\n  </div>","css":"#s86-t td.flash { animation: s86-flash 1.2s ease-out; }\n@keyframes s86-flash { from { background: #fde68a; } }","js":"(() => {\n  const LINES = ['ライン1', 'ライン2', 'ライン3', 'ライン4'], COLS = ['稼働', '生産数', '不良', '状態'];\n  let prev = null, timer = null, pending = 0;\n  const t = $('#s86-t'), out = $('#s86-out'), badge = $('#s86-badge');\n  let sim = LINES.map((l, i) => [l, '稼働中', String(1000 + i * 100), '0', '正常']);\n  const fetchStatus = () => new Promise(r => setTimeout(() => {                 // 疑似API：毎回2〜3セルだけ変わる\n    sim = sim.map(row => [...row]);\n    for (let k = 0; k < 2 + Math.floor(Math.random() * 2); k++) {\n      const row = sim[Math.floor(Math.random() * sim.length)], c = 1 + Math.floor(Math.random() * 4);\n      row[c] = c === 2 ? String(+row[c] + 1) : c === 3 ? String(+row[c] + (Math.random() < 0.3 ? 1 : 0)) : c === 1 ? (Math.random() < 0.8 ? '稼働中' : '停止') : (Math.random() < 0.8 ? '正常' : '要確認');\n    }\n    r(sim);\n  }, 200));\n  const render = rows => {\n    let changed = 0;\n    t.innerHTML = '<tr><th></th>' + COLS.map(c => `<th>${c}</th>`).join('') + '</tr>' + rows.map((r, i) => `<tr><th>${r[0]}</th>${r.slice(1).map((v, j) => { const f = prev && prev[i][j + 1] !== v; if (f) changed++; return `<td class=\"${f ? 'flash' : ''}\">${v}</td>`; }).join('')}</tr>`).join('');\n    prev = rows;\n    if (changed && !$('#s86-mute').checked) { pending += changed; badge.hidden = false; badge.textContent = `${pending} 件更新`; } // 集約\n  };\n  const poll = async () => {\n    if (document.hidden) return;                                       // 見えていないなら取得しない\n    const t0 = performance.now(); const rows = await fetchStatus(); render(rows);\n    out.textContent = `最終取得 ${new Date().toLocaleTimeString()}（${(performance.now() - t0).toFixed(0)}ms）`;\n  };\n  const start = () => { clearInterval(timer); if ($('#s86-run').checked) { poll(); timer = setInterval(poll, 2000); } };\n  document.addEventListener('visibilitychange', () => { out.textContent = document.hidden ? '非表示：ポーリング停止' : out.textContent; if (!document.hidden) poll(); });\n  $('#s86-run').onchange = start; badge.onclick = () => { pending = 0; badge.hidden = true; };\n  start();\n})();"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n63","title":"63シェアードエレメント遷移 Shared element transition","what":"一覧の行が「同じ物として」詳細画面へ拡大移動する。View Transitions（31）で、遷移する瞬間だけクリックした要素に view-transition-name を付ける。全行に同じ名前を付けると衝突して失敗するので、動的に付け外しするのが要点。","how":"操作：カードをクリック→詳細へ。「戻る」で逆再生。非対応ブラウザは即時切替。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s63-root\" class=\"s63-root\"></div>\n  </div>","css":".s63-root { height: 280px; padding: 12px; overflow: auto; }\n.s63-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }\n.s63-card { background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 10px; cursor: pointer; font-size: 13px; }\n.s63-thumb { height: 50px; border-radius: 6px; margin-bottom: 6px; }\n.s63-detail .s63-thumb { height: 120px; }\n::view-transition-old(hero), ::view-transition-new(hero) { animation-duration: .4s; }","js":"(() => {\n  const root = $('#s63-root');\n  const items = [['受注 #1001', '#2563eb'], ['受注 #1002', '#16a34a'], ['受注 #1003', '#d97706'], ['受注 #1004', '#dc2626'], ['受注 #1005', '#7c3aed'], ['受注 #1006', '#0891b2']];\n  let current = null;\n  const renderList = () => root.innerHTML = `<div class=\"s63-list\">${items.map(([t, c], i) => `<div class=\"s63-card\" data-i=\"${i}\"><div class=\"s63-thumb\" style=\"background:${c}\"></div>${t}</div>`).join('')}</div>`;\n  const renderDetail = i => root.innerHTML = `<div class=\"s63-detail\"><div class=\"s63-thumb\" style=\"background:${items[i][1]};view-transition-name:hero\"></div><b>${items[i][0]}</b><p style=\"font-size:13px\">詳細画面。サムネイルが一覧から「移動してきた」ように見える。</p><button id=\"s63-back\">← 戻る</button></div>`;\n  const go = (mutate, tagBefore) => {\n    if (!document.startViewTransition) { mutate(); return; }\n    tagBefore?.();                                           // 遷移前：出発側の要素に名前を付ける\n    document.startViewTransition(mutate).finished.then(() => $$('.s63-card').forEach(c => c.style.viewTransitionName = ''));\n  };\n  root.addEventListener('click', e => {\n    const card = e.target.closest('.s63-card');\n    if (card) { current = +card.dataset.i; go(() => renderDetail(current), () => $('.s63-thumb', card).style.viewTransitionName = 'hero'); }\n    if (e.target.id === 's63-back') go(() => { renderList(); $(`.s63-card[data-i=\"${current}\"] .s63-thumb`).style.viewTransitionName = 'hero'; }); // 到着側に名前を付ける\n  });\n  renderList();\n})();"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n64","title":"64スタガーアニメーション Stagger","what":"複数要素を数十msずつ遅らせて順に出す。「一斉にドン」より軽く見え、視線を上から下へ誘導できる。CSSなら animation-delay: calc(var(--i) * 40ms)、JSなら WAAPI の delay。要素数が多いときは合計時間が伸びすぎないよう上限を設ける。","how":"操作：再生。間隔を変えて印象の違いを見る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s64-run\">再生</button>間隔 <input id=\"s64-gap\" type=\"range\" min=\"0\" max=\"120\" value=\"40\"> <span class=\"readout\" id=\"s64-out\">40ms</span></div>\n    <div id=\"s64-list\"></div>\n  </div>","css":".s64-item { background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 6px 10px; margin-bottom: 4px; font-size: 13px; opacity: 0; transform: translateY(10px); }\n.s64-item.in { animation: s64-in .35s ease-out forwards; animation-delay: calc(var(--i) * var(--gap)); }\n@keyframes s64-in { to { opacity: 1; transform: none; } }","js":"(() => {\n  const list = $('#s64-list'), gap = $('#s64-gap'), out = $('#s64-out');\n  list.innerHTML = Array.from({ length: 6 }, (_, i) => `<div class=\"s64-item\" style=\"--i:${Math.min(i, 10)}\">行 ${i + 1}</div>`).join(''); // --i に上限（10）を設けて合計時間を抑える\n  gap.oninput = () => out.textContent = gap.value + 'ms';\n  $('#s64-run').onclick = () => {\n    list.style.setProperty('--gap', gap.value + 'ms');\n    $$('.s64-item').forEach(el => { el.classList.remove('in'); void el.offsetWidth; el.classList.add('in'); });\n  };\n})();"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n65","title":"65スケルトン → 実データのモーフィング Skeleton morph","what":"スケルトン（22）から本物の内容へ切り替わる瞬間に「ガタつき」が出るのを防ぐ。①スケルトンと本物を同じ位置に重ね、クロスフェードする ②高さが変わるならFLIP（30）の高さ版で滑らかに伸縮する。","how":"操作：再読込。「ガタつき版」と比べる。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s65-reload\">再読込（1.5秒）</button></div>\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <div class=\"s65-card\" id=\"s65-plain\"><div class=\"s65-sk\"></div></div>\n      <div class=\"s65-card s65-morph\" id=\"s65-morph\"><div class=\"s65-layer s65-sk\"></div><div class=\"s65-layer s65-real\" style=\"opacity:0\"></div></div>\n    </div>\n  </div>","css":".s65-card { flex: 1; background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 12px; font-size: 13px; position: relative; overflow: hidden; }\n.s65-sk { display: grid; gap: 8px; } .s65-sk::before, .s65-sk::after { content: ''; height: 12px; border-radius: 6px; background: #e5e7eb; } .s65-sk::after { width: 60%; }\n.s65-morph .s65-layer { transition: opacity .35s; }\n.s65-morph .s65-real { position: absolute; inset: 12px; }         /* 重ねる */\n.s65-morph.done { transition: height .35s ease; }","js":"(() => {\n  const plain = $('#s65-plain'), morph = $('#s65-morph');\n  const content = '<b>受注 #1001</b><div>株式会社サンプル</div><div>納期 2026-09-12 / 数量 120</div><div>備考：分納可、梱包は強化仕様。</div>';\n  const load = () => {\n    plain.innerHTML = '<div class=\"s65-sk\"></div>';\n    morph.classList.remove('done'); morph.style.height = ''; $('.s65-sk', morph).style.opacity = 1; const real = $('.s65-real', morph); real.style.opacity = 0; real.innerHTML = '';\n    setTimeout(() => {\n      plain.innerHTML = content;                                        // ガタつき版：差し替えるだけ\n      const h0 = morph.offsetHeight; real.innerHTML = content;           // モーフ版：高さを測ってから\n      real.style.position = 'static'; const h1 = morph.offsetHeight; real.style.position = '';\n      morph.style.height = h0 + 'px'; morph.classList.add('done'); void morph.offsetHeight; morph.style.height = h1 + 'px';  // 高さを FLIP\n      $('.s65-sk', morph).style.opacity = 0; real.style.opacity = 1;    // クロスフェード\n      morph.addEventListener('transitionend', () => { real.style.position = 'static'; morph.style.height = ''; }, { once: true });\n    }, 1500);\n  };\n  $('#s65-reload').onclick = load; load();\n})();"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n66","title":"66マイクロインタラクション Micro-interactions","what":"操作に対する「小さな返事」。チェックのバウンス、保存ボタンの「送信中→完了」の形状変化、いいねの弾み。ルール：150〜300ms、ユーザーの操作の直後に、操作したその場所で起きる。装飾ではなく「受け付けた」の合図。","how":"操作：それぞれ押す。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <label class=\"s66-check\"><input type=\"checkbox\"><span class=\"s66-box\"></span> 完了にする</label>\n      <button id=\"s66-save\" class=\"primary s66-save\"><span class=\"s66-label\">保存</span></button>\n      <button id=\"s66-like\" class=\"s66-like\">♥ <span>12</span></button>\n    </div>\n  </div>","css":".s66-check { display: inline-flex; align-items: center; gap: 6px; cursor: pointer; font-size: 13px; }\n.s66-check input { display: none; }\n.s66-box { width: 18px; height: 18px; border: 2px solid #94a3b8; border-radius: 4px; display: grid; place-items: center; transition: background .15s, border-color .15s; }\n.s66-box::after { content: '✓'; color: #fff; font-size: 12px; transform: scale(0); transition: transform .2s cubic-bezier(.3,1.6,.5,1); } /* 行き過ぎて戻る */\n.s66-check input:checked + .s66-box { background: var(--accent); border-color: var(--accent); }\n.s66-check input:checked + .s66-box::after { transform: scale(1); }\n.s66-save { min-width: 90px; transition: background .2s, min-width .2s; } .s66-save.busy { background: #94a3b8; border-color: #94a3b8; } .s66-save.ok { background: #16a34a; border-color: #16a34a; }\n.s66-like { transition: color .15s; } .s66-like.on { color: #dc2626; } .s66-like.pop { animation: s66-pop .3s; }\n@keyframes s66-pop { 30% { transform: scale(1.3); } }","js":"(() => {\n  const save = $('#s66-save'), label = $('.s66-label', save);\n  save.onclick = async () => {\n    if (save.classList.contains('busy')) return;\n    save.classList.add('busy'); label.textContent = '保存中…';\n    await new Promise(r => setTimeout(r, 900));\n    save.classList.replace('busy', 'ok'); label.textContent = '✓ 保存済み';\n    setTimeout(() => { save.classList.remove('ok'); label.textContent = '保存'; }, 1500);\n  };\n  const like = $('#s66-like'), n = $('span', like);\n  like.onclick = () => { const on = like.classList.toggle('on'); n.textContent = +n.textContent + (on ? 1 : -1); like.classList.remove('pop'); void like.offsetWidth; like.classList.add('pop'); };\n})();"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n67","title":"67ジェスチャー連動の物理 Interactive back swipe","what":"画面遷移を「アニメーション再生」ではなく「指の位置に追従」させ、離した時点で完了か取消かを決める（iOSの戻る操作）。ドラッグ量を0〜1の進捗に変換し、離したら閾値（40%）と速度で判定、残りはスプリング（29）で流す。","how":"操作：詳細画面の左端からドラッグ。途中で戻すとキャンセルされる。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div id=\"s67-stack\" class=\"s67-stack\">\n      <div class=\"s67-page s67-list\">一覧画面<br><small>（背面）</small></div>\n      <div id=\"s67-detail\" class=\"s67-page s67-detail\"><div class=\"s67-edge\"></div>詳細画面<br><small>左端からドラッグして戻る</small><br><button id=\"s67-reopen\" hidden>詳細を開く</button></div>\n    </div>\n  </div>","css":".s67-stack { position: relative; height: 260px; overflow: hidden; background: #e2e8f0; }\n.s67-page { position: absolute; inset: 0; display: grid; place-items: center; text-align: center; font-size: 15px; }\n.s67-list { background: #f8fafc; }\n.s67-detail { background: #fff; box-shadow: -6px 0 20px rgba(0,0,0,.15); touch-action: pan-y; will-change: transform; }\n.s67-edge { position: absolute; left: 0; top: 0; bottom: 0; width: 28px; cursor: ew-resize; background: linear-gradient(90deg, rgba(37,99,235,.15), transparent); }","js":"(() => {\n  const detail = $('#s67-detail'), W = () => detail.offsetWidth;\n  let st = null, x = 0, raf = 0;\n  const set = px => { x = px; detail.style.transform = `translateX(${px}px)`; $('.s67-list').style.filter = `brightness(${0.85 + 0.15 * px / W()})`; };\n  detail.addEventListener('pointerdown', e => { if (e.offsetX > 28 || e.target.tagName === 'BUTTON') return; cancelAnimationFrame(raf); st = { x: e.clientX, t: performance.now(), last: e.clientX, v: 0 }; detail.setPointerCapture(e.pointerId); });\n  detail.addEventListener('pointermove', e => { if (!st) return; const now = performance.now(); st.v = (e.clientX - st.last) / Math.max(1, now - st.t); st.last = e.clientX; st.t = now; set(Math.max(0, e.clientX - st.x)); });\n  detail.addEventListener('pointerup', () => {\n    if (!st) return;\n    const complete = x / W() > 0.4 || st.v > 0.5;               // 進捗 40% 超 or 速いフリックで確定\n    const target = complete ? W() : 0; st = null; let v = 0;\n    const tick = () => { v = (v + (target - x) * 0.15) * 0.75; set(x + v); if (Math.abs(target - x) > 0.5 || Math.abs(v) > 0.5) raf = requestAnimationFrame(tick); else { set(target); if (complete) $('#s67-reopen').hidden = false; } };\n    raf = requestAnimationFrame(tick);\n  });\n  $('#s67-reopen').onclick = e => { e.stopPropagation(); $('#s67-reopen').hidden = true; detail.animate([{ transform: `translateX(${W()}px)` }, { transform: 'none' }], { duration: 300, easing: 'cubic-bezier(.2,.8,.2,1)' }).finished.then(() => set(0)); };\n})();"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n68","title":"68スクロール駆動アニメーション（CSS） animation-timeline: scroll() / view()","what":"27 は JS（IntersectionObserver）だったが、CSS だけで「スクロール量＝アニメーション進捗」にできる。scroll() はスクロール位置に、view() は要素が見えている割合に連動する。メインスレッドを使わないので滑らか。非対応ブラウザでは単に表示される（プログレッシブ）。","how":"操作：枠内をスクロール。上端の読了バーと、各カードの出現がスクロールに同期する。","html":"<div class=\"stage\" style=\"padding:0\">\n    <div id=\"s68-view\" class=\"s68-view\"><div class=\"s68-bar\"></div>\n      <div class=\"s68-inner\"><p>読了バーは scroll()、カードは view()</p><div class=\"s68-card\">カード 1</div><div class=\"s68-card\">カード 2</div><div class=\"s68-card\">カード 3</div><div class=\"s68-card\">カード 4</div><div class=\"s68-card\">カード 5</div><p>終わり</p></div>\n    </div>\n    <span class=\"readout\" id=\"s68-out\" style=\"position:absolute;right:8px;top:8px\"></span>\n  </div>","css":".s68-view { height: 240px; overflow-y: auto; scroll-timeline: --s68 y; position: relative; }\n.s68-inner { padding: 14px; } .s68-inner p { font-size: 13px; color: var(--muted); }\n.s68-bar { position: sticky; top: 0; height: 4px; background: var(--accent); transform-origin: 0 50%; transform: scaleX(0); z-index: 1;\n  animation: s68-grow linear both; animation-timeline: --s68; }                  /* スクロール位置 → 進捗 */\n@keyframes s68-grow { to { transform: scaleX(1); } }\n.s68-card { background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 14px; margin: 50px 0; font-size: 13px;\n  animation: s68-in linear both; animation-timeline: view(); animation-range: entry 0% entry 80%; } /* 見え始め〜80% 見えた時点で完了 */\n@keyframes s68-in { from { opacity: 0; transform: translateX(-30px); } }","js":"(() => { $('#s68-out').textContent = CSS.supports('animation-timeline: scroll()') ? 'animation-timeline: 対応' : '非対応 → 静的表示にフォールバック'; })();"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n69","title":"69ぼかし / グラスモーフィズム backdrop-filter と性能","what":"半透明パネルの背後をぼかす backdrop-filter: blur()。見栄えは良いが、背後が動くたびに毎フレーム再計算されるためGPUが弱い端末では重い。実機で計測し、必要なら blur を外して単なる半透明にする。","how":"操作：ぼかしON/OFFを切り替えて、右上のフレーム時間を比べる（差が出ない端末なら採用してよい）。","html":"<div class=\"stage tall\" style=\"padding:0\">\n    <div class=\"s69-view\"><div id=\"s69-bg\" class=\"s69-bg\"></div><div id=\"s69-glass\" class=\"s69-glass blur\"><b>グラスパネル</b><br><label><input type=\"checkbox\" id=\"s69-toggle\" checked> backdrop-filter: blur(12px)</label></div><span class=\"readout\" id=\"s69-out\" style=\"position:absolute;right:8px;top:8px\">-</span></div>\n  </div>","css":".s69-view { position: relative; height: 240px; overflow: hidden; background: #0f172a; }\n.s69-bg { position: absolute; inset: -50%; background: conic-gradient(from 0deg, #2563eb, #db2777, #d97706, #16a34a, #2563eb); animation: s69-spin 6s linear infinite; }\n@keyframes s69-spin { to { transform: rotate(360deg); } }\n.s69-glass { position: absolute; left: 30px; top: 40px; width: 300px; padding: 16px; border-radius: 12px; color: #fff; font-size: 13px;\n  background: rgba(255,255,255,.18); border: 1px solid rgba(255,255,255,.35); }\n.s69-glass.blur { backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); }","js":"(() => {\n  const glass = $('#s69-glass'), out = $('#s69-out');\n  $('#s69-toggle').onchange = e => glass.classList.toggle('blur', e.target.checked);\n  let last = performance.now(), acc = 0, n = 0;                      // フレーム時間の移動平均\n  const tick = t => { acc += t - last; n++; last = t; if (n === 30) { out.textContent = `平均 ${(acc / n).toFixed(1)} ms/frame`; acc = n = 0; } requestAnimationFrame(tick); };\n  requestAnimationFrame(tick);\n})();"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n70","title":"70ダークモード切替のクロスフェード Theme transition with View Transitions","what":"テーマ切替時に全画面がパッと変わるのを、View Transitions で滑らかにする。標準は全体クロスフェード。::view-transition-new(root) に clip-path: circle() をアニメーションさせると「クリック位置から広がる」演出になる。テーマ自体は data-theme 属性と CSS 変数で。","how":"操作：ボタンを押す（押した位置から広がる）。このデモ枠内だけがテーマ切替の対象。","html":"<div class=\"stage\" style=\"padding:0\">\n    <div id=\"s70-app\" class=\"s70-app\" data-theme=\"light\"><div class=\"row\" style=\"padding:10px\"><button id=\"s70-btn\">🌙 ダークに切替</button><span class=\"readout\" id=\"s70-out\"></span></div><div class=\"s70-body\"><b>ダッシュボード</b><p>CSS変数を data-theme で切り替え、View Transitions で遷移をつなぐ。</p></div></div>\n  </div>","css":".s70-app { --bg: #fff; --fg: #1d1f23; background: var(--bg); color: var(--fg); height: 170px; transition: none; }\n.s70-app[data-theme=\"dark\"] { --bg: #0f172a; --fg: #e2e8f0; }\n.s70-body { padding: 0 14px; font-size: 13px; }\n::view-transition-old(root) { animation: none; }                                     /* 旧画面は静止、新画面を円で広げる */\n::view-transition-new(root) { animation: s70-reveal .5s ease-out; clip-path: circle(150% at var(--x) var(--y)); }\n@keyframes s70-reveal { from { clip-path: circle(0 at var(--x) var(--y)); } }","js":"(() => {\n  const app = $('#s70-app'), btn = $('#s70-btn'), out = $('#s70-out');\n  out.textContent = document.startViewTransition ? 'View Transitions: 対応' : '非対応 → 即時切替';\n  btn.onclick = e => {\n    document.documentElement.style.setProperty('--x', e.clientX + 'px'); document.documentElement.style.setProperty('--y', e.clientY + 'px'); // クリック位置を中心に\n    const swap = () => { const dark = app.dataset.theme !== 'dark'; app.dataset.theme = dark ? 'dark' : 'light'; btn.textContent = dark ? '☀ ライトに切替' : '🌙 ダークに切替'; };\n    document.startViewTransition ? document.startViewTransition(swap) : swap();\n  };\n})();"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f1","title":"F1座標系の違い clientX / pageX / offsetX / screenX / getBoundingClientRect","what":"マウス位置には5種類の「原点」がある。ドラッグやズームで一番よく使うのは clientX と getBoundingClientRect().left の差（＝要素内のローカル座標）。offsetX は「イベントが当たった要素」基準なので、子要素の上で値が飛ぶ。","how":"操作：枠内でマウスを動かす。枠は少しスクロールしてある。青い子要素の上で offsetX がどう変わるか見る。","html":"<div class=\"stage\">\n    <div id=\"f1-view\" class=\"f1-view\"><div class=\"f1-inner\"><div class=\"box\" style=\"position:absolute;left:120px;top:60px\">子要素</div></div></div>\n    <table class=\"cmp\" id=\"f1-t\" style=\"margin-top:8px\"></table>\n  </div>","css":".f1-view { height: 150px; overflow: auto; border: 1px solid #cbd5e1; background: #fff; }\n.f1-inner { position: relative; width: 900px; height: 400px; background-image: linear-gradient(#f1f5f9 1px, transparent 1px), linear-gradient(90deg, #f1f5f9 1px, transparent 1px); background-size: 40px 40px; }","js":"(() => {\n  const view = $('#f1-view'), t = $('#f1-t');\n  view.scrollTop = 30; view.scrollLeft = 20;\n  const rows = [\n    ['clientX/Y', 'ブラウザの表示領域（ビューポート）左上が原点。スクロールしても要素は動くが原点は動かない', e => [e.clientX, e.clientY]],\n    ['pageX/Y', 'ページ全体の左上が原点。client + ページのスクロール量', e => [e.pageX, e.pageY]],\n    ['offsetX/Y', 'イベントが当たった要素（target）の左上が原点。子要素の上では値が飛ぶ → ドラッグには使わない', e => [e.offsetX, e.offsetY]],\n    ['screenX/Y', '画面（モニタ）左上が原点。UIではほぼ使わない', e => [e.screenX, e.screenY]],\n    ['client − rect', '要素の getBoundingClientRect() を引く → 要素内ローカル座標。ドラッグ・ズーム・キャンバスはこれ', e => { const r = view.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; }],\n    ['+ scroll', 'ローカル座標 + 要素のスクロール量 → スクロール内容上の座標', e => { const r = view.getBoundingClientRect(); return [e.clientX - r.left + view.scrollLeft, e.clientY - r.top + view.scrollTop]; }],\n  ];\n  const render = e => t.innerHTML = '<tr><th>値</th><th>原点</th><th>x, y</th></tr>' + rows.map(([k, d, f]) => { const [x, y] = e ? f(e).map(Math.round) : ['-', '-']; return `<tr><td class=\"k\">${k}</td><td>${d}</td><td>${x}, ${y}</td></tr>`; }).join('');\n  view.addEventListener('pointermove', render); render(null);\n})();"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f2","title":"F2イベントの発火順と伝播 capture → target → bubble / stopPropagation","what":"イベントは「外側から内側へ（capture）→ 当たった要素（target）→ 内側から外側へ（bubble）」の順に流れる。addEventListener(type, fn, true) で capture 側に登録できる。stopPropagation() はそこから先へ流さない。preventDefault() は伝播ではなく「ブラウザの既定動作」を止める。この2つの違いが最重要。","how":"操作：内側の箱をクリック。ログに順序が出る。チェックで「中央で stopPropagation」を有効にすると、外側の bubble が来なくなる。","html":"<div class=\"stage\">\n    <div class=\"row\"><label><input type=\"checkbox\" id=\"f2-stop\"> 中央（bubble）で stopPropagation()</label><button id=\"f2-clear\">ログ消去</button></div>\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <div id=\"f2-outer\" class=\"f2-box\">外側<div id=\"f2-mid\" class=\"f2-box\">中央<div id=\"f2-inner\" class=\"f2-box\" style=\"background:var(--accent);color:#fff\">内側</div></div></div>\n      <div class=\"log\" id=\"f2-log\" style=\"flex:1\"></div>\n    </div>\n  </div>","css":".f2-box { padding: 14px; border: 1px solid #94a3b8; border-radius: 8px; background: #fff; font-size: 12px; user-select: none; cursor: pointer; }","js":"(() => {\n  const log = $('#f2-log');\n  ['outer', 'mid', 'inner'].forEach(id => {\n    const el = $('#f2-' + id);\n    el.addEventListener('click', e => logTo(log, `capture: ${id}`), true);                 // capture 側\n    el.addEventListener('click', e => { logTo(log, `bubble:  ${id}` + (e.target === el ? '（target）' : '')); if (id === 'mid' && $('#f2-stop').checked) { e.stopPropagation(); logTo(log, '  → stopPropagation: ここで止める'); } });\n  });\n  $('#f2-inner').addEventListener('click', () => logTo(log, '---'));\n  $('#f2-clear').onclick = () => log.textContent = '';\n})();"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f3","title":"F3transform と left/top の違い レイアウト vs 合成","what":"位置を動かす方法は2つあるが、コストが違う。left/top を変えるとブラウザはレイアウト計算（周囲の要素の位置も再計算）をやり直す。transform は最終的な合成段階で動かすだけで、レイアウトは走らない。だからデモは全部 transform で動かしている。opacity も同じく安い。","how":"操作：300個の箱を同じ動きで走らせ、フレーム時間を比べる。差が小さい端末もあるが、要素数が増えるほど開く。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"f3-left\">left/top で動かす</button><button id=\"f3-tf\">transform で動かす</button><span class=\"readout\" id=\"f3-out\">-</span></div>\n    <div id=\"f3-field\" class=\"f3-field\"></div>\n  </div>","css":".f3-field { position: relative; height: 120px; overflow: hidden; background: #fff; border: 1px solid #cbd5e1; }\n.f3-field i { position: absolute; width: 8px; height: 8px; border-radius: 50%; background: var(--accent); left: 0; top: 0; }","js":"(() => {\n  const field = $('#f3-field'), out = $('#f3-out'), N = 300;\n  field.innerHTML = Array.from({ length: N }, () => '<i></i>').join('');\n  const dots = $$('i', field);\n  const run = mode => {\n    const t0 = performance.now(); let frames = 0, worst = 0, last = t0;\n    const step = now => {\n      const p = (now - t0) / 1500; worst = Math.max(worst, now - last); last = now; frames++;\n      dots.forEach((d, i) => {\n        const x = p * 400 + (i % 30) * 6, y = 10 + Math.floor(i / 30) * 10 + Math.sin(p * 6 + i) * 4;\n        if (mode === 'left') { d.style.left = x + 'px'; d.style.top = y + 'px'; d.style.transform = ''; }\n        else { d.style.transform = `translate(${x}px, ${y}px)`; d.style.left = d.style.top = ''; }\n      });\n      if (p < 1) requestAnimationFrame(step); else out.textContent = `${mode}: 平均 ${((now - t0) / frames).toFixed(1)} ms/frame, 最悪 ${worst.toFixed(1)} ms`;\n    };\n    requestAnimationFrame(step);\n  };\n  $('#f3-left').onclick = () => run('left'); $('#f3-tf').onclick = () => run('transform');\n})();"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f4","title":"F4passive リスナーと touch-action スクロールを止めたいのに止まらない理由","what":"ブラウザは wheel / touchmove を「既定で passive（preventDefault が効かない）」として扱うことがある。自前でズームやパンをするなら { passive: false } を明示する。タッチでは加えて CSS の touch-action で「どの方向をブラウザに任せるか」を宣言する方が確実。","how":"操作：左右の枠でホイール。左は preventDefault が無視されてページがスクロールする。右は止まる。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"align-items:stretch\">\n      <div id=\"f4-a\" class=\"f4-box\">passive: true<br><small>preventDefault は無視される</small><br><span class=\"readout\" id=\"f4-a-out\">-</span></div>\n      <div id=\"f4-b\" class=\"f4-box\">passive: false<br><small>ページは動かない</small><br><span class=\"readout\" id=\"f4-b-out\">-</span></div>\n    </div>\n  </div>","css":".f4-box { flex: 1; padding: 14px; background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; font-size: 13px; text-align: center; touch-action: none; }","js":"(() => {\n  $('#f4-a').addEventListener('wheel', e => { e.preventDefault(); $('#f4-a-out').textContent = `defaultPrevented=${e.defaultPrevented}`; }, { passive: true });   // 効かない（コンソールに警告）\n  $('#f4-b').addEventListener('wheel', e => { e.preventDefault(); $('#f4-b-out').textContent = `defaultPrevented=${e.defaultPrevented}`; }, { passive: false });  // 効く\n})();"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f5","title":"F5動かし方の4手段 transition / CSS animation / WAAPI / requestAnimationFrame","what":"同じ「右に300px動かす」でも手段が4つある。使い分けの軸は「誰が時間を管理するか」と「途中で介入したいか」。迷ったら transition、JSで止めたり戻したりするなら WAAPI、毎フレーム値を計算するなら rAF。","how":"操作：再生。4つが同じ動きをするのを確認し、下の表で選び方を見る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"f5-run\">再生</button></div>\n    <div class=\"f5-lane\"><span>1. transition</span><div class=\"f5-ball f5-tr\"></div></div>\n    <div class=\"f5-lane\"><span>2. CSS animation</span><div class=\"f5-ball f5-an\"></div></div>\n    <div class=\"f5-lane\"><span>3. WAAPI</span><div class=\"f5-ball f5-wa\"></div></div>\n    <div class=\"f5-lane\"><span>4. rAF</span><div class=\"f5-ball f5-raf\"></div></div>\n    <table class=\"cmp\" style=\"margin-top:8px\">\n      <tr><th>手段</th><th>時間管理</th><th>向いている場面</th><th>途中介入</th><th>デモ</th></tr>\n      <tr><td class=\"k\">transition</td><td>ブラウザ</td><td>状態AとBの間を補間する。ホバー、開閉、表示切替</td><td>弱い（クラスを外すと戻るだけ）</td><td><a href=\"02-basic.html#n14\">14</a></td></tr>\n      <tr><td class=\"k\">CSS animation</td><td>ブラウザ</td><td>繰り返し、複数キーフレーム、ローディング</td><td>弱い</td><td><a href=\"02-basic.html#n22\">22</a>, <a href=\"06-effects.html#n64\">64</a></td></tr>\n      <tr><td class=\"k\">WAAPI</td><td>ブラウザ（JSから制御）</td><td>一時停止・逆再生・速度変更・完了待ちが要る</td><td>強い</td><td><a href=\"04-pro.html#n53\">53</a>, <a href=\"03-custom.html#n30\">30</a></td></tr>\n      <tr><td class=\"k\">rAF</td><td>自分</td><td>物理（慣性・スプリング）、入力追従、Canvas</td><td>完全</td><td><a href=\"03-custom.html#n28\">28</a>, <a href=\"03-custom.html#n29\">29</a></td></tr>\n    </table>\n  </div>","css":".f5-lane { position: relative; height: 28px; margin-bottom: 4px; background: #fff; border: 1px solid #e5e7eb; border-radius: 6px; }\n.f5-lane span { position: absolute; left: 8px; top: 4px; font-size: 12px; color: var(--muted); }\n.f5-ball { position: absolute; top: 3px; left: 4px; width: 20px; height: 20px; border-radius: 50%; background: var(--accent); }\n.f5-tr { transition: transform .8s ease-out; } .f5-tr.go { transform: translateX(300px); }\n@keyframes f5-move { to { transform: translateX(300px); } } .f5-an.go { animation: f5-move .8s ease-out forwards; }","js":"(() => {\n  $('#f5-run').onclick = () => {\n    const tr = $('.f5-tr'), an = $('.f5-an'), wa = $('.f5-wa'), raf = $('.f5-raf');\n    tr.classList.remove('go'); an.classList.remove('go'); void tr.offsetWidth;                       // リセット\n    tr.classList.add('go');                                                                          // 1. transition：クラス付与\n    an.classList.add('go');                                                                          // 2. CSS animation：クラス付与\n    wa.animate([{ transform: 'none' }, { transform: 'translateX(300px)' }], { duration: 800, easing: 'ease-out', fill: 'forwards' }); // 3. WAAPI\n    const t0 = performance.now(), ease = p => 1 - (1 - p) ** 3;                                    // 4. rAF：自分で補間\n    const step = now => { const p = Math.min(1, (now - t0) / 800); raf.style.transform = `translateX(${ease(p) * 300}px)`; if (p < 1) requestAnimationFrame(step); };\n    requestAnimationFrame(step);\n  };\n})();"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f6","title":"F6スロットルとデバウンス Throttle / Debounce","what":"高頻度イベント（scroll, pointermove, input, resize）の間引き方は2種類。デバウンス＝止まってから1回（検索、保存）。スロットル＝一定間隔で1回（スクロール連動、進捗表示）。描画目的なら 54 の rAF バッチが第3の選択肢。","how":"操作：灰色の帯でマウスを動かす。3つのカウンタの増え方を比べる。","html":"<div class=\"stage\">\n    <div id=\"f6-area\" class=\"f6-area\">ここでマウスを動かす</div>\n    <div class=\"row\"><span class=\"readout\" id=\"f6-raw\">raw: 0</span><span class=\"readout\" id=\"f6-th\">throttle(100ms): 0</span><span class=\"readout\" id=\"f6-db\">debounce(300ms): 0</span></div>\n  </div>","css":".f6-area { height: 70px; background: #e2e8f0; border-radius: 8px; display: grid; place-items: center; color: var(--muted); margin-bottom: 8px; }","js":"(() => {\n  const throttle = (fn, ms) => { let last = 0; return (...a) => { const now = Date.now(); if (now - last >= ms) { last = now; fn(...a); } }; };\n  const debounce = (fn, ms) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };\n  let raw = 0, th = 0, db = 0;\n  const onTh = throttle(() => $('#f6-th').textContent = `throttle(100ms): ${++th}`, 100);\n  const onDb = debounce(() => $('#f6-db').textContent = `debounce(300ms): ${++db}`, 300);\n  $('#f6-area').addEventListener('pointermove', () => { $('#f6-raw').textContent = `raw: ${++raw}`; onTh(); onDb(); });\n})();"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f7","title":"F7重なり順とスタッキングコンテキスト z-index が効かない理由","what":"z-index は「同じスタッキングコンテキスト内」でしか比較されない。親に transform・opacity&lt;1・filter・position + z-index などがあると、そこで新しいコンテキストができ、子の z-index がいくら大きくても親の外の要素を追い越せない。ツールチップやドロップダウンが「下に潜る」原因の9割はこれ。","how":"操作：チェックで左の親に transform を付ける。子の z-index:999 が右の z-index:1 に負ける。","html":"<div class=\"stage\">\n    <div class=\"row\"><label><input type=\"checkbox\" id=\"f7-tf\"> 左の親に transform: translateZ(0) を付ける（新しいスタッキングコンテキスト）</label></div>\n    <div class=\"row\" style=\"align-items:flex-start;position:relative;height:90px\">\n      <div id=\"f7-parent\" class=\"f7-parent\">親<div class=\"f7-child\">子 z-index:999</div></div>\n      <div class=\"f7-other\">隣 z-index:1</div>\n    </div>\n  </div>","css":".f7-parent { position: relative; width: 140px; height: 60px; background: #fff; border: 1px solid #94a3b8; font-size: 12px; padding: 4px; }\n.f7-parent.ctx { transform: translateZ(0); }\n.f7-child { position: absolute; left: 60px; top: 20px; width: 150px; height: 50px; background: var(--accent); color: #fff; z-index: 999; padding: 4px; }\n.f7-other { position: absolute; left: 120px; top: 30px; width: 140px; height: 50px; background: #fde68a; z-index: 1; font-size: 12px; padding: 4px; }","js":"(() => { $('#f7-tf').onchange = e => $('#f7-parent').classList.toggle('ctx', e.target.checked); })();"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f9","title":"F9レイアウトスラッシング 読み取りと書き込みを交互にすると遅くなる","what":"DOM の「幅を読む（offsetWidth, getBoundingClientRect）」と「スタイルを書く」を1要素ずつ交互にやると、ブラウザは書くたびにレイアウトをやり直してから読む（強制同期レイアウト）。先に全部読んでから、全部書くだけで桁違いに速くなる。FLIP（30）の「First を全部測ってから DOM を変える」もこの原則。","how":"操作：500要素で2つの方式を実行し、時間を比べる。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"f9-bad\">交互（読→書→読→書…）</button><button id=\"f9-good\">分離（全部読む→全部書く）</button><span class=\"readout\" id=\"f9-out\">-</span></div>\n    <div id=\"f9-field\" class=\"f9-field\"></div>\n  </div>","css":".f9-field { display: flex; flex-wrap: wrap; gap: 2px; background: #fff; border: 1px solid #cbd5e1; padding: 4px; max-height: 90px; overflow: hidden; }\n.f9-field i { display: block; width: 12px; height: 12px; background: var(--accent); }","js":"(() => {\n  const field = $('#f9-field'), out = $('#f9-out');\n  field.innerHTML = Array.from({ length: 500 }, () => '<i></i>').join('');\n  const items = $$('i', field);\n  $('#f9-bad').onclick = () => {\n    const t0 = performance.now();\n    items.forEach(el => { const w = el.offsetWidth; el.style.width = (w % 2 ? 12 : 13) + 'px'; });   // 読→書 を交互：毎回レイアウト\n    out.textContent = `交互: ${(performance.now() - t0).toFixed(1)} ms`;\n  };\n  $('#f9-good').onclick = () => {\n    const t0 = performance.now();\n    const widths = items.map(el => el.offsetWidth);                                              // 全部読む（レイアウト1回）\n    items.forEach((el, i) => el.style.width = (widths[i] % 2 ? 12 : 13) + 'px');                // 全部書く\n    out.textContent = `分離: ${(performance.now() - t0).toFixed(1)} ms`;\n  };\n})();"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f10","title":"F10計測の道具 performance.now / PerformanceObserver(longtask) / rAF フレーム時間","what":"「重い気がする」を数字にする3つの道具。①performance.now() で区間時間 ②PerformanceObserver の longtask で 50ms を超えてメインスレッドを塞いだ処理を検出 ③rAF の間隔でフレーム落ちを見る。開発者ツールの Performance タブが本命だが、実機で常時出しておくならこれ。","how":"操作：「重い処理を実行」で意図的に 120ms ブロックする。longtask が検出され、フレーム時間が跳ねる。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"f10-heavy\">重い処理を実行（120ms ブロック）</button><span class=\"readout\" id=\"f10-frame\">frame: -</span><span class=\"readout\" id=\"f10-long\">longtask: 0 件</span></div>\n    <div class=\"log\" id=\"f10-log\" style=\"height:80px\"></div>\n  </div>","css":"","js":"(() => {\n  const log = $('#f10-log'); let n = 0;\n  // ② longtask 監視（対応ブラウザのみ）\n  try { new PerformanceObserver(list => list.getEntries().forEach(e => { $('#f10-long').textContent = `longtask: ${++n} 件`; logTo(log, `longtask ${e.duration.toFixed(0)}ms @ ${e.startTime.toFixed(0)}`); })).observe({ type: 'longtask', buffered: true }); }\n  catch { logTo(log, 'longtask 非対応のブラウザ'); }\n  // ③ フレーム時間（最大値を1秒ごとに表示）\n  let last = performance.now(), worst = 0, t = last;\n  const tick = now => { worst = Math.max(worst, now - last); last = now; if (now - t > 1000) { $('#f10-frame').textContent = `frame 最悪: ${worst.toFixed(1)} ms`; worst = 0; t = now; } requestAnimationFrame(tick); };\n  requestAnimationFrame(tick);\n  // ① 区間計測\n  $('#f10-heavy').onclick = () => { const t0 = performance.now(); while (performance.now() - t0 < 120) {} logTo(log, `区間: ${(performance.now() - t0).toFixed(1)}ms（同期ブロック）`); };\n})();"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f11","title":"F11イベントループと描画のタイミング 同期処理 → microtask → 描画 → setTimeout","what":"JS は「今の処理が全部終わってから」描画する。だから クラスを外して即付け直しても、間に描画が無いので何も起きない（14・64 の void el.offsetWidth はレイアウトを強制して「外した状態」を確定させる裏技）。順序は：同期コード → microtask（Promise.then, await の続き）→ requestAnimationFrame → 描画 → setTimeout。「描画してから次をやりたい」なら rAF を2回重ねる。","how":"操作：「順序を見る」で各コールバックの実行順をログに出す。「再アニメーション」で、リフロー強制あり／なしの違いを見る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"f11-order\">順序を見る</button><button id=\"f11-bad\">再アニメーション（リフローなし＝動かない）</button><button id=\"f11-good\">再アニメーション（void offsetWidth）</button><button id=\"f11-raf\">再アニメーション（rAF 2回）</button></div>\n    <div class=\"row\"><div id=\"f11-ball\" class=\"f11-ball\"></div><div class=\"log\" id=\"f11-log\" style=\"flex:1;height:120px\"></div></div>\n  </div>","css":".f11-ball { width: 30px; height: 30px; border-radius: 50%; background: var(--accent); }\n.f11-ball.pop { animation: f11-pop .5s ease-out; }\n@keyframes f11-pop { 30% { transform: scale(1.6); } }","js":"(() => {\n  const log = $('#f11-log'), ball = $('#f11-ball');\n  $('#f11-order').onclick = () => {\n    log.textContent = '';\n    setTimeout(() => logTo(log, '5. setTimeout(0)（描画の後）'), 0);\n    requestAnimationFrame(() => { logTo(log, '3. requestAnimationFrame（描画の直前）'); requestAnimationFrame(() => logTo(log, '4. rAF の中の rAF（次のフレーム＝描画済み）')); });\n    Promise.resolve().then(() => logTo(log, '2. Promise.then（microtask：同期処理の直後、描画の前）'));\n    logTo(log, '1. 同期コード');\n  };\n  $('#f11-bad').onclick = () => { ball.classList.remove('pop'); ball.classList.add('pop'); };                       // 間に描画が無い → 変化なし扱い\n  $('#f11-good').onclick = () => { ball.classList.remove('pop'); void ball.offsetWidth; ball.classList.add('pop'); }; // レイアウト強制で「外れた」を確定\n  $('#f11-raf').onclick = () => { ball.classList.remove('pop'); requestAnimationFrame(() => requestAnimationFrame(() => ball.classList.add('pop'))); }; // 1フレーム描かせてから付ける\n})();"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a1","title":"A1キーボードだけで操作できるか フォーカス順の可視化","what":"マウスなしで全機能に届くか。Tab の順番が見た目の順と一致しているか、フォーカスが見えるか、閉じ込められて抜けられない箇所がないか。下のボタンで、このページ内の「フォーカスできる要素」に番号を振って順路を可視化する。","how":"操作：「フォーカス順を表示」→ 番号が見た目の順に並んでいるか確認。その後 Tab で実際に辿る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"a1-show\">フォーカス順を表示</button><button id=\"a1-hide\">消す</button><span class=\"readout\" id=\"a1-out\">-</span></div>\n    <div class=\"row\"><button>1つ目</button><a href=\"#a1\">リンク</a><input type=\"text\" placeholder=\"入力\"><div tabindex=\"0\" class=\"box\" style=\"width:auto;height:auto;padding:6px 10px\">tabindex=0 の div</div><div class=\"box\" style=\"width:auto;height:auto;padding:6px 10px;background:#94a3b8\">tabindex なし（届かない）</div><button tabindex=\"-1\">tabindex=-1（Tabで届かない）</button></div>\n  </div>","css":".a11y-badge { position: absolute; z-index: 999; background: #dc2626; color: #fff; font: 700 11px/1 system-ui; padding: 2px 5px; border-radius: 3px; pointer-events: none; }","js":"(() => {\n  const SEL = 'a[href], button, input, select, textarea, [tabindex]';\n  const focusable = () => $$(SEL).filter(el => !el.disabled && el.tabIndex >= 0 && el.getClientRects().length);\n  $('#a1-show').onclick = () => {\n    $$('.a11y-badge').forEach(b => b.remove());\n    const list = focusable();\n    list.forEach((el, i) => { const r = el.getBoundingClientRect(); const b = document.createElement('span'); b.className = 'a11y-badge'; b.textContent = i + 1; b.style.left = r.left + scrollX + 'px'; b.style.top = r.top + scrollY - 8 + 'px'; document.body.appendChild(b); });\n    $('#a1-out').textContent = `フォーカス可能: ${list.length} 個`;\n  };\n  $('#a1-hide').onclick = () => $$('.a11y-badge').forEach(b => b.remove());\n})();"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a2","title":"A2読み上げに何が伝わるか アクセシブルネームと role","what":"スクリーンリーダーは「役割（role）」と「名前（accessible name）」を読む。アイコンだけのボタンは名前が空になる。aria-label か視覚的に隠したテキストで名前を与える。下の検査は、ページ内のボタン・リンクで名前が空のものを列挙する。","how":"操作：「名前のない操作要素を探す」。右の例は意図的に名前が無い。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"a2-scan\">名前のない操作要素を探す</button><span class=\"readout\" id=\"a2-out\">-</span></div>\n    <div class=\"row\">\n      <button title=\"良い例: aria-label あり\" aria-label=\"削除\">🗑</button>\n      <button title=\"悪い例: 名前なし\">🗑</button>\n      <button title=\"良い例: 隠しテキスト\">🔍<span class=\"a2-sr\">検索</span></button>\n      <a href=\"#a2\" title=\"悪い例: 名前なし\"><span style=\"display:inline-block;width:16px;height:16px;background:#94a3b8;border-radius:3px\"></span></a>\n    </div>\n    <div class=\"log\" id=\"a2-log\" style=\"height:70px\"></div>\n  </div>","css":"/* 視覚的に隠すが読み上げには残す（display:none は読み上げも消える） */\n.a2-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }","js":"(() => {\n  const name = el => (el.getAttribute('aria-label') || el.getAttribute('aria-labelledby') && document.getElementById(el.getAttribute('aria-labelledby'))?.textContent || el.textContent || el.getAttribute('title') || '').trim();\n  $('#a2-scan').onclick = () => {\n    const log = $('#a2-log'); log.textContent = '';\n    const bad = $$('button, a[href]').filter(el => !name(el).replace(/[\\u{1F300}-\\u{1FAFF}\\s]/gu, ''));\n    bad.forEach(el => logTo(log, `${el.tagName.toLowerCase()}: \"${el.outerHTML.slice(0, 60)}…\" → 名前なし`));\n    $('#a2-out').textContent = `名前のない要素: ${bad.length} 個（title はブラウザにより読まれないので不十分）`;\n  };\n})();"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a3","title":"A3コントラスト比 WCAG 4.5:1（通常文字）/ 3:1（大きな文字・UI部品）","what":"現場の照明や古いモニタでは、薄い灰色の文字は読めない。文字色と背景色から比率を計算し、基準を満たすか確認する。計算式は WCAG の相対輝度。","how":"操作：色を変えて比率を見る。","html":"<div class=\"stage\">\n    <div class=\"row\">文字 <input type=\"color\" id=\"a3-fg\" value=\"#6b7280\"> 背景 <input type=\"color\" id=\"a3-bg\" value=\"#ffffff\"> <span class=\"readout\" id=\"a3-out\"></span></div>\n    <div id=\"a3-sample\" style=\"padding:10px 14px;border-radius:6px;font-size:14px\">サンプル文字：受注 #1001 納期 2026-09-12</div>\n  </div>","css":"","js":"(() => {\n  const lum = hex => { const c = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16) / 255).map(v => v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4); return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]; };\n  const ratio = (a, b) => { const [l1, l2] = [lum(a), lum(b)].sort((x, y) => y - x); return (l1 + 0.05) / (l2 + 0.05); };\n  const upd = () => { const fg = $('#a3-fg').value, bg = $('#a3-bg').value, r = ratio(fg, bg); Object.assign($('#a3-sample').style, { color: fg, background: bg }); $('#a3-out').textContent = `${r.toFixed(2)} : 1 → 通常文字 ${r >= 4.5 ? '合格' : '不合格'} / 大きな文字・UI ${r >= 3 ? '合格' : '不合格'}`; };\n  $('#a3-fg').oninput = $('#a3-bg').oninput = upd; upd();\n})();"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a4","title":"A4非同期結果の通知 aria-live の polite / assertive","what":"保存完了やエラーを画面の隅に出しても、読み上げユーザーには伝わらない。aria-live 領域にテキストを書くと自動で読み上げられる。polite は今の読み上げが終わってから、assertive は割り込む（エラー用）。領域は最初から存在させ、中身だけ変える。","how":"操作：ボタンで通知。スクリーンリーダー（Windows: ナレーター Win+Ctrl+Enter、macOS: VoiceOver Cmd+F5）を起動して聞く。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"a4-ok\">保存成功（polite）</button><button id=\"a4-ng\">エラー（assertive）</button></div>\n    <div class=\"readout\" id=\"a4-polite\" aria-live=\"polite\" role=\"status\">（status 領域）</div>\n    <div class=\"readout\" id=\"a4-assert\" aria-live=\"assertive\" role=\"alert\" style=\"margin-top:6px;color:#dc2626\">（alert 領域）</div>\n  </div>","css":"","js":"(() => {\n  let n = 0;\n  $('#a4-ok').onclick = () => $('#a4-polite').textContent = `レコード #${1000 + ++n} を保存しました`;\n  $('#a4-ng').onclick = () => $('#a4-assert').textContent = `保存に失敗しました（通信エラー）`;\n})();"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a5","title":"A5環境設定の尊重 reduced-motion / contrast / color-scheme / forced-colors","what":"OS の設定をメディアクエリで拾える。動きを減らす、コントラストを上げる、ダークモード、Windows のハイコントラストモード（forced-colors、色指定が無視される）。この環境の現在値を表示する。","how":"","html":"<div class=\"stage\"><table class=\"cmp\" id=\"a5-t\"></table></div>","css":"","js":"(() => {\n  const Q = [['prefers-reduced-motion: reduce', '動きを減らす → アニメーションを短縮・省略（42）'], ['prefers-contrast: more', 'コントラストを上げる → 枠線・文字色を濃く'], ['prefers-color-scheme: dark', 'ダークモード → 配色を切替（70）'], ['forced-colors: active', 'ハイコントラストモード → 背景色で状態を表すUIは消える。枠線・アイコンで表す'], ['hover: hover', 'ホバー可能な入力装置（06）'], ['pointer: coarse', '粗いポインタ（指）→ 当たり判定を 44px 以上に']];\n  const render = () => $('#a5-t').innerHTML = '<tr><th>メディアクエリ</th><th>この環境</th><th>対応</th></tr>' + Q.map(([q, d]) => `<tr><td><code>@media (${q})</code></td><td>${matchMedia(`(${q})`).matches ? '<b>該当</b>' : '—'}</td><td>${d}</td></tr>`).join('');\n  Q.forEach(([q]) => matchMedia(`(${q})`).addEventListener('change', render)); render();\n})();"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a7","title":"A7canvas と 3D の代替経路 見えない中身をどう伝えるか","what":"&lt;canvas&gt; の中身は支援技術から完全に見えない。画素があるだけで、要素も文字も無いためである。3D ビューア（Z層）・グラフ・図面エディタはすべてこれに当たる。やることは3つ。①canvas 自体をフォーカスできる操作対象にする（tabindex=\"0\" ＋ role ＋ aria-label）②キーボードだけで一巡できるようにする（矢印キーで対象を順に選ぶ）③選択結果や測定値を canvas の外の文字として出す（aria-live）。「見て触る」前提の UI ほど、代替経路を後から足せないので最初に決める。","how":"操作：下の枠を Tab で選び、矢印キーで部品を順に選ぶ。Enter で確定、Esc で解除。読み上げに渡る文字が右に出る。マウスでも同じことができる。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <canvas id=\"a7c\" width=\"360\" height=\"150\" tabindex=\"0\" role=\"application\"\n        aria-label=\"部品ビュー。矢印キーで部品を選択、Enter で確定、Esc で解除\"\n        style=\"border:1px solid var(--line);border-radius:8px;background:#0f172a;max-width:100%\"></canvas>\n      <div style=\"flex:1;min-width:180px\">\n        <div style=\"font-size:11px;color:var(--muted)\">読み上げに渡る文字（aria-live）</div>\n        <div id=\"a7live\" aria-live=\"polite\" style=\"min-height:44px;border:1px dashed var(--line);border-radius:6px;padding:6px;font-size:13px\">（未選択）</div>\n        <div style=\"font-size:11px;color:var(--muted);margin-top:6px\">代替の一覧（canvas と同じ内容を文字で持つ）</div>\n        <ul id=\"a7list\" style=\"margin:4px 0 0;padding-left:18px;font-size:13px\"></ul>\n      </div>\n    </div>\n  </div>","css":"","js":"(() => {\n  // canvas の内容は「配列」として先に持つ。描画はその写像にすぎない、という作りにするのが要点\n  const PARTS = [\n    { name: '台座', x: 20,  y: 95, w: 320, h: 30, color: '#64748b' },\n    { name: '支柱A', x: 70,  y: 35, w: 40,  h: 60, color: '#2563eb' },\n    { name: '支柱B', x: 250, y: 35, w: 40,  h: 60, color: '#2563eb' },\n    { name: '梁',   x: 70,  y: 20, w: 220, h: 15, color: '#16a34a' },\n  ];\n  const c = $('#a7c'), g = c.getContext('2d'), live = $('#a7live');\n  let sel = -1;\n\n  const draw = () => {\n    g.fillStyle = '#0f172a'; g.fillRect(0, 0, c.width, c.height);\n    PARTS.forEach((p, i) => {\n      g.fillStyle = p.color; g.fillRect(p.x, p.y, p.w, p.h);\n      if (i === sel) { g.strokeStyle = '#fbbf24'; g.lineWidth = 3; g.strokeRect(p.x - 2, p.y - 2, p.w + 4, p.h + 4); }\n    });\n  };\n  const say = t => live.textContent = t;                    // ③ canvas の外に文字で出す\n  const select = i => {\n    sel = i; draw();\n    // 代替一覧の選択状態も属性で表す（色だけで示さない）\n    $$('#a7list li').forEach((li, k) => li.setAttribute('aria-current', k === i ? 'true' : 'false'));\n    say(i < 0 ? '選択を解除しました' : `${PARTS[i].name} を選択（${i + 1} / ${PARTS.length}）`);\n  };\n\n  // ② キーボードだけで一巡できるようにする\n  // check-ime-ignore : canvas は文字入力欄ではないため変換が発生しない\n  c.addEventListener('keydown', e => {\n    const n = PARTS.length;\n    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') select((sel + 1 + n) % n);\n    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') select((sel - 1 + n) % n);\n    else if (e.key === 'Escape') select(-1);\n    else if (e.key === 'Enter' && sel >= 0) return say(`${PARTS[sel].name} を確定しました`);\n    else return;\n    e.preventDefault();                                     // 矢印でページがスクロールしないように\n  });\n  c.addEventListener('focus', () => { if (sel < 0) say('部品ビューにフォーカス。矢印キーで部品を選べます'); });\n  c.addEventListener('pointerdown', e => {                  // マウス経路も同じ select を通す\n    const r = c.getBoundingClientRect(), x = (e.clientX - r.left) * c.width / r.width, y = (e.clientY - r.top) * c.height / r.height;\n    const i = PARTS.findIndex(p => x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h);\n    c.focus(); select(i);\n  });\n\n  // ①' 代替の一覧：canvas と同じ内容を DOM でも持つ。読み上げにも検索にも印刷にも効く\n  $('#a7list').innerHTML = PARTS.map((p, i) =>\n    `<li><a href=\"#\" data-i=\"${i}\">${p.name}</a></li>`).join('');\n  $('#a7list').addEventListener('click', e => {\n    const a = e.target.closest('a[data-i]'); if (!a) return;\n    e.preventDefault(); select(Number(a.dataset.i));\n  });\n  draw();\n})();"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n88","title":"88出入りのアニメーション @starting-style / transition-behavior: allow-discrete","what":"display: none の要素は「表示した瞬間の初期値」が無いためアニメーションできず、12 のように opacity だけで消す（要素は残る）か、JS で二段階に切り替えていた。@starting-style が出現時の初期値を与え、transition-behavior: allow-discrete が display の切り替えを遷移の最後まで遅らせるので、出入り両方が CSS だけで書ける。","how":"操作：トグル。閉じるときも最後まで見えている（display の切替が遅延される）。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s88-btn\">表示を切り替え</button><span class=\"readout\">JS はクラスの付け外しだけ</span></div>\n    <div id=\"s88-panel\" class=\"s88-panel\">通知パネル：出るときも消えるときもアニメーションする</div>\n  </div>","css":".s88-panel {\n  display: none; opacity: 0; transform: translateY(-8px);\n  background: var(--accent); color: #fff; padding: 12px 16px; border-radius: 8px; font-size: 13px;\n  transition: opacity .3s, transform .3s, display .3s allow-discrete;   /* display も遷移対象にする */\n}\n.s88-panel.open { display: block; opacity: 1; transform: none; }\n@starting-style { .s88-panel.open { opacity: 0; transform: translateY(-8px); } }  /* 出現時の初期値 */","js":"(() => { $('#s88-btn').onclick = () => $('#s88-panel').classList.toggle('open'); })();"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n91","title":"91height: auto へのアニメーション interpolate-size / calc-size()","what":"18（アコーディオン）で触れた「height: auto にはトランジションが効かない」という長年の壁。interpolate-size: allow-keywords を指定すると auto や min-content への遷移が補間できるようになり、grid の 0fr→1fr という回避策も、JS で scrollHeight を測る処理も要らなくなる。","how":"操作：開閉する。中身の長さが違っても、高さを測らずに滑らかに開く。","html":"<div class=\"stage\">\n    <div class=\"s91\">\n      <button class=\"s91-head\">出荷条件 ▾</button>\n      <div class=\"s91-body\"><p>納期は受注後5営業日。分納可。梱包は標準仕様。</p></div>\n    </div>\n    <div class=\"s91\">\n      <button class=\"s91-head\">支払条件 ▾</button>\n      <div class=\"s91-body\"><p>月末締め翌月末払い。手形不可。</p><p>与信枠を超える場合は前金。</p><p>請求書は電子送付。</p></div>\n    </div>\n  </div>","css":".s91 { interpolate-size: allow-keywords; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; margin-bottom: 6px; overflow: hidden; }\n.s91-head { width: 100%; text-align: left; border: none; border-radius: 0; }\n.s91-body { height: 0; overflow: hidden; transition: height .3s ease; }\n.s91-body p { margin: 0; padding: 4px 12px; font-size: 13px; }\n.s91:has(.s91-head:focus) .s91-body, .s91.open .s91-body { height: auto; padding: 6px 0; }   /* auto へ遷移できる */","js":"(() => { $$('.s91-head').forEach(h => h.onclick = () => h.parentElement.classList.toggle('open')); })();"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n94","title":"94画面外の描画を省く content-visibility: auto / contain-intrinsic-size","what":"23 の仮想スクロールは「DOM を作らない」方式で最速だが、実装コストが高い。content-visibility: auto はDOM は置いたまま、画面外の描画とレイアウトだけを省く。contain-intrinsic-size で仮の大きさを教えるとスクロールバーも安定する。数百〜数千行なら実装ゼロでこれで足りることが多い。","how":"操作：切り替えて描画時間を比べる（1,000 行）。","html":"<div class=\"stage\">\n    <div class=\"row\"><label><input type=\"checkbox\" id=\"s94-cv\" checked> content-visibility: auto</label><button id=\"s94-measure\">再描画して測る</button><span class=\"readout\" id=\"s94-out\">-</span></div>\n    <div id=\"s94-list\" class=\"s94-list cv\"></div>\n  </div>","css":".s94-list { height: 200px; overflow: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 13px; }\n.s94-list .card { border-bottom: 1px solid #f1f5f9; padding: 8px 12px; }\n.s94-list.cv .card { content-visibility: auto; contain-intrinsic-size: auto 37px; }  /* 画面外は描画しない */","js":"(() => {\n  const list = $('#s94-list'), out = $('#s94-out');\n  const fill = () => {\n    const t0 = performance.now();\n    list.innerHTML = Array.from({ length: 1000 }, (_, i) =>\n      `<div class=\"card\"><b>受注 #${1000 + i}</b> 株式会社サンプル / 納期 2026-10-${String(i % 28 + 1).padStart(2, '0')} / 数量 ${(i % 9 + 1) * 10}</div>`).join('');\n    list.offsetHeight;                                    // レイアウトを確定させてから測る\n    out.textContent = `1,000 行の描画: ${(performance.now() - t0).toFixed(1)} ms`;\n  };\n  $('#s94-cv').onchange = e => { list.classList.toggle('cv', e.target.checked); fill(); };\n  $('#s94-measure').onclick = fill; fill();\n})();"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n95","title":"95テーマと色の計算 light-dark() / color-mix() / oklch()","what":"70 のテーマ切替は「ライト用とダーク用の変数を2セット書く」形だった。light-dark() は1行で両方を書ける。color-mix() は基準色1つから、ホバー・無効・枠線の色を自動で作れるので、配色の定義が減る。oklch() は明度が知覚とほぼ一致するため、混ぜても濁りにくい。","how":"操作：基準色とテーマを変える。派生色は全て計算で作られる。","html":"<div class=\"stage\">\n    <div class=\"row\">基準色 <input type=\"color\" id=\"s95-c\" value=\"#2563eb\"><label><input type=\"checkbox\" id=\"s95-dark\"> ダーク</label><span class=\"readout\" id=\"s95-out\"></span></div>\n    <div id=\"s95-box\" class=\"s95-box\">\n      <button class=\"s95-btn\">主ボタン</button>\n      <button class=\"s95-btn ghost\">副ボタン</button>\n      <button class=\"s95-btn\" disabled>無効</button>\n      <div class=\"s95-card\">カード：背景は基準色を 92% 白に混ぜたもの</div>\n    </div>\n  </div>","css":".s95-box { --brand: #2563eb; color-scheme: light; padding: 14px; border-radius: 8px;\n  background: light-dark(#ffffff, #0f172a); color: light-dark(#1d1f23, #e6e9ee); }  /* 1行で両テーマ */\n.s95-box.dark { color-scheme: dark; }\n.s95-btn { background: var(--brand); color: #fff; border: none; padding: 6px 14px; border-radius: 6px; font: inherit; font-size: 13px; }\n.s95-btn:hover { background: color-mix(in oklch, var(--brand), black 15%); }          /* 濃く */\n.s95-btn:disabled { background: color-mix(in oklch, var(--brand), gray 60%); }        /* くすませる */\n.s95-btn.ghost { background: color-mix(in oklch, var(--brand), transparent 88%); color: var(--brand); }\n.s95-card { margin-top: 10px; padding: 10px; border-radius: 6px; font-size: 13px;\n  background: color-mix(in oklch, var(--brand), light-dark(white, black) 92%);\n  border: 1px solid color-mix(in oklch, var(--brand), transparent 70%); }","js":"(() => {\n  const box = $('#s95-box');\n  $('#s95-c').oninput = e => { box.style.setProperty('--brand', e.target.value); $('#s95-out').textContent = '派生色はすべて color-mix() で計算'; };\n  $('#s95-dark').onchange = e => box.classList.toggle('dark', e.target.checked);\n})();"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n96","title":"96状態を保ったまま移動する Element.moveBefore()","what":"32 の並べ替えは insertBefore で DOM を動かす。これは「一度取り外して付け直す」動作なので、iframe は再読み込みされ、フォーカスや再生中の動画・アニメーション・popover の開閉状態が失われる。moveBefore() は接続を保ったまま移動するため、状態が壊れない。グリッド内の埋め込み表示や入力途中の行を動かす場面で効く。","how":"操作：それぞれの「先頭へ」を押す。左（従来）はカウンタが 0 に戻り、右（moveBefore）は数え続ける。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <div style=\"flex:1\"><div class=\"row\"><b style=\"font-size:13px\">insertBefore（従来）</b><button id=\"s96-a-btn\">2番目を先頭へ</button></div><div id=\"s96-a\" class=\"s96-list\"></div></div>\n      <div style=\"flex:1\"><div class=\"row\"><b style=\"font-size:13px\">moveBefore（状態を保つ）</b><button id=\"s96-b-btn\">2番目を先頭へ</button></div><div id=\"s96-b\" class=\"s96-list\"></div></div>\n    </div>\n  </div>","css":".s96-list { background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; }\n.s96-list > div { display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-bottom: 1px solid #f1f5f9; font-size: 13px; }\n.s96-list iframe { width: 92px; height: 26px; border: 1px solid #e5e7eb; border-radius: 4px; }","js":"(() => {\n  // 中で経過秒を数え続ける iframe を並べる（再読み込みされると 0 に戻る）\n  const row = n => `<div>行 ${n} <iframe srcdoc='&lt;body style=\"margin:0;font:12px/26px system-ui;text-align:center\"&gt;&lt;span id=t&gt;0&lt;/span&gt; 秒&lt;script&gt;let s=0;setInterval(()=>t.textContent=++s,1000)&lt;\\/script&gt;'></iframe></div>`;\n  ['#s96-a', '#s96-b'].forEach(sel => $(sel).innerHTML = [1, 2, 3].map(row).join(''));\n  $('#s96-a-btn').onclick = () => { const l = $('#s96-a'); l.insertBefore(l.children[1], l.firstElementChild); };\n  $('#s96-b-btn').onclick = () => {\n    const l = $('#s96-b'), second = l.children[1];\n    if (l.moveBefore) l.moveBefore(second, l.firstElementChild);   // 非対応環境では従来の方法へ\n    else l.insertBefore(second, l.firstElementChild);\n  };\n})();"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n97","title":"97DOM を変えずに強調する CSS Custom Highlight API","what":"74 の検索ハイライトは一致部分を &lt;mark&gt; で囲むため、DOM を作り直す＝選択・フォーカス・イベントの結び付きが切れる。Custom Highlight API は文字範囲（Range）に名前を付けて色を塗るだけなので、DOM は一切変わらない。大量の一致でも軽い。","how":"操作：検索語を入れる。文章の DOM は変わらないまま色が付く（開発者ツールで確認できる）。","html":"<div class=\"stage\">\n    <div class=\"row\"><input id=\"s97-q\" type=\"search\" placeholder=\"例: 梱包 / 分納 / 検査\" style=\"width:220px\"><span class=\"readout\" id=\"s97-out\">-</span></div>\n    <div id=\"s97-text\" class=\"s97-text\">受注 #1001 の備考：梱包は強化仕様で依頼。分納可、初回は 60 個。検査成績書を同梱すること。次回以降の梱包は標準で構わない。検査は全数。</div>\n  </div>","css":".s97-text { background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 12px; font-size: 14px; line-height: 1.9; }\n::highlight(s97-hit) { background: #fde68a; color: #7c2d12; }      /* 名前を付けた範囲の見た目 */","js":"(() => {\n  const node = $('#s97-text').firstChild, out = $('#s97-out');\n  $('#s97-q').addEventListener('input', e => {\n    if (!window.CSS || !CSS.highlights) { out.textContent = '非対応：74 の <mark> 方式にフォールバック'; return; }\n    CSS.highlights.delete('s97-hit');\n    const q = e.target.value.trim(); if (!q) { out.textContent = '-'; return; }\n    const text = node.textContent, ranges = [];\n    for (let i = text.indexOf(q); i >= 0; i = text.indexOf(q, i + q.length)) {\n      const r = new Range(); r.setStart(node, i); r.setEnd(node, i + q.length); ranges.push(r);\n    }\n    if (ranges.length) CSS.highlights.set('s97-hit', new Highlight(...ranges));\n    out.textContent = `${ranges.length} 件（DOM の子要素数: ${$('#s97-text').children.length}）`;\n  });\n})();"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n98","title":"98長い処理で UI を止めない scheduler.yield() / long-animation-frame","what":"54 は「描画をまとめる」話だったが、逆に重い計算そのものが長すぎると、その間クリックもスクロールも効かなくなる（F10 の longtask）。await scheduler.yield() を挟むと、その場でブラウザに順番を譲り、続きは優先的に再開される（setTimeout(0) より順番待ちが短い）。CSV 変換や一括計算はこれで分割する。","how":"操作：3方式を試す。左の丸が回り続けるかを見る。総時間はどれもほぼ同じで、違うのは「途中で画面が動くか」だけ。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <div class=\"s98-spin\"></div>\n      <button id=\"s98-sync\">① 一気に処理（固まる）</button>\n      <button id=\"s98-timeout\">② setTimeout で分割</button>\n      <button id=\"s98-yield\">③ scheduler.yield で分割</button>\n      <span class=\"readout\" id=\"s98-out\">-</span>\n    </div>\n    <div class=\"log\" id=\"s98-log\" style=\"height:90px\"></div>\n    <p class=\"note\">① と ②③ の差は決定的（画面が 1.6 秒止まるか、止まらないか）。② と ③ の差は、ページが暇なときは小さい。混んでいるとき（他のタスクや入力があるとき）に、③ は待ち行列の後ろに回されず優先的に再開される点で有利になる。</p>\n  </div>","css":".s98-spin { width: 22px; height: 22px; border: 3px solid #e5e7eb; border-top-color: var(--accent); border-radius: 50%; animation: s98 .8s linear infinite; }\n@keyframes s98 { to { transform: rotate(360deg); } }","js":"(() => {\n  const log = $('#s98-log'), out = $('#s98-out');\n  const CHUNK = 40, TOTAL = 400;                               // 400 回 × 約 4ms の作業\n  const work = () => { const t = performance.now(); while (performance.now() - t < 4); };\n  // 「処理中に何フレーム描けたか」と「最も長く描画が止まった時間」を測る\n  let frames = 0, worst = 0, last = 0, running = false;\n  const loop = now => { frames++; worst = Math.max(worst, now - last); last = now; if (running) requestAnimationFrame(loop); };\n  const start = () => { frames = 0; worst = 0; last = performance.now(); running = true; requestAnimationFrame(loop); };\n  const finish = async (name, t0) => {\n    const took = performance.now() - t0;\n    await new Promise(r => setTimeout(r, 300));                // 直後のフレームまで拾ってから止める\n    running = false;\n    logTo(log, `${name}: 所要 ${took.toFixed(0)}ms ／ 処理中に描けたフレーム ${frames} ／ 最長の停止 ${worst.toFixed(0)}ms`);\n    out.textContent = `最長の停止 ${worst.toFixed(0)}ms`;\n  };\n  $('#s98-sync').onclick = async () => { start(); const t0 = performance.now(); for (let i = 0; i < TOTAL; i++) work(); await finish('① 一気に', t0); };\n  $('#s98-timeout').onclick = async () => { start(); const t0 = performance.now();\n    for (let i = 0; i < TOTAL; i++) { work(); if (i % CHUNK === CHUNK - 1) await new Promise(r => setTimeout(r, 0)); }\n    await finish('② setTimeout で分割', t0); };\n  $('#s98-yield').onclick = async () => { start(); const t0 = performance.now();\n    const yieldTo = window.scheduler?.yield ? () => scheduler.yield() : () => new Promise(r => setTimeout(r, 0));\n    for (let i = 0; i < TOTAL; i++) { work(); if (i % CHUNK === CHUNK - 1) await yieldTo(); }\n    await finish('③ scheduler.yield で分割', t0); };\n})();"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n99","title":"99業務コードが短くなる標準API Object.groupBy / toSorted / Promise.withResolvers / AbortSignal.any / Intl","what":"集計・並べ替え・非同期・書式で、自前のユーティリティを書かずに済むようになったもの。元の配列を壊さない（toSorted）、グループ化が1行（Object.groupBy）、外から解決できる Promise（withResolvers：ダイアログの戻り値待ちに最適）、複数の中断条件を束ねる（AbortSignal.any：タイムアウト＋ユーザー中断）。","how":"操作：実行して結果を見る。コードを開いて書き方を確認する。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s99-run\" class=\"primary\">実行</button></div>\n    <div class=\"log\" id=\"s99-log\" style=\"height:170px\"></div>\n  </div>","css":"","js":"(() => {\n  const log = $('#s99-log');\n  const recs = [\n    { id: 1, site: '本社', qty: 120, at: '2026-09-01' }, { id: 2, site: '第2工場', qty: 80, at: '2026-09-03' },\n    { id: 3, site: '本社', qty: 240, at: '2026-09-02' }, { id: 4, site: '倉庫', qty: 60, at: '2026-09-04' },\n  ];\n  $('#s99-run').onclick = async () => {\n    log.textContent = '';\n    // 1. 拠点ごとにまとめる（従来は reduce で 4〜5 行）\n    const byRecs = Object.groupBy(recs, r => r.site);\n    logTo(log, 'groupBy: ' + Object.entries(byRecs).map(([k, v]) => `${k}=${v.length}件`).join(' '));\n    // 2. 元を壊さずに並べ替え / 1件だけ差し替え\n    logTo(log, 'toSorted: ' + recs.toSorted((a, b) => b.qty - a.qty).map(r => r.qty).join(',') + '（元は ' + recs.map(r => r.qty).join(',') + '）');\n    logTo(log, 'with: ' + recs.with(0, { ...recs[0], qty: 999 })[0].qty + '（元は ' + recs[0].qty + '）');\n    // 3. 外から解決できる Promise（ダイアログの戻り値待ちがそのまま書ける）\n    const { promise, resolve } = Promise.withResolvers();\n    setTimeout(() => resolve('削除'), 300);\n    logTo(log, 'withResolvers: ユーザーの選択 = ' + await promise);\n    // 4. タイムアウトとユーザー中断を束ねる\n    const user = new AbortController();\n    const signal = AbortSignal.any([user.signal, AbortSignal.timeout(200)]);\n    await new Promise(r => signal.addEventListener('abort', r, { once: true }));\n    logTo(log, 'AbortSignal.any: 中断理由 = ' + signal.reason.name);\n    // 5. 書式（通貨・相対時刻・日本語の語区切り）\n    logTo(log, 'NumberFormat: ' + new Intl.NumberFormat('ja-JP', { style: 'currency', currency: 'JPY' }).format(1234567));\n    logTo(log, 'RelativeTimeFormat: ' + new Intl.RelativeTimeFormat('ja', { numeric: 'auto' }).format(-2, 'day'));\n    const seg = [...new Intl.Segmenter('ja', { granularity: 'word' }).segment('六角ボルトを検査する')].filter(s => s.isWordLike).map(s => s.segment);\n    logTo(log, 'Segmenter（語の区切り）: ' + seg.join(' / '));\n  };\n})();"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n100","title":"100カルーセルの操作部品 ::scroll-button() / ::scroll-marker","what":"25 のスクロールスナップに「前後ボタン」と「現在位置のドット」を付けるには JS が必要だった。::scroll-button() と ::scroll-marker はスクロール領域そのものから疑似要素として生やせる。押せない端では自動で :disabled になり、現在位置のマーカーには :target-current が付く。キーボード操作も付いてくる。","how":"操作：◀▶ とドットで移動する。JS なし。","html":"<div class=\"stage\">\n    <div class=\"s100\" id=\"s100\"></div>\n  </div>","css":".s100 { display: flex; gap: 12px; overflow-x: auto; scroll-snap-type: x mandatory; padding: 4px; scroll-behavior: smooth;\n  anchor-name: --s100; scroll-marker-group: after; }\n.s100 > div { flex: 0 0 200px; height: 110px; scroll-snap-align: center; background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; display: grid; place-items: center; font-size: 15px; }\n/* 前後ボタン：スクロール領域から生やす。端では自動で無効になる */\n.s100::scroll-button(left), .s100::scroll-button(right) {\n  position: absolute; position-anchor: --s100; top: anchor(center); translate: 0 -50%;\n  border: 1px solid #cbd5e1; background: #fff; border-radius: 50%; width: 32px; height: 32px; font-size: 14px; cursor: pointer; }\n.s100::scroll-button(left) { content: '◀'; position-area: left; }\n.s100::scroll-button(right) { content: '▶'; position-area: right; }\n.s100::scroll-button(*):disabled { opacity: .3; }\n/* 現在位置のドット */\n.s100::scroll-marker-group { display: flex; gap: 6px; justify-content: center; padding: 8px 0 0; }\n.s100 > div::scroll-marker { content: ''; width: 9px; height: 9px; border-radius: 50%; background: #cbd5e1; cursor: pointer; }\n.s100 > div::scroll-marker:target-current { background: var(--accent); }","js":"(() => { $('#s100').innerHTML = Array.from({ length: 6 }, (_, i) => `<div>工程 ${i + 1}</div>`).join(''); })();"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n101","title":"101並び順を CSS から使う sibling-index() / sibling-count()","what":"64 のスタガーは「何番目か」を style=\"--i:3\" と HTML に書くか JS で付けていた。sibling-index() はCSS が自分で順番を知るので、要素を増減しても何も直さなくてよい。遅延だけでなく、色や大きさの段階付けにも使える。","how":"操作：「行を足す」→「再生」。足した行にも自動で正しい遅延が付く。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s101-run\">再生</button><button id=\"s101-add\">行を足す</button><span class=\"readout\" id=\"s101-out\"></span></div>\n    <div id=\"s101-list\" class=\"s101\"></div>\n  </div>","css":".s101 > div { background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 6px 10px; margin-bottom: 4px; font-size: 13px;\n  opacity: 0; transform: translateX(-12px);\n  border-left: 4px solid color-mix(in oklch, var(--accent), #fff calc(sibling-index() * 8%));  /* 順番で色も段階的に */\n}\n.s101.go > div { animation: s101-in .35s ease-out forwards; animation-delay: calc(sibling-index() * 60ms); }  /* 何番目かを CSS が知っている */\n@keyframes s101-in { to { opacity: 1; transform: none; } }","js":"(() => {\n  const list = $('#s101-list'); let n = 0;\n  const add = () => list.insertAdjacentHTML('beforeend', `<div>工程 ${++n}</div>`);\n  for (let i = 0; i < 4; i++) add();\n  $('#s101-add').onclick = () => { add(); $('#s101-out').textContent = `${n} 行（HTML に番号は書いていない）`; };\n  $('#s101-run').onclick = () => { list.classList.remove('go'); void list.offsetWidth; list.classList.add('go'); };\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n102","title":"102この端末は何か 実測パネル","what":"まずは自分が今いる環境を知る。以下はすべてブラウザが答えた実際の値。現場で使う端末でこのページを開き、値を控えておくと、以降の判断（当たり判定の大きさ、ホバーの可否、使える API）が全部決まる。","how":"操作：ウィンドウの大きさを変える、タッチで触る、と値が変わる項目がある。","html":"<div class=\"stage\">\n    <table class=\"cmp\" id=\"s102-t\"></table>\n  </div>","css":":root { --svh: 1svh; }   /* 単位が使えるかを JS から確認するための置き場 */","js":"(() => {\n  const q = s => matchMedia(s).matches;\n  const rows = () => [\n    ['ポインタの精度', q('(pointer: fine)') ? 'fine（マウス・ペン）' : q('(pointer: coarse)') ? 'coarse（指）' : 'none', '当たり判定の大きさを決める（103）'],\n    ['ホバーできるか', q('(hover: hover)') ? 'できる' : 'できない', 'ホバー専用の情報を置けるか（06）'],\n    ['他の入力装置', [q('(any-pointer: fine)') && 'fine', q('(any-pointer: coarse)') && 'coarse'].filter(Boolean).join(' + ') || 'なし', 'タッチ＋マウス両対応か'],\n    ['画面', `${innerWidth}×${innerHeight} CSS px / dpr ${devicePixelRatio}`, 'Canvas の内部解像度（55）'],\n    ['ビューポート単位', `100svh=${getComputedStyle(document.documentElement).getPropertyValue('--svh').trim() || '-'} / 100dvh=${CSS.supports('height','100dvh') ? '対応' : '非対応'}`, 'モバイルのアドレスバー（105）'],\n    ['プラットフォーム', (navigator.userAgentData && navigator.userAgentData.platform) || navigator.platform || '不明', '修飾キーの表記（104）'],\n    ['タッチ点数', navigator.maxTouchPoints + ' 点', 'マルチタッチ（50）'],\n    ['動きを減らす設定', q('(prefers-reduced-motion: reduce)') ? 'ON' : 'OFF', 'アニメーションの省略（42）'],\n    ['配色の希望', q('(prefers-color-scheme: dark)') ? 'ダーク' : 'ライト', 'テーマ（70・95）'],\n    ['強制配色', q('(forced-colors: active)') ? 'ON（色指定は無視される）' : 'OFF', '枠線や記号で状態を示す（10）'],\n    ['言語', navigator.language + ' / ' + navigator.languages.join(','), '書式（99）'],\n    ['オンライン', navigator.onLine ? 'オンライン' : 'オフライン', '再送キュー（79）'],\n  ];\n  const render = () => $('#s102-t').innerHTML = '<tr><th>項目</th><th>この端末</th><th>効いてくる場所</th></tr>' +\n    rows().map(([k, v, u]) => `<tr><td class=\"k\">${k}</td><td><b>${v}</b></td><td>${u}</td></tr>`).join('');\n  addEventListener('resize', render); ['(pointer: fine)', '(hover: hover)', '(prefers-color-scheme: dark)'].forEach(m => matchMedia(m).addEventListener('change', render));\n  render();\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n103","title":"103入力装置と当たり判定 pointer / any-pointer / 44px","what":"マウスは 1px を狙えるが、指は狙えない。@media (pointer: coarse) で見た目を変えずに当たり判定だけ広げるのが定石（::before を伸ばす）。指で使う画面は 44×44px 以上が目安。タッチとマウスの両方が繋がる端末（現場のタブレット＋マウス）もあるので、`any-pointer` で「どちらも来る」前提にする。","how":"操作：下の2つのボタンの周囲（薄い枠）が実際の当たり判定。coarse の端末では自動で広がる。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"gap:30px\"><button class=\"s103 narrow\">狭い</button><button class=\"s103 wide\">広い（判定拡張）</button><span class=\"readout\" id=\"s103-out\"></span></div>\n  </div>","css":".s103 { position: relative; font-size: 12px; padding: 4px 8px; }\n.s103.wide::before { content: ''; position: absolute; inset: -10px; }         /* 見た目そのまま、判定だけ拡張 */\n.s103.wide { outline: 1px dashed #cbd5e1; outline-offset: 10px; }\n@media (pointer: coarse) {                                                     /* 指で使う端末では全体を大きく */\n  .s103 { min-width: 44px; min-height: 44px; font-size: 14px; }\n  .s103.wide::before { inset: -14px; }\n}","js":"(() => {\n  const fine = matchMedia('(pointer: fine)').matches;\n  $('#s103-out').textContent = fine ? 'この端末は fine：狭くても押せる' : 'この端末は coarse：44px 以上が必要';\n  $$('.s103').forEach(b => b.onclick = () => $('#s103-out').textContent = b.textContent + ' を押した');\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n104","title":"104修飾キーの差 Ctrl / ⌘ / Alt / Option","what":"Windows の Ctrl は macOS の ⌘（metaKey）。判定を間違えると Mac で全く効かない。画面に出す表記も OS で変える（Mac に「Ctrl+S」と出ていると迷う）。navigator.userAgentData.platform で判定し、無い環境では navigator.platform にフォールバックする。","how":"操作：キーを押す。押された修飾キーと、この OS での正しい表記が出る。","html":"<div class=\"stage\">\n    <div class=\"row\"><span class=\"readout\" id=\"s104-os\"></span><span class=\"readout\" id=\"s104-keys\">キーを押してみる</span></div>\n    <table class=\"cmp\" id=\"s104-t\"></table>\n  </div>","css":"","js":"(() => {\n  const plat = (navigator.userAgentData && navigator.userAgentData.platform) || navigator.platform || '';\n  const isMac = /mac|iphone|ipad/i.test(plat);\n  const label = { mod: isMac ? '⌘' : 'Ctrl', alt: isMac ? 'Option' : 'Alt', del: isMac ? 'Delete' : 'Del' };\n  $('#s104-os').textContent = `この OS: ${plat || '不明'} → 修飾キーは「${label.mod}」`;\n  $('#s104-t').innerHTML = '<tr><th>機能</th><th>この端末での表記</th><th>判定するプロパティ</th></tr>' + [\n    ['保存', label.mod + '+S', 'e.ctrlKey || e.metaKey'],\n    ['複数選択', label.mod + '+クリック', '同上（11 の選択）'],\n    ['範囲選択', 'Shift+クリック', 'e.shiftKey'],\n    ['等比・軸固定', 'Shift+ドラッグ', 'e.shiftKey（51）'],\n    ['複製しながら移動', label.alt + '+ドラッグ', 'e.altKey'],\n  ].map(r => `<tr><td class=\"k\">${r[0]}</td><td><b>${r[1]}</b></td><td><code>${r[2]}</code></td></tr>`).join('');\n  addEventListener('keydown', e => {\n    const on = [e.ctrlKey && 'Ctrl', e.metaKey && 'Meta(⌘)', e.altKey && 'Alt/Option', e.shiftKey && 'Shift'].filter(Boolean);\n    $('#s104-keys').textContent = `押されている: ${on.join(' + ') || 'なし'} / key = ${e.key}`;\n  });\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n105","title":"105画面の高さ vh / svh / lvh / dvh","what":"スマートフォンではスクロールに応じてアドレスバーが伸縮するため、100vh は「バーが隠れたときの高さ」＝画面より大きく、下がはみ出す。svh（最小＝バーが出ている状態）、lvh（最大）、dvh（今の実際の高さ、変化に追従）で正確に指定できる。全画面のパネルやモーダルは dvh か svh。","how":"操作：スマートフォンで開いてスクロールすると差が出る。下の帯は同じ「10%」の高さを4種類の単位で描いたもの。","html":"<div class=\"stage\">\n    <div class=\"s105\"><div class=\"a\">10vh</div><div class=\"b\">10svh</div><div class=\"c\">10lvh</div><div class=\"d\">10dvh</div></div>\n    <div class=\"row\"><span class=\"readout\" id=\"s105-out\"></span></div>\n  </div>","css":".s105 { display: flex; gap: 6px; align-items: flex-end; height: 90px; }\n.s105 > div { flex: 1; display: grid; place-items: end center; font-size: 11px; color: #fff; padding-bottom: 2px; border-radius: 4px 4px 0 0; }\n.s105 .a { height: 10vh;  background: #94a3b8; }\n.s105 .b { height: 10svh; background: #2563eb; }\n.s105 .c { height: 10lvh; background: #7c3aed; }\n.s105 .d { height: 10dvh; background: #16a34a; }","js":"(() => {\n  const px = u => { const d = document.createElement('div'); d.style.cssText = `position:absolute;height:100${u}`; document.body.appendChild(d); const h = d.getBoundingClientRect().height; d.remove(); return Math.round(h); };\n  const show = () => $('#s105-out').textContent = `この端末: 100vh=${px('vh')}px / 100svh=${px('svh')}px / 100lvh=${px('lvh')}px / 100dvh=${px('dvh')}px / innerHeight=${innerHeight}px`;\n  addEventListener('resize', show); show();\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n106","title":"106セーフエリア env(safe-area-inset-*) / viewport-fit=cover","what":"ノッチ、ホームバー、丸い角のある端末では、画面の端に置いた操作部品が隠れる・押せない。&lt;meta name=\"viewport\" content=\"…, viewport-fit=cover\"&gt; を付けたうえで env(safe-area-inset-bottom) などを余白に足す。固定ヘッダー・固定フッター・全画面モーダルの3か所で必ず要る。","how":"操作：該当端末では下の帯に余白が入る。この端末の実測値は下に表示される。","html":"<div class=\"stage\">\n    <div class=\"s106\">画面下に固定する操作バー（セーフエリア分の余白を足している）</div>\n    <div class=\"row\"><span class=\"readout\" id=\"s106-out\"></span></div>\n  </div>","css":".s106 { background: #0f172a; color: #fff; font-size: 13px; text-align: center; border-radius: 8px;\n  padding: 10px 14px;\n  padding-bottom: calc(10px + env(safe-area-inset-bottom, 0px));    /* 第2引数が非対応時の既定値 */\n  padding-left:  calc(14px + env(safe-area-inset-left, 0px));\n  padding-right: calc(14px + env(safe-area-inset-right, 0px)); }","js":"(() => {\n  const v = s => getComputedStyle(document.documentElement).getPropertyValue(s) || '0px';\n  const probe = document.createElement('div');\n  probe.style.cssText = 'position:fixed;top:env(safe-area-inset-top,0px);left:env(safe-area-inset-left,0px);bottom:env(safe-area-inset-bottom,0px);right:env(safe-area-inset-right,0px);visibility:hidden';\n  document.body.appendChild(probe);\n  const r = probe.getBoundingClientRect(); probe.remove();\n  $('#s106-out').textContent = `この端末のセーフエリア: 上 ${Math.round(r.top)}px / 左 ${Math.round(r.left)}px / 下 ${Math.round(innerHeight - r.bottom)}px（0 ならノッチ等なし）`;\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n107","title":"107日本語入力（IME）の途中を無視する compositionstart / isComposing","what":"この資料で最も実害が出やすい項目。日本語を打つと、変換確定前の「かな」の段階でも input と keydown が飛ぶ。対策しないと、①検索が「けん」「けんさ」…と無駄に走る ②Enter による変換確定を「決定」と誤認して、確定した瞬間にフォームが送信される、が起きる。event.isComposing（または compositionstart/end）で変換中は無視するのが正解。","how":"操作：日本語入力に切り替えて「けんさ」と打ち、変換して Enter。左（対策なし）は途中で何度も反応し、Enter を確定として扱ってしまう。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <div style=\"flex:1\"><b style=\"font-size:13px\">対策なし</b><input id=\"s107-bad\" placeholder=\"日本語で入力\" style=\"width:100%\"><div class=\"log\" id=\"s107-bad-log\" style=\"height:96px\"></div></div>\n      <div style=\"flex:1\"><b style=\"font-size:13px\">isComposing で無視</b><input id=\"s107-good\" placeholder=\"日本語で入力\" style=\"width:100%\"><div class=\"log\" id=\"s107-good-log\" style=\"height:96px\"></div></div>\n    </div>\n  </div>","css":"","js":"(() => {\n  const bad = $('#s107-bad'), good = $('#s107-good');\n  bad.addEventListener('input', e => logTo($('#s107-bad-log'), `検索実行: 「${e.target.value}」`));\n  // check-ime-ignore : ここは「対策していない例」を見せるためのコード（意図的に isComposing を見ない）\n  bad.addEventListener('keydown', e => { if (e.key === 'Enter') logTo($('#s107-bad-log'), '★ 決定として処理（変換確定の Enter でも発火）'); });\n\n  // 対策：変換中（isComposing）は何もしない。compositionend で1回だけ処理する。\n  good.addEventListener('input', e => { if (e.isComposing) return; logTo($('#s107-good-log'), `検索実行: 「${e.target.value}」`); });\n  good.addEventListener('compositionend', e => logTo($('#s107-good-log'), `変換確定 → 検索実行: 「${e.target.value}」`));\n  good.addEventListener('keydown', e => {\n    if (e.isComposing || e.keyCode === 229) return;            // 229 は古い環境向けの保険\n    if (e.key === 'Enter') logTo($('#s107-good-log'), '★ 決定として処理（変換確定では発火しない）');\n  });\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n108","title":"108「戻る」で閉じる CloseWatcher / Android のバックキー","what":"Android では戻る操作でモーダルを閉じるのが期待される挙動。従来は履歴に push して popstate で閉じる小細工が要った。CloseWatcher は「Esc・Android の戻る・ブラウザの戻るジェスチャー」をまとめて1つのイベントで受け取れる。&lt;dialog&gt; と popover は最初からこの挙動を持つ（自前のオーバーレイにだけ必要）。","how":"操作：開いて Esc（Android なら戻るキー）で閉じる。","html":"<div class=\"stage\" style=\"min-height:150px\">\n    <div class=\"row\"><button id=\"s108-open\">自前のパネルを開く</button><span class=\"readout\" id=\"s108-out\"></span></div>\n    <div id=\"s108-panel\" class=\"s108-panel\" hidden>自前のオーバーレイ（dialog ではない）<br>Esc / 戻る で閉じる</div>\n  </div>","css":".s108-panel { position: absolute; inset: 40px 20px 20px; background: #fff; border: 1px solid #cbd5e1; border-radius: 10px; padding: 16px; font-size: 13px; box-shadow: 0 12px 30px rgba(0,0,0,.15); }","js":"(() => {\n  const panel = $('#s108-panel'), out = $('#s108-out');\n  out.textContent = 'CloseWatcher: ' + ('CloseWatcher' in window ? '対応' : '非対応 → keydown で代替');\n  let watcher = null;\n  $('#s108-open').onclick = () => {\n    panel.hidden = false;\n    if ('CloseWatcher' in window) {\n      watcher = new CloseWatcher();                            // Esc・Android の戻る・戻るジェスチャーを一括で受ける\n      watcher.onclose = () => { panel.hidden = true; out.textContent = 'CloseWatcher で閉じた'; };\n    } else {\n      const onKey = e => { if (e.key === 'Escape') { panel.hidden = true; out.textContent = 'keydown で閉じた'; removeEventListener('keydown', onKey); } };\n      addEventListener('keydown', onKey);\n    }\n  };\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n109","title":"109スクロールバーの差 scrollbar-gutter / scrollbar-width / overscroll-behavior","what":"Windows のスクロールバーは場所を取る（出た瞬間に中身が 15px ずれる）。macOS と iOS は重なって表示され消える。scrollbar-gutter: stable で最初から場所を空けておくとズレが起きない。overscroll-behavior: contain は「内側を末端まで送ったら親までスクロールが伝わる」現象（モーダル内スクロールの定番の不快さ）を止める。","how":"操作：3つの枠をスクロールする。中央は末端でも親に伝わらない。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"align-items:flex-start\">\n      <div style=\"flex:1\"><b style=\"font-size:12px\">既定</b><div class=\"s109 plain\"></div></div>\n      <div style=\"flex:1\"><b style=\"font-size:12px\">gutter: stable + contain</b><div class=\"s109 stable\"></div></div>\n      <div style=\"flex:1\"><b style=\"font-size:12px\">細いバー</b><div class=\"s109 thin\"></div></div>\n    </div>\n    <div class=\"row\"><span class=\"readout\" id=\"s109-out\"></span></div>\n  </div>","css":".s109 { height: 120px; overflow-y: auto; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 12px; }\n.s109 div { padding: 3px 8px; border-bottom: 1px solid #f1f5f9; }\n.s109.stable { scrollbar-gutter: stable; overscroll-behavior: contain; }   /* 場所を確保 ＋ 親へ伝えない */\n.s109.thin { scrollbar-width: thin; scrollbar-color: #94a3b8 transparent; }","js":"(() => {\n  $$('.s109').forEach(el => el.innerHTML = Array.from({ length: 30 }, (_, i) => `<div>行 ${i + 1}</div>`).join(''));\n  const el = $('.s109.plain');\n  const w = el.offsetWidth - el.clientWidth;\n  $('#s109-out').textContent = `この端末のスクロールバー幅: ${w}px（0 なら重ねて表示するタイプ＝ズレは起きない）`;\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n110","title":"110タッチ端末の癖 touch-action / tap highlight / 自動ズーム","what":"タッチ特有の4つ。①ダブルタップズームで連打が拾われない ②タップ時に灰色の矩形が光る ③iOS は 16px 未満の入力欄で自動的に拡大する（現場で一番嫌われる） ④長押しで選択・コンテキストメニューが出る。いずれも CSS で抑えられるが、抑えすぎると選択やコピーができなくなるので、対象は操作部品に限る。","how":"操作：タッチ端末で2つの領域を触り比べる。","html":"<div class=\"stage\">\n    <div class=\"row\" style=\"align-items:stretch\">\n      <div class=\"s110 plain\">既定<br><small>連打・長押ししてみる</small><br><input type=\"text\" placeholder=\"14px（iOSで拡大）\"></div>\n      <div class=\"s110 tuned\">対策済み<br><small>拡大しない・光らない</small><br><input type=\"text\" placeholder=\"16px（拡大しない）\"></div>\n    </div>\n    <div class=\"row\"><span class=\"readout\" id=\"s110-out\"></span></div>\n  </div>","css":".s110 { flex: 1; background: #fff; border: 1px solid #cbd5e1; border-radius: 8px; padding: 12px; font-size: 13px; text-align: center; }\n.s110 input { width: 90%; margin-top: 8px; padding: 6px; border: 1px solid #cbd5e1; border-radius: 6px; }\n.s110.plain input { font-size: 14px; }                       /* iOS はフォーカス時に自動で拡大する */\n.s110.tuned { touch-action: manipulation;                    /* ダブルタップズームを無効化＝連打が拾える */\n  -webkit-tap-highlight-color: transparent;                  /* タップ時の灰色を消す */\n  -webkit-touch-callout: none; user-select: none; }          /* 長押しメニュー・選択を抑える（操作部品だけに） */\n.s110.tuned input { font-size: 16px; user-select: text; }    /* 入力欄は 16px 以上、選択は許可 */","js":"(() => {\n  let n = 0, t0 = 0;\n  $$('.s110').forEach(el => el.addEventListener('pointerdown', () => {\n    const now = performance.now(); n = now - t0 < 400 ? n + 1 : 1; t0 = now;\n    $('#s110-out').textContent = `連続タップ ${n} 回（ダブルタップズームが効いていると 2 回目以降を取りこぼす）`;\n  }));\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n111","title":"111日本語のテキスト処理 text-wrap / word-break / Intl.Segmenter","what":"日本語は単語の区切りが無いので、意味の切れ目を無視して折り返される。text-wrap: balance（見出しの行長を揃える）、pretty（最終行に1文字だけ残さない）、word-break: auto-phrase（文節で折る）で読みやすくなる。省略は text-overflow: ellipsis、文字数の数え方は絵文字や結合文字があるため Intl.Segmenter が正確（.length は誤る）。","how":"操作：幅を変えて折り返しの違いを見る。下は文字数の数え方の比較。","html":"<div class=\"stage\">\n    <div class=\"row\">幅 <input type=\"range\" id=\"s111-w\" min=\"180\" max=\"520\" value=\"300\"></div>\n    <div id=\"s111-box\" class=\"s111-box\">\n      <p class=\"plain\">六角ボルトの検査成績書を同梱してください</p>\n      <p class=\"pretty\">六角ボルトの検査成績書を同梱してください</p>\n      <p class=\"phrase\">六角ボルトの検査成績書を同梱してください</p>\n      <p class=\"ellip\">株式会社サンプル製作所 第2工場 生産管理課 宛の長い宛名</p>\n    </div>\n    <div class=\"row\"><span class=\"readout\" id=\"s111-out\"></span></div>\n  </div>","css":".s111-box { width: 300px; background: #fff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 8px 12px; }\n.s111-box p { margin: 0 0 8px; font-size: 14px; border-left: 3px solid #e5e7eb; padding-left: 8px; }\n.s111-box .plain::before  { content: '既定 '; font-size: 10px; color: #6b7280; }\n.s111-box .pretty { text-wrap: pretty; }\n.s111-box .pretty::before { content: 'pretty '; font-size: 10px; color: #6b7280; }\n.s111-box .phrase { word-break: auto-phrase; }               /* 文節で折り返す */\n.s111-box .phrase::before { content: 'auto-phrase '; font-size: 10px; color: #6b7280; }\n.s111-box .ellip { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }","js":"(() => {\n  $('#s111-w').oninput = e => $('#s111-box').style.width = e.target.value + 'px';\n  const s = '検査OK👨‍🏭👍';\n  const graphemes = [...new Intl.Segmenter('ja', { granularity: 'grapheme' }).segment(s)].length;\n  $('#s111-out').textContent = `「${s}」 .length=${s.length} / Array.from=${Array.from(s).length} / 人が数える字数（Segmenter）=${graphemes}`;\n})();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n112","title":"112印刷 @page / break-inside / print-color-adjust","what":"現場では画面より紙が正義のことがある。@media print で操作部品を消し、@page で余白と向きを決め、break-inside: avoid で表の行が分断されるのを防ぐ。背景色は既定で印刷されないので、色で状態を示している表は print-color-adjust: exact を指定するか、記号を併記する（10 のチェックリストと同じ理由）。","how":"操作：「印刷プレビュー」で確認（このデモの領域だけが印刷対象になるよう指定してある）。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"s112-print\">印刷プレビューを開く</button><span class=\"readout\">ヘッダー・目次・ボタンは印刷されない</span></div>\n    <table class=\"cmp s112\" style=\"margin-top:8px\"><tr><th>品番</th><th>状態</th><th>数量</th></tr>\n      <tr><td>P-001</td><td class=\"ok\">正常</td><td>120</td></tr>\n      <tr><td>P-002</td><td class=\"ng\">要確認</td><td>80</td></tr>\n    </table>\n  </div>","css":".s112 .ok { background: #dcfce7; } .s112 .ng { background: #fee2e2; }\n.s112 .ok::after { content: ' ✓'; } .s112 .ng::after { content: ' ✖'; }   /* 色に頼らない */\n@media print {\n  @page { size: A4 portrait; margin: 14mm; }\n  body > *:not(.layout), aside.toc, header.top, .row, details { display: none !important; }\n  .s112 { break-inside: avoid; print-color-adjust: exact; -webkit-print-color-adjust: exact; }  /* 背景色も印刷する */\n  .s112 tr { break-inside: avoid; }\n}","js":"(() => { $('#s112-print').onclick = () => window.print(); })();"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n113","title":"113機能検出と段階的強化 @supports / CSS.supports / 'x' in y","what":"17 章の新機能を業務アプリで使う判断は「無くても仕事が終わるか」で決める。@supports で対応環境だけ上書きする書き方にすれば、非対応環境には従来の実装が残る。JS は 'moveBefore' in Element.prototype のように使う直前に確かめる。下の表はこの端末の実測。","how":"","html":"<div class=\"stage\">\n    <div class=\"before-after\" style=\"display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:12.5px\">\n      <div style=\"background:#fff;border:1px solid #fca5a5;border-radius:6px;padding:8px 10px;color:#1d1f23\"><b>× 危ない書き方</b><br>新機能を前提に書き、非対応だと崩れる</div>\n      <div style=\"background:#fff;border:1px solid #86efac;border-radius:6px;padding:8px 10px;color:#1d1f23\"><b>○ 段階的強化</b><br>まず従来の書き方 → <code>@supports</code> で上書き</div>\n    </div>\n    <table class=\"cmp\" id=\"s113-t\"></table>\n  </div>","css":"/* 段階的強化の型：まず全環境で成立する指定を書き、対応環境だけ上書きする */\n.s113-panel { display: none; opacity: 0; transition: opacity .2s; }\n.s113-panel.open { display: block; opacity: 1; }\n@supports (transition-behavior: allow-discrete) {\n  .s113-panel { transition: opacity .2s, display .2s allow-discrete; }\n  @starting-style { .s113-panel.open { opacity: 0; } }\n}","js":"(() => {\n  const F = [\n    [':has()', () => CSS.supports('selector(:has(*))'), '87', 'JS でクラスを付け外し'],\n    ['@starting-style', () => CSS.supports('transition-behavior', 'allow-discrete'), '88', '12 の opacity 方式'],\n    ['popover', () => 'popover' in HTMLElement.prototype, '89', '20 の自前ドロップダウン'],\n    ['アンカー位置指定', () => CSS.supports('position-area', 'top'), '90', '17 の getBoundingClientRect'],\n    ['interpolate-size', () => CSS.supports('interpolate-size', 'allow-keywords'), '91', '18 の grid 0fr→1fr'],\n    ['details name', () => 'name' in document.createElement('details'), '92', 'JS で他を閉じる'],\n    ['field-sizing', () => CSS.supports('field-sizing', 'content'), '93', 'scrollHeight を読んで高さ指定'],\n    ['content-visibility', () => CSS.supports('content-visibility', 'auto'), '94', '23 の仮想スクロール'],\n    ['light-dark()', () => CSS.supports('color', 'light-dark(#000,#fff)'), '95', '変数を2セット書く'],\n    ['moveBefore()', () => 'moveBefore' in Element.prototype, '96', 'insertBefore（状態は失われる）'],\n    ['Custom Highlight', () => !!(window.CSS && CSS.highlights), '97', '74 の <mark> 差し替え'],\n    ['scheduler.yield()', () => !!(window.scheduler && window.scheduler.yield), '98', 'setTimeout(0) で分割'],\n    ['スクロールボタン', () => { try { document.querySelector('div::scroll-button(left)'); return true; } catch { return false; } }, '100', 'JS で scrollBy'],\n    ['sibling-index()', () => CSS.supports('width', 'calc(sibling-index() * 1px)'), '101', '--i を HTML に書く'],\n    ['CloseWatcher', () => 'CloseWatcher' in window, '108', 'keydown + history'],\n    ['dvh 単位', () => CSS.supports('height', '100dvh'), '105', 'JS で innerHeight を代入'],\n    ['word-break: auto-phrase', () => CSS.supports('word-break', 'auto-phrase'), '111', '既定の折り返し'],\n  ];\n  $('#s113-t').innerHTML = '<tr><th>機能</th><th>この端末</th><th>デモ</th><th>非対応時に使う従来の方法</th></tr>' +\n    F.map(([name, test, no, fallback]) => {\n      let ok = false; try { ok = !!test(); } catch {}\n      return `<tr><td class=\"k\">${name}</td><td class=\"${ok ? 'yes' : 'no'}\"><b>${ok ? '使える' : '使えない'}</b></td><td>${no}</td><td>${fallback}</td></tr>`;\n    }).join('');\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n115","title":"115iframe と postMessage 相互通信実動","what":"埋め込んだ画面とやりとりする唯一の手段。要点は3つ。①送信時に targetOrigin を必ず具体的に書く（'*' は誰にでも届く）②受信時に event.origin を必ず検証する（誰でも送れる）③相手の準備完了を待つ握手をする（読み込み前に送ると消える）。高さの自動調整も postMessage で送るのが定番。","how":"操作：下の枠は別文書。ボタンで双方向に送る。ログに origin 検証の結果が出る。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"b115\">親 → 子（受注番号を送る）</button><span class=\"readout\" id=\"o115\">-</span></div>\n    <iframe class=\"embed\" id=\"f115\"></iframe>\n    <div class=\"log\" id=\"l115\" style=\"height:90px;margin-top:8px\"></div>\n  </div>","css":"","js":"(() => {\n  const log = m => logTo($('#l115'), m);\n  // 子側（実際は別オリジンのサービス）。ここでは srcdoc で同じ内容を再現する\n  $('#f115').srcdoc = `<!DOCTYPE html><meta charset=\"utf-8\">\n    <style>body{font:13px system-ui;margin:0;padding:12px;background:#f8fafc}button{font:inherit}</style>\n    <b>埋め込まれた側</b><p id=\"msg\">親からの受信待ち…</p>\n    <button id=\"send\">子 → 親（高さを通知）</button>\n    <script>\n      parent.postMessage({ type: 'ready' }, '*');            // ③ 準備できたと知らせる\n      addEventListener('message', e => {\n        // ② 実際は e.origin を許可リストと突き合わせる\n        if (e.data && e.data.type === 'order') document.getElementById('msg').textContent = '受信: ' + e.data.id;\n      });\n      document.getElementById('send').onclick = () =>\n        parent.postMessage({ type: 'height', value: document.body.scrollHeight }, '*');\n    <\\/script>`;\n  let ready = false;\n  addEventListener('message', e => {\n    if (e.source !== $('#f115').contentWindow) return;        // ② 送信元を確かめる（最低限）\n    const d = e.data || {};\n    if (d.type === 'ready') { ready = true; log('子: 準備完了（握手）'); }\n    if (d.type === 'height') { log(`子 → 親: 高さ ${d.value}px`); $('#f115').style.height = (d.value + 24) + 'px'; $('#o115').textContent = `高さを ${d.value}px に合わせた`; }\n  });\n  $('#b115').onclick = () => {\n    if (!ready) return log('まだ準備できていない（握手前に送ると消える）');\n    // ① 本番では targetOrigin に相手のオリジンを具体的に書く\n    $('#f115').contentWindow.postMessage({ type: 'order', id: '#1001' }, '*');\n    log('親 → 子: 受注 #1001');\n  };\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n116","title":"116埋め込まれる側の作法 sandbox / frame-ancestors実動","what":"自分の画面が他人のページに埋め込まれる場合の防御と、他人の画面を埋め込む場合の制限。埋め込む側は sandbox 属性で権限を絞る（スクリプト・フォーム送信・別窓・トップレベル遷移などを個別に許可）。埋め込まれる側は Content-Security-Policy: frame-ancestors で誰に埋め込ませるかを決める（クリックジャッキング対策）。","how":"操作：sandbox の指定を変えて、中のスクリプトが動くかどうかを見る。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <select id=\"s116\">\n        <option value=\"\">sandbox なし（何でもできる）</option>\n        <option value=\"allow-scripts\" selected>sandbox=\"allow-scripts\"</option>\n        <option value=\"__none__\">sandbox=\"\"（スクリプト禁止）</option>\n      </select>\n      <span class=\"readout\" id=\"o116\"></span>\n    </div>\n    <iframe class=\"embed\" id=\"f116\" style=\"height:110px\"></iframe>\n  </div>","css":"","js":"(() => {\n  const body = `<!DOCTYPE html><meta charset=\"utf-8\"><style>body{font:13px system-ui;margin:0;padding:12px;background:#f8fafc}</style>\n    <b>埋め込まれた側</b><p id=\"p\">スクリプトは動いていない</p>\n    <script>document.getElementById('p').textContent = 'スクリプトが動いた（時刻 ' + new Date().toLocaleTimeString() + '）';<\\/script>`;\n  const apply = () => {\n    const v = $('#s116').value, f = $('#f116');\n    const next = f.cloneNode(false);                          // sandbox は再読み込みしないと効かない\n    if (v === '__none__') next.setAttribute('sandbox', '');\n    else if (v) next.setAttribute('sandbox', v);\n    else next.removeAttribute('sandbox');\n    f.replaceWith(next); next.id = 'f116'; next.srcdoc = body;\n    $('#o116').textContent = v === '__none__' ? 'スクリプトは実行されない' : v ? 'スクリプトのみ許可' : '制限なし';\n  };\n  $('#s116').onchange = apply; apply();\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n117","title":"117埋め込みでログインが切れる 3rd party Cookie / CHIPS / Storage Access API模擬","what":"「PC では見えるのに、iPhone だと iframe の中がログイン画面になる」の原因。ブラウザは埋め込まれた別サイトの Cookie を、トップレベルのサイトごとに分離する。2026年時点の状況：Chrome は 3rd party Cookie の廃止を撤回して継続、Safari・Firefox はブロックを継続。つまり環境によって挙動が違う状態が続く。対処は3つ：CHIPS（Cookie に Partitioned を付け、トップレベルごとに別の入れ物として持つ）、Storage Access API（ユーザー操作を起点に許可を求める）、そしてそもそも iframe をやめる（114 の③④）。","how":"操作：この端末の判定と、3方式の比較を表示する。","html":"<div class=\"stage\"><table class=\"cmp\" id=\"t117\"></table></div>","css":"","js":"(() => {\n  const has = (o, k) => o && k in o;\n  const rows = [\n    ['この文書は iframe の中か', window.top !== window.self ? 'はい' : 'いいえ（トップレベル）', '中にいると 3rd party 扱いになる'],\n    ['Cookie が使えるか', navigator.cookieEnabled ? '有効' : '無効', 'ブロックされていると読み書きできない'],\n    ['CHIPS（Partitioned）', (() => { try { document.cookie = '_p=1; Secure; SameSite=None; Partitioned; Path=/'; return document.cookie.includes('_p=1') ? '書けた' : '書けない（file:// では Secure 属性が通らない場合がある）'; } catch { return '判定不可'; } })(), 'トップレベルごとに分離した入れ物'],\n    ['Storage Access API', has(document, 'requestStorageAccess') ? '対応' : '非対応', 'ユーザー操作を起点に許可を求める'],\n    ['hasStorageAccess()', has(document, 'hasStorageAccess') ? '対応' : '非対応', '許可済みかを確認'],\n    ['FedCM', has(navigator, 'credentials') && 'IdentityCredential' in window ? '対応' : '非対応', 'ログイン連携の新しい枠組み'],\n  ];\n  $('#t117').innerHTML = '<tr><th>項目</th><th>この端末</th><th>意味</th></tr>' +\n    rows.map(r => `<tr><td class=\"k\">${r[0]}</td><td><b>${r[1]}</b></td><td>${r[2]}</td></tr>`).join('') +\n    `<tr><td class=\"k\">Chrome</td><td class=\"cau\">3rd party Cookie は継続</td><td>2025年に廃止方針を撤回</td></tr>\n     <tr><td class=\"k\">Safari / Firefox</td><td class=\"no\">ブロック継続</td><td><b>ここで切れる</b>。CHIPS か SAA、または iframe をやめる</td></tr>`;\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n118","title":"118CORS とプリフライト なぜ「サーバ経由」が要るのか模擬","what":"ブラウザは別オリジンへの読み取りを既定で禁じる。許可を出すのは相手のサーバであって、こちら側では変えられない。Content-Type: application/json や独自ヘッダを付けると事前確認（プリフライト）の OPTIONS が先に飛び、相手がそれに答えないと本体は送られない。認証情報を送るなら credentials と Access-Control-Allow-Credentials の両方が必要で、ワイルドカードは使えない。相手が対応していなければ 114 の③（サーバ経由）しか手がない。","how":"操作：要求の条件を変えて、通るか・プリフライトが要るかを判定する（相手のサーバ設定は下で切り替える）。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <label><input type=\"checkbox\" id=\"j118\" checked> JSON で送る</label>\n      <label><input type=\"checkbox\" id=\"h118\"> 独自ヘッダを付ける</label>\n      <label><input type=\"checkbox\" id=\"c118\"> Cookie を送る</label>\n      <span style=\"margin-left:10px\">相手の設定:</span>\n      <select id=\"s118\">\n        <option value=\"none\">許可なし</option>\n        <option value=\"star\" selected>Allow-Origin: *</option>\n        <option value=\"origin\">Allow-Origin: 自分 + Credentials</option>\n      </select>\n    </div>\n    <div class=\"log\" id=\"l118\" style=\"height:130px\"></div>\n  </div>","css":"","js":"(() => {\n  const log = m => logTo($('#l118'), m);\n  const judge = () => {\n    $('#l118').textContent = '';\n    const json = $('#j118').checked, custom = $('#h118').checked, cred = $('#c118').checked, server = $('#s118').value;\n    const preflight = json || custom;                       // 単純要求の条件を外れるとプリフライトになる\n    log(`要求: ${json ? 'Content-Type: application/json ' : ''}${custom ? 'X-App-Id ' : ''}${cred ? '+ Cookie' : ''}`);\n    log(preflight ? '→ 先に OPTIONS（プリフライト）が飛ぶ' : '→ 単純要求（プリフライトなし）');\n    if (server === 'none') return log('✖ 相手が Access-Control-Allow-Origin を返さない → ブラウザが結果を渡さない（サーバ経由にするしかない）');\n    if (cred && server === 'star') return log('✖ Cookie を送るときは Allow-Origin: * が使えない → 具体的なオリジンと Allow-Credentials: true が必要');\n    if (preflight && server === 'star' && custom) log('△ プリフライトの応答に Allow-Headers: X-App-Id が必要');\n    if (preflight) log('→ OPTIONS に Allow-Methods / Allow-Headers が返れば本体を送る');\n    log('✔ 通る（応答が JS から読める）');\n  };\n  ['#j118', '#h118', '#c118', '#s118'].forEach(s => $(s).addEventListener('change', judge));\n  judge();\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n119","title":"119OAuth 2.1 と PKCE 認可コード + PKCE（S256）実動","what":"2026年の標準形。OAuth 2.1 では PKCE が必須で、implicit フロー（トークンを URL で受け取る）は廃止。仕組み：①ランダムな code_verifier を作り ②その SHA-256（code_challenge）だけを認可画面へ渡す ③戻ってきた認可コードと verifier を一緒に送る。途中でコードを盗まれても、verifier を知らなければトークンに交換できない。アクセストークンはメモリに置く（localStorage は XSS で読まれる）。リフレッシュトークンは自前サーバからの HttpOnly Cookie にする。","how":"操作：実際に WebCrypto で verifier / challenge を生成し、模擬の認可サーバとやりとりする。攻撃者がコードだけ盗んだ場合も試せる。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"b119\" class=\"primary\">認可フローを実行</button><button id=\"b119x\">盗まれたコードで交換を試す</button></div>\n    <div class=\"log\" id=\"l119\" style=\"height:160px\"></div>\n  </div>","css":"","js":"(() => {\n  const log = m => logTo($('#l119'), m);\n  const b64url = buf => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/, '');\n  const server = { issued: null };                            // 模擬の認可サーバ\n  let stolenCode = null;\n  $('#b119').onclick = async () => {\n    $('#l119').textContent = '';\n    const verifier = b64url(crypto.getRandomValues(new Uint8Array(32)));\n    const challenge = b64url(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier)));\n    log('① code_verifier（手元にだけ置く）: ' + verifier.slice(0, 24) + '…');\n    log('② code_challenge = SHA-256(verifier): ' + challenge.slice(0, 24) + '…');\n    log('③ 認可画面へ: /authorize?code_challenge=' + challenge.slice(0, 12) + '…&code_challenge_method=S256&state=…');\n    const code = b64url(crypto.getRandomValues(new Uint8Array(12)));\n    server.issued = { code, challenge };\n    stolenCode = code;\n    log('④ 戻り: /callback?code=' + code.slice(0, 12) + '…（この時点ではまだトークンではない）');\n    const ok = await exchange(code, verifier);\n    log(ok ? '⑤ トークン取得成功 → メモリ上の変数に置く（localStorage には置かない）' : '⑤ 失敗');\n  };\n  const exchange = async (code, verifier) => {                 // サーバ側の検証\n    if (!server.issued || server.issued.code !== code) { log('  サーバ: 未知のコード'); return false; }\n    const c = b64url(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier || '')));\n    if (c !== server.issued.challenge) { log('  サーバ: verifier が challenge と一致しない → 拒否'); return false; }\n    log('  サーバ: verifier を検証 → 一致'); return true;\n  };\n  $('#b119x').onclick = async () => {\n    if (!stolenCode) return log('先に認可フローを実行する');\n    log('攻撃者: 盗んだ code で交換を試みる（verifier は知らない）');\n    const ok = await exchange(stolenCode, b64url(crypto.getRandomValues(new Uint8Array(32))));\n    log(ok ? '✖ 交換できてしまった' : '✔ 交換できない（PKCE が効いている）');\n  };\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n121","title":"121鍵を画面に置かない クライアントに秘密は無い実動","what":"ブラウザや renderer に置いた値は、すべて利用者に読める。難読化しても変わらない。「API キーを JS に埋める」「kintone のカスタマイズに管理者トークンを書く」は、その画面を開ける全員にキーを配るのと同じ。鍵が要る呼び出しは 114 の③④（サーバ／main 経由）に寄せる。","how":"操作：下のボタンで、このページの JS に「隠した」つもりの値を取り出す。実際には数行で読める。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"b121\">画面の中の「秘密」を取り出す</button><span class=\"readout\" id=\"o121\">-</span></div>\n    <table class=\"cmp\" style=\"margin-top:8px\">\n      <tr><th>置き場所</th><th>安全か</th><th>代わりにどうするか</th></tr>\n      <tr><td class=\"k\">JS の変数・定数</td><td class=\"no\">読める</td><td>サーバ／main 経由にする</td></tr>\n      <tr><td class=\"k\">ビルド時の環境変数</td><td class=\"no\">埋め込まれるので読める</td><td>同上（サーバ側の環境変数は安全）</td></tr>\n      <tr><td class=\"k\">localStorage</td><td class=\"no\">読める・XSS でも盗まれる</td><td>アクセストークンはメモリ、更新用は HttpOnly Cookie</td></tr>\n      <tr><td class=\"k\">Electron の renderer</td><td class=\"no\">読める</td><td>main に置き、IPC で「結果」だけ返す</td></tr>\n      <tr><td class=\"k\">Electron の main + safeStorage</td><td class=\"yes\">実用上は安全</td><td>これが基本形（120）</td></tr>\n    </table>\n  </div>","css":"","js":"(() => {\n  const CONFIG = { apiKey: 'sk-live-EXAMPLE-1234567890', endpoint: '/api' };   // ← これがそのまま読める\n  $('#b121').onclick = () => {\n    // 開発者ツールのコンソールからも、拡張機能からも、同じことができる\n    $('#o121').textContent = `見えている: ${CONFIG.apiKey}（難読化しても実行時には復元される）`;\n  };\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n122","title":"122レート制限と再試行 429・バックオフ・冪等キー実動","what":"外部 API は必ず絞られる（kintone も 1 アプリあたりの同時実行数・秒間リクエスト数に上限がある。具体的な数値は相手の仕様書で確認すること＝ここでは断定しない）。上限に当たると 429 Too Many Requests が返り、多くは Retry-After ヘッダで「何秒待て」と教えてくる。やることは3つ。①すぐ再試行しない（待ち時間を倍々にする＝指数バックオフ）②ジッター（ゆらぎ）を足す（全端末が同時に再開すると再び詰まる＝雪崩）③冪等キーを付ける（送信は成功したが応答が届かなかったとき、二重登録を防ぐ）。","how":"操作：同じ模擬 API（先頭2件しか通らない）に 6 件送る。3つの方式で結果と所要時間を比べる。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <button id=\"b122a\">① 再試行しない</button>\n      <button id=\"b122b\">② すぐ再試行（間隔一定）</button>\n      <button id=\"b122c\">③ 指数バックオフ＋ジッター</button>\n      <span class=\"readout\" id=\"o122\">-</span>\n    </div>\n    <div class=\"log\" id=\"l122\" style=\"height:150px;margin-top:8px\"></div>\n  </div>","css":"#n122 .log { font-variant-numeric: tabular-nums; }","js":"(() => {\n  const log = m => logTo($('#l122'), m);\n  const sleep = ms => new Promise(r => setTimeout(r, ms));\n\n  // ---- 模擬 API：2秒の窓で 2 件までしか受け付けず、超えたら 429 + Retry-After ----\n  let win = { start: 0, n: 0 };\n  const store = new Map();                       // 冪等キー → 保存済みの応答\n  async function fakeApi(body, idemKey) {\n    await sleep(30);                             // 通信の往復ぶん\n    if (store.has(idemKey)) return { status: 200, replay: true };   // ③ 同じキーなら再登録しない\n    const now = performance.now();\n    if (now - win.start > 2000) win = { start: now, n: 0 };\n    if (win.n >= 2) return { status: 429, retryAfter: Math.ceil((2000 - (now - win.start)) / 1000) };\n    win.n++; store.set(idemKey, true);\n    return { status: 200 };\n  }\n\n  // ---- 再試行つきの呼び出し ----\n  async function call(body, mode) {\n    const idemKey = `order-${body.id}`;          // ① 業務上のキーから作る（毎回ランダムにしない）\n    const max = 5;\n    for (let attempt = 0; attempt <= max; attempt++) {\n      const res = await fakeApi(body, idemKey);\n      if (res.status !== 429) return { ok: true, attempt, replay: res.replay };\n      if (mode === 'none' || attempt === max) return { ok: false, attempt };\n      let wait;\n      if (mode === 'flat') wait = 200;                                   // ② 一定間隔＝みんな同時に再開する\n      else {\n        const base = res.retryAfter != null ? res.retryAfter * 1000      // ③ サーバの指示が最優先\n                                            : Math.min(2 ** attempt * 200, 8000);\n        wait = base * (0.5 + Math.random() * 0.5);                       //    ジッター（半分〜満額でばらす）\n      }\n      log(`  #${body.id} 429 → ${Math.round(wait)}ms 待って再試行（${attempt + 1}回目）`);\n      await sleep(wait);\n    }\n  }\n\n  async function run(mode, label) {\n    win = { start: 0, n: 0 }; store.clear();\n    $('#l122').textContent = ''; log(`${label}：6件を同時に送る`);\n    const t0 = performance.now();\n    const rs = await Promise.all([1,2,3,4,5,6].map(id => call({ id }, mode)));\n    const ok = rs.filter(r => r.ok).length;\n    const ms = Math.round(performance.now() - t0);\n    log(`成功 ${ok}/6 ・ 所要 ${ms}ms`);\n    $('#o122').textContent = `${label}: 成功 ${ok}/6 / ${ms}ms`;\n  }\n  $('#b122a').onclick = () => run('none', '① 再試行しない');\n  $('#b122b').onclick = () => run('flat', '② 間隔一定');\n  $('#b122c').onclick = () => run('backoff', '③ バックオフ＋ジッター');\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n123","title":"123Webhook の受け側 署名検証・リプレイ・冪等実動","what":"相手のサービスから「起きたこと」を押し込んでもらう仕組み。受け口は誰でも叩ける URL なので、次の3つが必須。①署名検証（本文と共有鍵の HMAC が一致するか。ここは WebCrypto で実際に計算する）②時刻の確認（古い正しい署名の使い回し＝リプレイを弾く）③冪等処理（相手は「届いたか不明」なら再送する。同じイベント ID を二度処理しない）。さらに順序は保証されない前提で、イベント内の版番号や更新時刻で新旧を判断する。","how":"操作：正しい配送・改ざん・古い時刻・再送を送り分け、受け口の判定を見る。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <button id=\"b123a\">正しい配送</button>\n      <button id=\"b123b\">本文を改ざん</button>\n      <button id=\"b123c\">6分前の署名（リプレイ）</button>\n      <button id=\"b123d\">同じイベントを再送</button>\n      <span class=\"readout\" id=\"o123\">-</span>\n    </div>\n    <div class=\"log\" id=\"l123\" style=\"height:130px;margin-top:8px\"></div>\n  </div>","css":"","js":"(() => {\n  const log = m => logTo($('#l123'), m);\n  const SECRET = 'whsec_EXAMPLE_SHARED_SECRET';     // 実際は環境変数。画面には絶対に置かない（121）\n  const enc = new TextEncoder();\n  const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');\n\n  async function sign(ts, body) {                    // 署名対象は「時刻 + 本文」（時刻だけを差し替えられないように）\n    const key = await crypto.subtle.importKey('raw', enc.encode(SECRET),\n      { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);\n    return hex(await crypto.subtle.sign('HMAC', key, enc.encode(`${ts}.${body}`)));\n  }\n\n  const seen = new Map();                            // 実際は DB。イベントID → 処理済み\n  let version = 0;\n\n  async function receive(headers, rawBody) {         // ← サーバ側の処理（Node でもほぼ同じ）\n    const ts = Number(headers['x-timestamp']);\n    // ② 時刻ズレが大きいものは弾く（5分が目安。相手の仕様に合わせる）\n    if (!Number.isFinite(ts) || Math.abs(Date.now() - ts) > 5 * 60 * 1000)\n      return { code: 400, msg: '✖ 時刻が古い／不正 → リプレイとして拒否' };\n    // ① 署名検証。必ず「受け取った生の本文」で計算する（JSON.parse して再文字列化しない）\n    const expect = await sign(ts, rawBody);\n    const got = headers['x-signature'] || '';\n    // 定数時間で比較する（== は先頭が違った時点で返るため、応答時間から1桁ずつ当てられる）\n    // Node なら crypto.timingSafeEqual。ブラウザには専用APIが無いので XOR で全桁見る\n    let diff = got.length ^ expect.length;\n    for (let i = 0; i < Math.max(got.length, expect.length); i++)\n      diff |= (got.charCodeAt(i) | 0) ^ (expect.charCodeAt(i) | 0);\n    if (diff !== 0) return { code: 401, msg: '✖ 署名が一致しない → 改ざん or 別送信者として拒否' };\n    const ev = JSON.parse(rawBody);\n    // ③ 冪等：同じイベントIDは二度処理しない。返すのは 200（そうしないと相手が再送し続ける）\n    if (seen.has(ev.id)) return { code: 200, msg: `✔ 受理（処理済みなので何もしない）: ${ev.id}` };\n    // 順序保証が無い前提：古い版が後から来たら捨てる\n    if (ev.version <= version) return { code: 200, msg: `✔ 受理（古い版なので無視）v${ev.version} ≦ v${version}` };\n    seen.set(ev.id, true); version = ev.version;\n    return { code: 200, msg: `✔ 受理して反映: ${ev.id} / v${ev.version}` };\n  }\n\n  // ---- 送信側（相手のサービス）を模擬 ----\n  let n = 0, lastId = null, lastBody = null;\n  async function deliver(kind) {\n    let id, body, ts = Date.now();\n    if (kind === 'dup' && lastId) { id = lastId; body = lastBody; }\n    else { id = `evt_${++n}`; body = JSON.stringify({ id, type: 'record.updated', version: n, recordId: 1001 }); }\n    if (kind === 'old') ts = Date.now() - 6 * 60 * 1000;\n    const sig = await sign(ts, body);\n    if (kind === 'tamper') body = body.replace('1001', '9999');     // 署名を作った後に本文だけ書き換える\n    lastId = id; lastBody = body;\n    const res = await receive({ 'x-timestamp': String(ts), 'x-signature': sig }, body);\n    log(`${res.code} ${res.msg}`);\n    $('#o123').textContent = `${res.code} ${res.msg}`;\n  }\n  $('#b123a').onclick = () => deliver('ok');\n  $('#b123b').onclick = () => deliver('tamper');\n  $('#b123c').onclick = () => deliver('old');\n  $('#b123d').onclick = () => deliver('dup');\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n124","title":"124反映方式の選び方 ポーリング／SSE／WebSocket実動","what":"「他の人の更新をどう画面に出すか」の3択。ポーリング＝一定間隔で問い合わせる。最も簡単で、どんな相手にも使える（kintone のように Webhook しか無い相手でも成立）。SSE（EventSource）＝サーバから一方向に流し続ける。実装が軽く自動再接続つき。WebSocket＝双方向。カーソル共有や共同編集はこれが要る。迷ったらポーリングから始め、遅延と無駄が問題になってから上げる。","how":"操作：同じ「サーバの値」を3方式で追う。無駄な通信回数と、変化を検知するまでの遅れを比べる。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <button id=\"b124go\">サーバ側で 3 秒後に値を変える</button>\n      <button id=\"b124r\">リセット</button>\n    </div>\n    <table class=\"cmp\" style=\"margin-top:8px\">\n      <tr><th>方式</th><th>受け取った値</th><th>通信回数</th><th>検知までの遅れ</th></tr>\n      <tr><td class=\"k\">ポーリング（2秒毎）</td><td id=\"v124p\">-</td><td id=\"c124p\">0</td><td id=\"d124p\">-</td></tr>\n      <tr><td class=\"k\">SSE（一方向）</td><td id=\"v124s\">-</td><td id=\"c124s\">1</td><td id=\"d124s\">-</td></tr>\n      <tr><td class=\"k\">WebSocket（双方向）</td><td id=\"v124w\">-</td><td id=\"c124w\">1</td><td id=\"d124w\">-</td></tr>\n    </table>\n  </div>","css":"","js":"(() => {\n  // ---- サーバの状態を模擬（本物は 1 台のサーバ上の値）----\n  const server = { value: '在庫 120', changedAt: 0, subs: new Set() };\n  function serverUpdate(v) {                       // 変更が起きた瞬間に push 系へ配る\n    server.value = v; server.changedAt = performance.now();\n    server.subs.forEach(fn => setTimeout(() => fn(v), 20));   // 20ms＝ネットワーク往復\n  }\n  const ms = t => t ? `${Math.round(performance.now() - t)}ms` : '-';\n\n  // ---- ① ポーリング：一定間隔で取りに行く（変化が無くても通信する）----\n  let polls = 0, timer = null, lastSeen = null;\n  function startPolling() {\n    timer = setInterval(() => {                    // 実際は fetch('/api/stock')\n      polls++; $('#c124p').textContent = polls;\n      if (server.value !== lastSeen) {\n        lastSeen = server.value;\n        $('#v124p').textContent = server.value;\n        if (server.changedAt) $('#d124p').textContent = ms(server.changedAt);\n      }\n    }, 2000);\n  }\n  // ---- ② SSE：接続 1 本。サーバ → 画面の一方向 ----\n  //   const es = new EventSource('/events');\n  //   es.onmessage = e => apply(JSON.parse(e.data));      // 切断時は自動で再接続してくれる\n  const sse = v => { $('#v124s').textContent = v; $('#d124s').textContent = ms(server.changedAt); };\n  // ---- ③ WebSocket：接続 1 本。双方向（画面 → サーバ も送れる）----\n  //   const ws = new WebSocket('wss://example.invalid/ws');\n  //   ws.onmessage = e => apply(JSON.parse(e.data));      // 再接続は自前で書く必要がある\n  const wsock = v => { $('#v124w').textContent = v; $('#d124w').textContent = ms(server.changedAt); };\n\n  function reset() {\n    clearInterval(timer); server.subs.clear();\n    polls = 0; lastSeen = server.value = '在庫 120'; server.changedAt = 0;\n    for (const k of ['p','s','w']) { $('#v124' + k).textContent = server.value; $('#d124' + k).textContent = '-'; }\n    $('#c124p').textContent = '0'; $('#c124s').textContent = '1'; $('#c124w').textContent = '1';\n    server.subs.add(sse); server.subs.add(wsock); startPolling();\n  }\n  $('#b124r').onclick = reset;\n  $('#b124go').onclick = () => setTimeout(() => serverUpdate('在庫 96'), 3000);\n  reset();\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n125","title":"125ファイルの授受 保存・読込・貼り付け・共有実動","what":"現場の連携は「ファイルを渡す・受け取る」で足りることが多い。ダウンロード／&lt;input type=file&gt; はどこでも動く最終手段。File System Access API（showSaveFilePicker / showOpenFilePicker）は同じファイルに上書き保存できる＝「編集して保存」が成立する（Chromium 系のみ）。クリップボードは写真や図の受け取りに効く。Web Share は主にモバイルで、他アプリへ渡す。","how":"操作：この環境の対応状況を実測。保存 → 読込 → 貼り付けを試す。file:// では一部が使えないことがある。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <button id=\"b125s\">保存（ハンドル保持）</button>\n      <button id=\"b125w\" disabled>同じファイルに上書き</button>\n      <button id=\"b125o\">開く</button>\n      <button id=\"b125d\">ダウンロード（どこでも動く）</button>\n    </div>\n    <div class=\"row\" style=\"margin-top:6px\">\n      <textarea id=\"t125\" rows=\"3\" style=\"flex:1;min-width:220px;font:13px ui-monospace,Menlo,Consolas,monospace\">部品番号,数量\nA-1001,12</textarea>\n    </div>\n    <div class=\"row\" style=\"margin-top:6px\">\n      <div id=\"p125\" tabindex=\"0\" style=\"flex:1;min-width:200px;border:2px dashed var(--line);border-radius:8px;padding:14px;text-align:center;color:var(--muted);font-size:13px\">ここをクリックして Ctrl/⌘+V で貼り付け（画像・テキスト）／ファイルをドロップ</div>\n    </div>\n    <span class=\"readout\" id=\"o125\">-</span>\n    <table class=\"cmp\" style=\"margin-top:8px\">\n      <tr><th>機能</th><th>この環境</th><th>できること</th></tr>\n      <tr><td class=\"k\">File System Access</td><td id=\"s125a\">-</td><td>同じファイルに上書き保存・フォルダ単位の読み書き</td></tr>\n      <tr><td class=\"k\">ドラッグ&amp;ドロップ</td><td id=\"s125b\">-</td><td>受け取りはどこでも可能（59）</td></tr>\n      <tr><td class=\"k\">クリップボード読取</td><td id=\"s125c\">-</td><td>貼り付けで画像・テキストを受け取る</td></tr>\n      <tr><td class=\"k\">Web Share（ファイル）</td><td id=\"s125d\">-</td><td>他アプリへ渡す（主にモバイル）</td></tr>\n    </table>\n  </div>","css":"","js":"(() => {\n  const set = (id, ok, note) => { const el = $(id); el.textContent = (ok ? '✔ 使える' : '✖ 使えない') + (note ? `（${note}）` : ''); el.className = ok ? 'yes' : 'no'; };\n  const hasFSA = typeof window.showSaveFilePicker === 'function';\n  set('#s125a', hasFSA, hasFSA ? '' : 'Chromium 系のみ。Electron なら Node の fs で代替');\n  set('#s125b', true);\n  set('#s125c', !!(navigator.clipboard && navigator.clipboard.read), '許可を求められる');\n  set('#s125d', !!(navigator.canShare && navigator.canShare({ files: [new File([''], 'a.txt')] })), 'モバイル中心');\n\n  let handle = null;                                     // 保存先を覚えておく＝上書きできる\n  $('#b125s').onclick = async () => {\n    if (!hasFSA) return ($('#o125').textContent = 'この環境では使えない → ダウンロードを使う');\n    try {\n      handle = await showSaveFilePicker({ suggestedName: 'parts.csv',\n        types: [{ description: 'CSV', accept: { 'text/csv': ['.csv'] } }] });\n      const w = await handle.createWritable(); await w.write($('#t125').value); await w.close();\n      $('#b125w').disabled = false;\n      $('#o125').textContent = `保存した: ${handle.name}（以後は同じファイルに上書きできる）`;\n    } catch (e) { $('#o125').textContent = e.name === 'AbortError' ? 'キャンセルした' : `失敗: ${e.message}`; }\n  };\n  $('#b125w').onclick = async () => {                    // ダイアログを出さずに上書き\n    const w = await handle.createWritable(); await w.write($('#t125').value); await w.close();\n    $('#o125').textContent = `上書きした: ${handle.name}（ダイアログ無し）`;\n  };\n  $('#b125o').onclick = async () => {\n    if (hasFSA) {\n      try {\n        [handle] = await showOpenFilePicker(); const f = await handle.getFile();\n        $('#t125').value = await f.text(); $('#b125w').disabled = false;\n        $('#o125').textContent = `読み込んだ: ${f.name} / ${f.size} バイト`;\n      } catch (e) { $('#o125').textContent = e.name === 'AbortError' ? 'キャンセルした' : `失敗: ${e.message}`; }\n    } else {                                             // どこでも動く方法\n      const i = Object.assign(document.createElement('input'), { type: 'file' });\n      i.onchange = async () => { const f = i.files[0]; if (!f) return;\n        $('#t125').value = await f.text(); $('#o125').textContent = `読み込んだ: ${f.name}`; };\n      i.click();\n    }\n  };\n  $('#b125d').onclick = () => {                          // 最終手段。どのブラウザでも動く\n    const url = URL.createObjectURL(new Blob([$('#t125').value], { type: 'text/csv' }));\n    Object.assign(document.createElement('a'), { href: url, download: 'parts.csv' }).click();\n    setTimeout(() => URL.revokeObjectURL(url), 1000);    // 忘れるとメモリを掴んだままになる\n    $('#o125').textContent = 'ダウンロードした（保存先は覚えられない）';\n  };\n\n  const pad = $('#p125');\n  pad.addEventListener('paste', e => {                   // 貼り付けで受け取る\n    for (const item of e.clipboardData.items) {\n      if (item.type.startsWith('image/')) {\n        const f = item.getAsFile();\n        pad.innerHTML = ''; const img = new Image(); img.style.maxHeight = '90px';\n        img.src = URL.createObjectURL(f); pad.append(img);\n        return ($('#o125').textContent = `画像を受け取った: ${f.type} / ${f.size} バイト`);\n      }\n    }\n    $('#o125').textContent = `テキストを受け取った: ${e.clipboardData.getData('text').slice(0, 40)}`;\n  });\n  pad.addEventListener('dragover', e => { e.preventDefault(); pad.style.borderColor = '#2563eb'; });\n  pad.addEventListener('dragleave', () => pad.style.borderColor = '');\n  pad.addEventListener('drop', async e => {\n    e.preventDefault(); pad.style.borderColor = '';\n    const f = e.dataTransfer.files[0]; if (!f) return;\n    $('#o125').textContent = `ドロップ: ${f.name} / ${f.size} バイト`;\n    if (/text|csv|json/.test(f.type) || /\\.(csv|txt|json)$/i.test(f.name)) $('#t125').value = await f.text();\n  });\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n126","title":"126現場機器との連携 WebHID・WebSerial・WebUSB実動","what":"バーコードリーダー・電子秤・ノギス・ラベルプリンタをブラウザから直接扱う API 群。すべて Chromium 系のみ（Safari・Firefox は方針として非対応。2026 年時点の利用可能な利用者はおよそ 4 分の 1 前後にとどまる＝正確な比率は caniuse 等で都度確認）。したがって現場配布では Electron が本命：Chromium を同梱するので API がそのまま使え、さらに Node の serialport 等も使える。バーコードリーダーの多くはキーボードとして振る舞うので、まず「フォーカスした入力欄に高速入力される」前提で作れば API は不要（下で実測できる）。","how":"操作：対応状況を実測。接続ボタンは実機がある環境でのみ完走する（無い場合はデバイス選択が空になる）。下の欄はリーダーを繋がなくても「速い連続入力」で判定を確かめられる。","html":"<div class=\"stage\">\n    <div class=\"row\">\n      <button id=\"b126h\">HID を接続</button>\n      <button id=\"b126s\">シリアルを接続</button>\n      <button id=\"b126u\">USB を接続</button>\n      <span class=\"readout\" id=\"o126\">-</span>\n    </div>\n    <div class=\"row\" style=\"margin-top:6px\">\n      <input id=\"i126\" placeholder=\"ここにバーコードを読ませる（または高速でタイプ）\" style=\"flex:1;min-width:240px\">\n      <span class=\"readout\" id=\"r126\">-</span>\n    </div>\n    <table class=\"cmp\" style=\"margin-top:8px\">\n      <tr><th>API</th><th>この環境</th><th>用途</th><th>備考</th></tr>\n      <tr><td class=\"k\">WebHID</td><td id=\"s126h\">-</td><td>バーコード・カードリーダー・フットスイッチ</td><td>生のレポートを読む</td></tr>\n      <tr><td class=\"k\">WebSerial</td><td id=\"s126s\">-</td><td>秤・ノギス・PLC・計測器</td><td>RS-232C / USB シリアル</td></tr>\n      <tr><td class=\"k\">WebUSB</td><td id=\"s126u\">-</td><td>ラベルプリンタ等</td><td>OS がドライバを掴んでいると開けない</td></tr>\n      <tr><td class=\"k\">キーボード入力として</td><td class=\"yes\">✔ どこでも</td><td>バーコードの大半</td><td><b>まずこれを検討する</b></td></tr>\n    </table>\n  </div>","css":"","js":"(() => {\n  const mark = (id, ok) => { const el = $(id); el.textContent = ok ? '✔ 使える' : '✖ 使えない'; el.className = ok ? 'yes' : 'no'; };\n  mark('#s126h', !!navigator.hid); mark('#s126s', !!navigator.serial); mark('#s126u', !!navigator.usb);\n  const say = m => $('#o126').textContent = m;\n\n  $('#b126h').onclick = async () => {                       // WebHID：レポートを直接読む\n    if (!navigator.hid) return say('この環境では WebHID が無い → Electron か、キーボード入力方式にする');\n    try {\n      const [dev] = await navigator.hid.requestDevice({ filters: [] });   // filters で vendorId 等を絞る\n      if (!dev) return say('デバイスが選ばれなかった（実機が無い環境では空になる）');\n      await dev.open();\n      dev.addEventListener('inputreport', e => {\n        const bytes = [...new Uint8Array(e.data.buffer)].map(b => b.toString(16).padStart(2, '0')).join(' ');\n        say(`HID 受信 reportId=${e.reportId} : ${bytes}`);\n      });\n      say(`接続: ${dev.productName}（読み取り待ち）`);\n    } catch (e) { say(`失敗: ${e.message}`); }\n  };\n  $('#b126s').onclick = async () => {                       // WebSerial：秤・計測器の定番\n    if (!navigator.serial) return say('この環境では WebSerial が無い');\n    try {\n      const port = await navigator.serial.requestPort();\n      await port.open({ baudRate: 9600 });                  // 通信条件は機器の仕様書どおりに（推測しない）\n      const reader = port.readable.pipeThrough(new TextDecoderStream()).getReader();\n      say('接続した（受信待ち）');\n      let buf = '';\n      for (;;) {\n        const { value, done } = await reader.read(); if (done) break;\n        buf += value;\n        let i;                                              // 機器は行単位で送ってくることが多い\n        while ((i = buf.indexOf('\\n')) >= 0) { say(`受信: ${buf.slice(0, i).trim()}`); buf = buf.slice(i + 1); }\n      }\n    } catch (e) { say(`失敗: ${e.message}`); }\n  };\n  $('#b126u').onclick = async () => {                       // WebUSB：プリンタ等\n    if (!navigator.usb) return say('この環境では WebUSB が無い');\n    try {\n      const dev = await navigator.usb.requestDevice({ filters: [] });\n      await dev.open(); await dev.selectConfiguration(1); await dev.claimInterface(0);\n      say(`接続: ${dev.productName || 'USB device'}（transferOut で印字コマンドを送る）`);\n    } catch (e) { say(`失敗: ${e.message}`); }\n  };\n\n  // ---- キーボード型リーダーの判定：人の手より速く、最後に Enter が来る ----\n  const inp = $('#i126'); let t0 = 0, keys = 0;\n  inp.addEventListener('keydown', e => {\n    if (e.isComposing || e.keyCode === 229) return;         // 日本語入力の変換中は数えない\n    if (e.key === 'Enter') {\n      const ms = performance.now() - t0, per = keys ? ms / keys : 0;\n      const scanner = keys >= 4 && per < 30;                // 1文字あたり 30ms 未満＝機械入力とみなす\n      $('#r126').textContent = `${inp.value} → ${scanner ? 'リーダー' : '手入力'}（${keys}文字 / 1文字 ${per.toFixed(1)}ms）`;\n      inp.value = ''; keys = 0; t0 = 0; e.preventDefault();\n      return;\n    }\n    if (!t0) { t0 = performance.now(); keys = 0; }\n    keys++;\n  });\n})();"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n127","title":"127埋め込みウィジェットを作る側 Shadow DOM で壊れない部品実動","what":"自分が作った部品を他人のページに貼ってもらうとき、相手の CSS がこちらを壊し、こちらの CSS が相手を壊す。attachShadow で影の木を作れば、スタイルが両方向に漏れない。ページ側の * { box-sizing } も button { } も届かない。kintone のカスタマイズやポータルへの部品配布はこの形が正解。","how":"操作：「乱暴な CSS」を有効にすると、通常の部品は崩れ、Shadow DOM の部品は無傷なことが分かる。","html":"<div class=\"stage\">\n    <div class=\"row\"><button id=\"b127\">相手ページの乱暴な CSS を有効にする</button><span class=\"readout\" id=\"o127\">-</span></div>\n    <div id=\"host127\" style=\"display:flex;gap:14px;flex-wrap:wrap;margin-top:8px\">\n      <div class=\"widget-normal\" style=\"flex:1;min-width:200px\">\n        <div class=\"wtitle\">通常の DOM</div>\n        <button class=\"wbtn\">出荷を登録</button>\n      </div>\n      <div id=\"shadow127\" style=\"flex:1;min-width:200px\"></div>\n    </div>\n  </div>","css":"/* 部品側のスタイル（通常版は相手ページと同じ土俵に置かれる） */\n#host127 .widget-normal, #host127 .widget-shadow {\n  background: #fff; border: 1px solid #e5e7eb; border-radius: 8px; padding: 12px;\n}\n#host127 .wtitle { font: 600 13px system-ui; color: #1d1f23; margin-bottom: 8px; }\n#host127 .wbtn { font: 13px system-ui; padding: 6px 12px; border: 1px solid #2563eb;\n  background: #2563eb; color: #fff; border-radius: 6px; cursor: pointer; }\n/* 相手ページが後から入れてくる「乱暴な CSS」 */\n#host127.hostile button { all: unset; color: #b91c1c !important; font-size: 22px !important;\n  font-family: cursive !important; text-decoration: underline; }\n#host127.hostile div { border-radius: 0 !important; background: #fef08a !important; }","js":"(() => {\n  // ---- 配布する部品：Shadow DOM に閉じ込める ----\n  const root = $('#shadow127').attachShadow({ mode: 'open' });   // open でも外の CSS は届かない\n  root.innerHTML = `\n    <style>\n      /* :host = 貼られた場所そのもの。ここだけで完結する */\n      :host { display: block; }\n      .box { background:#fff; border:1px solid #e5e7eb; border-radius:8px; padding:12px; }\n      .t { font:600 13px system-ui; color:#1d1f23; margin-bottom:8px; }\n      button { font:13px system-ui; padding:6px 12px; border:1px solid #16a34a;\n               background:#16a34a; color:#fff; border-radius:6px; cursor:pointer; }\n    </style>\n    <div class=\"box\"><div class=\"t\">Shadow DOM</div><button>出荷を登録</button></div>`;\n  // 影の中のイベントも普通に取れる（外へ出るときは composed に注意）\n  root.querySelector('button').onclick = () => $('#o127').textContent = '影の中のボタンが押された';\n\n  let on = false;\n  $('#b127').onclick = () => {\n    on = !on; $('#host127').classList.toggle('hostile', on);\n    $('#b127').textContent = on ? '乱暴な CSS を止める' : '相手ページの乱暴な CSS を有効にする';\n    $('#o127').textContent = on ? '通常 DOM は崩れた／Shadow DOM は無傷' : '両方とも正常';\n  };\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n128","title":"1283Dの座標系と行列 モデル → ワールド → ビュー → クリップ → 画面","what":"43 の toWorld / toScreen の 3D 版。ある点は5つの座標系を順に通って画面に着く。①モデル座標（部品の中の位置）②ワールド座標（置いた場所）③ビュー座標（カメラから見た位置）④クリップ座標（投影後）⑤画面座標（px）。3Dのバグの大半は「今どの座標系の値を触っているか」の取り違えで起きる。","how":"操作：ドラッグでカメラを回すと、青い部品の角の点が各座標系でどう変わるかが表で追える。ワールド座標は動かず、ビュー以降だけが変わることを確認する。","html":"<div class=\"stage\" style=\"padding:0\">\n    <div class=\"scene\"><canvas class=\"cv\" id=\"c128\"></canvas><div class=\"label\" id=\"l128\">角の点</div></div>\n    <table class=\"cmp\" id=\"t128\" style=\"margin-top:8px\"></table>\n  </div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c128'), { background: '#0f172a' });\n  if (!v) return;\n  v.add({ id: 'grid', geo: Mini3D.Shapes.gridLines(4, .5), color: '#334155' });\n  const part = v.add({ id: 'part', geo: Mini3D.Shapes.box(1.2, 1.2, 1.2), color: '#2563eb', position: [.6, .6, 0] });\n  const LOCAL = [.6, .6, .6];                                   // 部品のローカル座標での「角」\n  const show = () => {\n    const model = Mini3D.mat4.compose(part.position, part.rotation, part.scale);\n    const world = Mini3D.mat4.transformPoint(model, LOCAL);\n    const view = Mini3D.mat4.transformPoint(Mini3D.mat4.lookAt(v.eye(), v.camera.target, [0,1,0]), world);\n    const clip = Mini3D.mat4.transformPoint(v.viewProj(), world);\n    const scr = v.project(world);\n    const f = a => a.map(n => n.toFixed(2)).join(', ');\n    $('#t128').innerHTML = '<tr><th>座標系</th><th>値</th><th>意味</th></tr>' + [\n      ['① モデル', f(LOCAL), '部品の中での位置。部品を動かしても変わらない'],\n      ['② ワールド', f(world), '置かれた場所。カメラを回しても変わらない'],\n      ['③ ビュー', f(view), 'カメラから見た位置。カメラを回すと変わる'],\n      ['④ クリップ(NDC)', f(clip), '-1〜1 に収まっていれば画面内'],\n      ['⑤ 画面', `${scr.x.toFixed(0)}, ${scr.y.toFixed(0)} px`, 'ラベルや計測の表示に使う'],\n    ].map(r => `<tr><td>${r[0]}</td><td><code>${r[1]}</code></td><td>${r[2]}</td></tr>`).join('');\n    const l = $('#l128'); l.style.left = scr.x + 'px'; l.style.top = scr.y + 'px'; l.classList.toggle('dim', scr.behind);\n  };\n  v.attachOrbit({ onChange: show });\n  v.draw(); show();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n129","title":"129カメラ操作 オービット / パン / ドリー","what":"3D ビューアの共通作法。オービット＝注視点を中心に回り込む、パン＝注視点ごと平行移動、ドリー（ズーム）＝注視点との距離を変える。02 のパンと 03 のズームの立体版で、動いているのは物体ではなくカメラという点が違う。真上・真下で回り込みが破綻しないよう仰角に上限を設けるのが定石。","how":"操作：ドラッグ＝オービット、Shift+ドラッグ（または2本指）＝パン、ホイール／ピンチ＝ドリー。","html":"<div class=\"stage\" style=\"padding:0\"><canvas class=\"cv\" id=\"c129\"></canvas></div>\n  <div class=\"row\"><span class=\"readout\" id=\"o129\">-</span><button id=\"b129\">視点を戻す</button></div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c129'), { background: '#0f172a' });\n  if (!v) return;\n  v.add({ id: 'grid', geo: Mini3D.Shapes.gridLines(5, .5), color: '#334155' });\n  v.add({ id: 'base', geo: Mini3D.Shapes.box(3, .3, 2), color: '#64748b', position: [0, -.15, 0] });\n  v.add({ id: 'b1', geo: Mini3D.Shapes.cylinder(.28, 1.1, 20), color: '#2563eb', position: [-.8, .55, .4] });\n  v.add({ id: 'b2', geo: Mini3D.Shapes.cylinder(.28, 1.1, 20), color: '#2563eb', position: [.8, .55, -.4] });\n  const show = () => $('#o129').textContent =\n    `方位 ${(v.camera.azimuth * 180 / Math.PI).toFixed(0)}° / 仰角 ${(v.camera.elevation * 180 / Math.PI).toFixed(0)}° / 距離 ${v.camera.distance.toFixed(1)} / 注視点 ${v.camera.target.map(n => n.toFixed(1)).join(',')}`;\n  v.attachOrbit({ onChange: show });\n  $('#b129').onclick = () => { Object.assign(v.camera, { target: [0,0,0], distance: 6, azimuth: .7, elevation: .5 }); v.draw(); show(); };\n  v.draw(); show();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n130","title":"130ビューキューブと投影方式 正面・上面へのスナップ / 正投影と透視","what":"CAD 系ビューアの右上にある立方体。今どちらを向いているかを示し、面や軸をクリックするとその向きへスナップする。図面的な確認には正投影（奥行きで大きさが変わらない＝寸法が読める）、全体像の把握には透視投影を使い分ける。","how":"操作：ボタンで視点をスナップ。投影方式を切り替えると、奥の部品の大きさの見え方が変わる。","html":"<div class=\"stage\" style=\"padding:0\"><canvas class=\"cv\" id=\"c130\"></canvas></div>\n  <div class=\"row\">\n    <button data-v130=\"front\">正面</button><button data-v130=\"top\">上面</button><button data-v130=\"right\">右</button><button data-v130=\"iso\">等角</button>\n    <label><input type=\"checkbox\" id=\"ortho130\"> 正投影（寸法が読める）</label><span class=\"readout\" id=\"o130\"></span>\n  </div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c130'), { background: '#0f172a' });\n  if (!v) return;\n  v.add({ id: 'grid', geo: Mini3D.Shapes.gridLines(4, .5), color: '#334155' });\n  [[-1.5, 0], [0, 0], [1.5, 0]].forEach(([x], i) =>\n    v.add({ id: 'p' + i, geo: Mini3D.Shapes.box(.8, .8, .8), color: ['#2563eb','#16a34a','#d97706'][i], position: [x, .4, -i * 1.2] }));\n  const views = { front: [0, 0], top: [0, 1.45], right: [Math.PI / 2, 0], iso: [.7, .5] };\n  const show = () => $('#o130').textContent = v.camera.ortho ? '正投影：奥の部品も同じ大きさ' : '透視投影：奥の部品が小さい';\n  $$('[data-v130]').forEach(b => b.onclick = () => {\n    const [a, e] = views[b.dataset.v130];\n    v.camera.azimuth = a; v.camera.elevation = e; v.draw();\n  });\n  $('#ortho130').onchange = e => { v.camera.ortho = e.target.checked; v.draw(); show(); };\n  v.attachOrbit(); v.draw(); show();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n131","title":"131WebGPU と WebGL2 2026年1月に WebGPU が Baseline","what":"ブラウザで 3D を描く API は 2つ。WebGL2 はどこでも動く枯れた選択肢、WebGPU は 2026年1月に主要ブラウザで Baseline に到達した新しい API で、描画コールの束ね方が効率的なうえ計算（コンピュートシェーダ）が使える。業務アプリでの現実解は 113 と同じ段階的強化：WebGPU があれば使い、無ければ WebGL2。このページのデモは WebGL2 で動いている。","how":"操作：この端末の対応状況とアダプタ情報を表示する。","html":"<div class=\"stage\"><table class=\"cmp\" id=\"t131\"></table></div>","css":"","js":"(() => {\n  const rows = [];\n  const gl = document.createElement('canvas').getContext('webgl2');\n  rows.push(['WebGL2', gl ? '対応' : '非対応', gl ? gl.getParameter(gl.VERSION) : '—']);\n  const render = () => $('#t131').innerHTML = '<tr><th>API</th><th>この端末</th><th>詳細</th></tr>' +\n    rows.map(r => `<tr><td>${r[0]}</td><td><b>${r[1]}</b></td><td>${r[2]}</td></tr>`).join('');\n  render();\n  (async () => {\n    if (!('gpu' in navigator)) { rows.push(['WebGPU', '非対応', 'WebGL2 にフォールバックする']); return render(); }\n    try {\n      const ad = await navigator.gpu.requestAdapter();\n      const info = ad && (ad.info || {});\n      rows.push(['WebGPU', ad ? '対応' : 'アダプタなし', ad ? `${info.vendor || '?'} / ${info.architecture || info.description || '?'}` : 'GPU が使えない環境']);\n    } catch (e) { rows.push(['WebGPU', '取得失敗', e.message]); }\n    render();\n  })();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n132","title":"132ピッキング レイキャスト と カラーIDバッファ","what":"「クリックした先にどの部品があるか」を求める操作。2方式ある。レイキャスト＝画面の点から光線を飛ばし、三角形との交差を CPU で計算する（当たった位置と法線まで分かるので計測に使える）。カラーIDバッファ＝各部品を「連番を色にして」描き、1px 読む（三角形数が増えても遅くならない代わりに、GPU の描画完了を待つ readPixels の同期待ちが毎回入る。位置も分からない）。部品数が少ないうちはレイキャストの方が速く、モデルが重くなるほどカラーIDが有利になる。55 の Canvas ヒットテストの 3D 版。","how":"操作：部品をクリック。方式を切り替えて、所要時間と得られる情報の差を見る。","html":"<div class=\"stage\" style=\"padding:0\"><div class=\"scene\"><canvas class=\"cv\" id=\"c132\"></canvas><div class=\"label\" id=\"l132\" hidden></div></div></div>\n  <div class=\"row\">\n    <label><input type=\"radio\" name=\"m132\" value=\"ray\" checked> レイキャスト（位置も分かる）</label>\n    <label><input type=\"radio\" name=\"m132\" value=\"gpu\"> カラーID（速い）</label>\n    <span class=\"readout\" id=\"o132\">部品をクリック</span>\n  </div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c132'), { background: '#0f172a' });\n  if (!v) return;\n  const colors = ['#2563eb', '#16a34a', '#d97706', '#db2777'];\n  v.add({ id: 'grid', geo: Mini3D.Shapes.gridLines(4, .5), color: '#334155' });\n  for (let i = 0; i < 4; i++)\n    v.add({ id: '部品' + (i + 1), geo: i % 2 ? Mini3D.Shapes.cylinder(.4, 1, 20) : Mini3D.Shapes.box(.9, .9, .9),\n            color: colors[i], position: [(i % 2 ? -1.2 : 1.2), .5, (i < 2 ? -1 : 1)] });\n  $('#c132').addEventListener('click', e => {\n    const mode = $('input[name=m132]:checked').value, t0 = performance.now();\n    if (mode === 'ray') {\n      const hit = v.raycast(e.clientX, e.clientY);\n      $('#o132').textContent = hit\n        ? `${hit.object.id} / 交点 (${hit.point.map(n => n.toFixed(2)).join(', ')}) / ${(performance.now() - t0).toFixed(2)}ms`\n        : `何もない / ${(performance.now() - t0).toFixed(2)}ms`;\n      const l = $('#l132');\n      if (hit) { const p = v.project(hit.point); l.hidden = false; l.textContent = hit.object.id; l.style.left = p.x + 'px'; l.style.top = p.y + 'px'; }\n      else l.hidden = true;\n    } else {\n      const o = v.pickGPU(e.clientX, e.clientY);\n      $('#o132').textContent = (o ? o.id : '何もない') + ` / 位置は分からない / ${(performance.now() - t0).toFixed(2)}ms`;\n      $('#l132').hidden = true;\n    }\n  });\n  v.attachOrbit(); v.draw();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n133","title":"133変形ギズモ 軸ハンドルで動かす","what":"選んだ部品を動かす取っ手。要点は3つ。①軸に拘束する（X ハンドルを掴んだら X しか動かない＝51 の軸固定の 3D 版）②画面上で一定の大きさに見えるようカメラ距離に比例させる（遠くの部品でも掴める）③掴んでいる間はカメラ操作を止める（52 の状態機械）。ドラッグ量は軸を含みカメラに正対する平面との交点から求める。","how":"操作：部品をクリックで選択 → 赤(X)・緑(Y)・青(Z) の棒をドラッグ。Shift で 0.25 刻みに吸着（134）。","html":"<div class=\"stage\" style=\"padding:0\"><canvas class=\"cv\" id=\"c133\"></canvas></div>\n  <div class=\"row\"><span class=\"readout\" id=\"o133\">部品を選ぶ</span><button id=\"b133\">位置を戻す</button></div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c133'), { background: '#0f172a' });\n  if (!v) return;\n  v.add({ id: 'grid', geo: Mini3D.Shapes.gridLines(4, .25), color: '#334155' });\n  const parts = [0, 1].map(i => v.add({ id: '治具' + (i + 1), geo: Mini3D.Shapes.box(.8, .8, .8), color: '#2563eb', position: [i ? 1.2 : -1.2, .4, 0] }));\n  const AX = [[1,0,0], [0,1,0], [0,0,1]], AXC = ['#ef4444', '#22c55e', '#3b82f6'];\n  // 掴みやすさのため、見た目より太めにする（103 の当たり判定の話は 3D でも同じ）\n  const handles = AX.map((a, i) => v.add({ id: 'h' + i, geo: Mini3D.Shapes.cylinder(.1, 1.1, 10), color: AXC[i], visible: false,\n    rotation: i === 0 ? [0,0,-Math.PI/2] : i === 2 ? [Math.PI/2,0,0] : [0,0,0] }));\n  let sel = null, drag = null;\n  const layout = () => {                                   // ② 画面上で一定サイズに見せる\n    if (!sel) return;\n    const s = v.camera.distance / 6;\n    handles.forEach((h, i) => { h.visible = true; h.scale = [s, s, s];\n      h.position = sel.position.map((p, k) => p + AX[i][k] * 0.6 * s); });\n  };\n  const hideHandles = () => handles.forEach(h => h.visible = false);\n  const rayPlanePoint = (e, axis, origin) => {              // 軸を含み、カメラに正対する平面との交点\n    const r = v.ray(e.clientX, e.clientY);\n    const view = Mini3D.vec3.normalize(Mini3D.vec3.sub(v.eye(), origin));\n    let n = Mini3D.vec3.cross(Mini3D.vec3.cross(axis, view), axis);\n    n = Mini3D.vec3.normalize(n);\n    const den = Mini3D.vec3.dot(r.dir, n);\n    if (Math.abs(den) < 1e-6) return null;\n    const t = Mini3D.vec3.dot(Mini3D.vec3.sub(origin, r.origin), n) / den;\n    return Mini3D.vec3.add(r.origin, Mini3D.vec3.scale(r.dir, t));\n  };\n  const canvas = $('#c133');\n  canvas.addEventListener('pointerdown', e => {\n    const hit = v.raycast(e.clientX, e.clientY);\n    if (hit && hit.object.id.startsWith('h')) {             // ハンドルを掴んだ：カメラ操作は止める（③）\n      const i = +hit.object.id[1];\n      const start = rayPlanePoint(e, AX[i], sel.position);\n      drag = { axis: i, start, base: sel.position.slice() };\n      canvas.setPointerCapture(e.pointerId);\n    } else if (hit) { sel = hit.object; layout(); v.draw(); $('#o133').textContent = `${sel.id} を選択`; }\n    else { sel = null; hideHandles(); v.draw(); $('#o133').textContent = '部品を選ぶ'; }\n  });\n  canvas.addEventListener('pointermove', e => {\n    if (!drag || !sel) return;\n    const p = rayPlanePoint(e, AX[drag.axis], sel.position);\n    if (!p || !drag.start) return;\n    let d = Mini3D.vec3.dot(Mini3D.vec3.sub(p, drag.start), AX[drag.axis]);   // ① 軸方向の成分だけ取る\n    if (e.shiftKey) d = Math.round((drag.base[drag.axis] + d) / .25) * .25 - drag.base[drag.axis];\n    sel.position = drag.base.map((b, k) => b + AX[drag.axis][k] * d);\n    layout(); v.draw();\n    $('#o133').textContent = `${sel.id} 位置 (${sel.position.map(n => n.toFixed(2)).join(', ')})${e.shiftKey ? ' / 0.25 刻み' : ''}`;\n  });\n  canvas.addEventListener('pointerup', () => drag = null);\n  $('#b133').onclick = () => { parts.forEach((p, i) => p.position = [i ? 1.2 : -1.2, .4, 0]); layout(); v.draw(); };\n  v.attachOrbit({ filter: e => !drag });                    // ③ 掴んでいる間はカメラを回さない\n  v.draw();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n134","title":"134スナップ グリッド / 面 / 角度","what":"47 のスナップの 3D 版。位置の刻み（グリッド）、他の部品の面に載せる、角度の刻み（15°など）。判定は 47 と同じ「候補を列挙し、しきい値内で最も近いものに吸着」。3D では吸着したことを画面で示す（ガイド線・色変化）のがより重要で、見た目だけでは合っているか分からない。","how":"操作：スライダで部品を動かす。刻みを切り替えると、値が丸められる。","html":"<div class=\"stage\" style=\"padding:0\"><canvas class=\"cv\" id=\"c134\"></canvas></div>\n  <div class=\"row\">\n    X <input type=\"range\" id=\"x134\" min=\"-2\" max=\"2\" step=\"0.01\" value=\"-1\">\n    <select id=\"s134\"><option value=\"0\">刻みなし</option><option value=\"0.25\" selected>0.25</option><option value=\"0.5\">0.5</option></select>\n    <label><input type=\"checkbox\" id=\"f134\" checked> 面に載せる</label>\n    <span class=\"readout\" id=\"o134\"></span>\n  </div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c134'), { background: '#0f172a' });\n  if (!v) return;\n  v.add({ id: 'grid', geo: Mini3D.Shapes.gridLines(3, .25), color: '#334155' });\n  const table = v.add({ id: 'table', geo: Mini3D.Shapes.box(3, .4, 2), color: '#475569', position: [0, -.2, 0] });\n  const part = v.add({ id: 'part', geo: Mini3D.Shapes.box(.6, .6, .6), color: '#2563eb', position: [-1, .3, 0] });\n  const update = () => {\n    const step = +$('#s134').value;\n    let x = +$('#x134').value;\n    const snappedX = step ? Math.round(x / step) * step : x;\n    const y = $('#f134').checked ? 0.3 : +(0.3 + Math.abs(Math.sin(x * 3)) * .4).toFixed(3);   // 面に載せない例\n    part.position = [snappedX, y, 0];\n    part.color = (step && Math.abs(snappedX - x) > 1e-6) ? '#16a34a' : '#2563eb';               // 吸着したら色で示す\n    $('#o134').textContent = `X ${x.toFixed(2)} → ${snappedX.toFixed(2)}${$('#f134').checked ? ' / 天板の面に載せる' : ' / 面を無視'}`;\n    v.draw();\n  };\n  // check-ime-ignore : range / checkbox のため変換が発生しない\n  ['#x134', '#s134', '#f134'].forEach(s => $(s).addEventListener('input', update));\n  v.attachOrbit(); update();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n135","title":"135選択の可視化 強調・半透明・複数選択","what":"11 の選択の 3D 版。3D では選んだ物が他の部品の裏に隠れるため、色を変えるだけでは足りない。実務では①選択部品を強調色にする ②それ以外を半透明にする（中身が見える）③輪郭線を描く、のいずれかを使う。Ctrl/⌘ で追加選択するのは 11 と同じ作法。","how":"操作：部品をクリック。Ctrl/⌘+クリックで追加。表示方式を切り替える。","html":"<div class=\"stage\" style=\"padding:0\"><canvas class=\"cv\" id=\"c135\"></canvas></div>\n  <div class=\"row\">\n    <label><input type=\"radio\" name=\"v135\" value=\"color\" checked> 色を変える</label>\n    <label><input type=\"radio\" name=\"v135\" value=\"ghost\"> 他を半透明に</label>\n    <span class=\"readout\" id=\"o135\">選択なし</span>\n  </div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c135'), { background: '#0f172a' });\n  if (!v) return;\n  v.add({ id: 'grid', geo: Mini3D.Shapes.gridLines(4, .5), color: '#334155' });\n  const parts = [];\n  for (let i = 0; i < 6; i++) parts.push(v.add({ id: '部品' + (i + 1), geo: Mini3D.Shapes.box(.7, .7, .7), color: '#64748b',\n    position: [(i % 3 - 1) * 1.1, .4, (i < 3 ? -.7 : .7)] }));\n  const sel = new Set();\n  const paint = () => {\n    const ghost = $('input[name=v135]:checked').value === 'ghost';\n    parts.forEach(p => {\n      const on = sel.has(p);\n      p.color = on ? '#f59e0b' : '#64748b';\n      p.opacity = ghost && !on && sel.size ? .25 : 1;\n    });\n    $('#o135').textContent = sel.size ? [...sel].map(p => p.id).join(', ') : '選択なし';\n    v.draw();\n  };\n  $('#c135').addEventListener('click', e => {\n    const hit = v.raycast(e.clientX, e.clientY);\n    if (!hit) { sel.clear(); return paint(); }\n    if (!(e.ctrlKey || e.metaKey)) sel.clear();\n    sel.has(hit.object) ? sel.delete(hit.object) : sel.add(hit.object);\n    paint();\n  });\n  $$('input[name=v135]').forEach(r => r.onchange = paint);\n  v.attachOrbit(); paint();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n136","title":"136計測 2点間の距離","what":"現場で最もよく使われる 3D 機能。132 のレイキャストが「当たった位置」を返すので、2点取れば距離が出る。実装で外せないのは①どの点を取ったかを 3D 上に示す ②寸法線と数値を2D のラベルとして重ねる（139 と同じ仕組み）③単位と丸めを明示する（モデルの 1.0 が 1m なのか 1mm なのかは形式とデータ次第で、glTF は m が既定）。","how":"操作：部品の面を2か所クリック。距離が出る。「やり直す」で消える。","html":"<div class=\"stage\" style=\"padding:0\"><div class=\"scene\"><canvas class=\"cv\" id=\"c136\"></canvas><div class=\"label\" id=\"l136a\" hidden></div><div class=\"label\" id=\"l136b\" hidden></div><div class=\"label\" id=\"l136d\" hidden></div></div></div>\n  <div class=\"row\"><span class=\"readout\" id=\"o136\">1点目をクリック</span><button id=\"b136\">やり直す</button>\n    <select id=\"u136\"><option value=\"1000\">単位: mm（1.0 = 1000mm）</option><option value=\"1\">単位: m</option></select></div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c136'), { background: '#0f172a' });\n  if (!v) return;\n  v.add({ id: 'grid', geo: Mini3D.Shapes.gridLines(3, .5), color: '#334155' });\n  v.add({ id: '台', geo: Mini3D.Shapes.box(3, .3, 2), color: '#475569', position: [0, -.15, 0] });\n  v.add({ id: 'A', geo: Mini3D.Shapes.box(.8, 1.2, .8), color: '#2563eb', position: [-1, .6, 0] });\n  v.add({ id: 'B', geo: Mini3D.Shapes.cylinder(.4, .8, 20), color: '#16a34a', position: [1, .4, 0] });\n  const pts = [];\n  const marks = [];\n  const paint = () => {\n    marks.forEach(m => m.visible = false);\n    pts.forEach((p, i) => {\n      if (!marks[i]) marks[i] = v.add({ id: 'm' + i, geo: Mini3D.Shapes.box(.1, .1, .1), color: '#f59e0b' });\n      marks[i].visible = true; marks[i].position = p;\n    });\n    if (pts.length === 2) {                                  // 2点を結ぶ線\n      const line = v.get('line') || v.add({ id: 'line', geo: { pos: new Float32Array(6), lines: true }, color: '#f59e0b' });\n      line.geo.pos = new Float32Array([...pts[0], ...pts[1]]); line.geo._vao = null; line.visible = true;\n    } else if (v.get('line')) v.get('line').visible = false;\n    v.draw();\n    const u = +$('#u136').value;\n    [0, 1].forEach(i => {\n      const l = $(i ? '#l136b' : '#l136a');\n      if (!pts[i]) return l.hidden = true;\n      const s = v.project(pts[i]); l.hidden = false; l.textContent = (i ? 'P2' : 'P1'); l.style.left = s.x + 'px'; l.style.top = s.y + 'px';\n    });\n    const d = $('#l136d');\n    if (pts.length === 2) {\n      const mid = pts[0].map((n, k) => (n + pts[1][k]) / 2);\n      const dist = Mini3D.vec3.length(Mini3D.vec3.sub(pts[1], pts[0])) * u;\n      const s = v.project(mid); d.hidden = false; d.textContent = `${dist.toFixed(u === 1 ? 3 : 1)} ${u === 1 ? 'm' : 'mm'}`;\n      d.style.left = s.x + 'px'; d.style.top = s.y + 'px';\n      $('#o136').textContent = `2点間 ${dist.toFixed(u === 1 ? 3 : 1)} ${u === 1 ? 'm' : 'mm'}（やり直すで消える）`;\n    } else d.hidden = true;\n  };\n  $('#c136').addEventListener('click', e => {\n    const hit = v.raycast(e.clientX, e.clientY, o => !o.id.startsWith('m') && o.id !== 'line');\n    if (!hit) return;\n    if (pts.length >= 2) pts.length = 0;\n    pts.push(hit.point);\n    $('#o136').textContent = pts.length === 1 ? '2点目をクリック' : '';\n    paint();\n  });\n  $('#b136').onclick = () => { pts.length = 0; $('#o136').textContent = '1点目をクリック'; paint(); };\n  $('#u136').onchange = paint;\n  v.attachOrbit({ onChange: paint });\n  paint();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n137","title":"137断面 クリッピング平面","what":"組立の内部や、部品同士の干渉を見るために手前を切り落とす。実装は簡単で、フラグメントシェーダで「平面の表側にある画素を捨てる」だけ（discard）。注意点は切り口が開いて見えること。中身が詰まって見える「キャップ」を作るには、裏面だけを別に描くなどの追加処理が要る。","how":"操作：軸とスライダで切る位置を変える。キャップの有無で見え方の違いを比べる。","html":"<div class=\"stage\" style=\"padding:0\"><canvas class=\"cv\" id=\"c137\"></canvas></div>\n  <div class=\"row\">\n    <select id=\"a137\"><option value=\"0\">X で切る</option><option value=\"1\">Y で切る</option><option value=\"2\">Z で切る</option></select>\n    <input type=\"range\" id=\"s137\" min=\"-1.5\" max=\"1.5\" step=\"0.02\" value=\"0.2\" style=\"flex:1\">\n    <label><input type=\"checkbox\" id=\"cap137\"> 切り口を塞ぐ（簡易キャップ）</label>\n  </div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c137'), { background: '#0f172a' });\n  if (!v) return;\n  v.add({ id: 'case', geo: Mini3D.Shapes.box(2.2, 1.4, 1.6), color: '#94a3b8', opacity: 1 });\n  v.add({ id: 'in1', geo: Mini3D.Shapes.cylinder(.35, 1.1, 20), color: '#2563eb', position: [-.5, 0, 0] });\n  v.add({ id: 'in2', geo: Mini3D.Shapes.box(.6, .6, .6), color: '#16a34a', position: [.6, -.2, .2] });\n  const cap = v.add({ id: 'cap', geo: Mini3D.Shapes.plane(2.4, 1.8), color: '#1f2937', visible: false, rotation: [0, 0, Math.PI / 2] });\n  const update = () => {\n    const ax = +$('#a137').value, off = +$('#s137').value;\n    const n = [0, 0, 0]; n[ax] = 1;\n    v.clip = { normal: n, offset: off };\n    cap.visible = $('#cap137').checked;\n    cap.rotation = ax === 0 ? [0, 0, Math.PI / 2] : ax === 1 ? [0, 0, 0] : [Math.PI / 2, 0, 0];\n    cap.position = n.map(k => k * (off - 0.001));\n    v.draw();\n  };\n  // check-ime-ignore : range / checkbox のため変換が発生しない\n  ['#a137', '#s137', '#cap137'].forEach(s => $(s).addEventListener('input', update));\n  v.attachOrbit(); update();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n138","title":"138分解図と組立手順 Exploded view","what":"部品を中心から離して、重なりを解いて見せる。作業手順書では段階的に離す／1部品ずつ順に出すことで組立順を示す。実装は「各部品に離す方向を持たせ、係数 t を 0→1 に動かす」だけ。順に出す演出は 64 のスタガーと同じで、t を部品ごとに遅らせる。","how":"操作：スライダで分解、「手順を再生」で順に組み上がる。","html":"<div class=\"stage\" style=\"padding:0\"><canvas class=\"cv\" id=\"c138\"></canvas></div>\n  <div class=\"row\">分解 <input type=\"range\" id=\"s138\" min=\"0\" max=\"1\" step=\"0.01\" value=\"0\" style=\"flex:1\"><button id=\"b138\">手順を再生</button><span class=\"readout\" id=\"o138\"></span></div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c138'), { background: '#0f172a' });\n  if (!v) return;\n  const defs = [\n    ['ベース', Mini3D.Shapes.box(2, .3, 1.4), '#475569', [0, -.5, 0], [0, -1, 0]],\n    ['本体',   Mini3D.Shapes.box(1.4, .8, 1), '#64748b', [0, .1, 0], [0, 0, 0]],\n    ['カバー', Mini3D.Shapes.box(1.5, .2, 1.1), '#94a3b8', [0, .6, 0], [0, 1, 0]],\n    ['ボルト', Mini3D.Shapes.cylinder(.12, .6, 12), '#2563eb', [.5, .9, .3], [.6, 1.4, .4]],\n  ];\n  const parts = defs.map(([id, geo, color, home, dir]) => ({ o: v.add({ id, geo, color, position: home.slice() }), home, dir }));\n  const apply = t => {\n    parts.forEach((p, i) => {\n      const ti = Math.max(0, Math.min(1, (t - i * .12) / (1 - .12 * (parts.length - 1))));   // 部品ごとに遅らせる（64）\n      p.o.position = p.home.map((h, k) => h + p.dir[k] * ti * 1.2);\n    });\n    v.draw(); $('#o138').textContent = t === 0 ? '組み上がり' : t === 1 ? '完全に分解' : `分解 ${(t * 100) | 0}%`;\n  };\n  $('#s138').addEventListener('input', e => apply(+e.target.value));\n  $('#b138').onclick = () => {                                  // 1→0 へ動かす＝組み立てる\n    const t0 = performance.now(), dur = 1600;\n    const step = now => { const k = Math.min(1, (now - t0) / dur); const t = 1 - k;\n      $('#s138').value = t; apply(t); if (k < 1) requestAnimationFrame(step); };\n    apply(1); $('#s138').value = 1; requestAnimationFrame(step);\n  };\n  v.attachOrbit(); apply(0);\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n139","title":"139注釈・ホットスポット 3D 座標に貼り付くラベル","what":"17 のツールチップの 3D 版。ラベルは DOM 要素のままにして、project() で 3D 座標を画面座標に変換して毎フレーム位置を合わせるのが定石（文字は DOM の方が読みやすく、選択もできる）。要点は裏側に回ったら薄くする／隠すこと。厳密には「そのラベル位置がカメラから見えているか」をレイキャストで判定する（遮蔽判定）。","how":"操作：カメラを回すと、部品の裏に回ったラベルが薄くなる。ラベルをクリックすると内容が出る。","html":"<div class=\"stage\" style=\"padding:0\"><div class=\"scene\"><canvas class=\"cv\" id=\"c139\"></canvas><div id=\"h139\"></div></div></div>\n  <div class=\"row\"><label><input type=\"checkbox\" id=\"occ139\" checked> 遮蔽を判定して薄くする</label><span class=\"readout\" id=\"o139\">ラベルをクリック</span></div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c139'), { background: '#0f172a' });\n  if (!v) return;\n  v.add({ id: 'grid', geo: Mini3D.Shapes.gridLines(3, .5), color: '#334155' });\n  v.add({ id: 'body', geo: Mini3D.Shapes.box(1.6, 1, 1.2), color: '#64748b' });\n  const spots = [\n    { p: [0, .5, 0], text: '天面：ここに銘板を貼る' },\n    { p: [.8, 0, 0], text: '右面：締結トルク 12N・m' },\n    { p: [0, 0, -.6], text: '背面：配線の逃げに注意' },\n  ];\n  const host = $('#h139');\n  host.innerHTML = spots.map((s, i) => `<div class=\"label hot\" data-i=\"${i}\">${i + 1}</div>`).join('');\n  const layout = () => {\n    spots.forEach((s, i) => {\n      const el = host.children[i], q = v.project(s.p);\n      el.style.left = q.x + 'px'; el.style.top = q.y + 'px';\n      let hidden = q.behind;\n      if (!hidden && $('#occ139').checked) {\n        // 遮蔽判定：その画面位置にレイを飛ばし、最初に当たった点がラベル位置と一致するか。\n        // （距離で比べるとレイの起点＝ニアプレーンとカメラ位置のずれを踏まえる必要があり、点で比べる方が確実）\n        const r = v.canvas.getBoundingClientRect();\n        const hit = v.raycast(r.left + q.x, r.top + q.y);\n        if (!hit || Mini3D.vec3.length(Mini3D.vec3.sub(hit.point, s.p)) > 0.05) hidden = true;\n      }\n      el.classList.toggle('dim', hidden);\n    });\n  };\n  host.addEventListener('click', e => { const i = e.target.dataset.i; if (i != null) $('#o139').textContent = spots[i].text; });\n  $('#occ139').onchange = layout;\n  v.attachOrbit({ onChange: layout });\n  v.draw(); layout();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n140","title":"140モデルの読み込みと変換 glTF / GLB と、CAD 形式からの変換","what":"Web の 3D の標準は glTF（.gltf / .glb）で、「3D の JPEG」と呼ばれる転送用の形式。製造業で手元にあるのは STEP・IGES・IFC・DWGだが、これらはブラウザで直接は開けず事前の変換が要る（IFC は web-ifc、STEP は OpenCascade 系のツールで変換するのが定番）。設計データをそのまま配らず「表示用に変換したもの」を配るのは、容量と機密の両面で正しい。","how":"操作：下の箱を glTF に書き出し、それを読み込み直して表示する（JSON の中身も見える）。","html":"<div class=\"stage\" style=\"padding:0\">\n    <canvas class=\"cv\" id=\"c140\"></canvas>\n    <details class=\"code\" style=\"margin:8px\"><summary>生成された glTF（抜粋）</summary><pre id=\"j140\" style=\"max-height:200px\"></pre></details>\n  </div>\n  <div class=\"row\"><button id=\"b140\" class=\"primary\">glTF に書き出して読み込み直す</button><span class=\"readout\" id=\"o140\">-</span></div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c140'), { background: '#0f172a' });\n  if (!v) return;\n  const src = Mini3D.Shapes.box(1.2, 1.2, 1.2);\n  v.add({ id: 'src', geo: src, color: '#64748b', position: [-1, 0, 0] });\n  const b64 = buf => { let s = ''; const u = new Uint8Array(buf); for (let i = 0; i < u.length; i++) s += String.fromCharCode(u[i]); return btoa(s); };\n  // --- 書き出し：位置・法線・索引を1つのバッファに詰め、アクセサで場所を示す（これが glTF の骨格） ---\n  const exportGltf = geo => {\n    const idx = new Uint16Array(geo.idx), pos = geo.pos, nrm = geo.nrm;\n    const bytes = new Uint8Array(pos.byteLength + nrm.byteLength + Math.ceil(idx.byteLength / 4) * 4);\n    bytes.set(new Uint8Array(pos.buffer), 0);\n    bytes.set(new Uint8Array(nrm.buffer), pos.byteLength);\n    bytes.set(new Uint8Array(idx.buffer), pos.byteLength + nrm.byteLength);\n    const min = [Infinity, Infinity, Infinity], max = [-Infinity, -Infinity, -Infinity];\n    for (let i = 0; i < pos.length; i += 3) for (let k = 0; k < 3; k++) { min[k] = Math.min(min[k], pos[i+k]); max[k] = Math.max(max[k], pos[i+k]); }\n    return {\n      asset: { version: '2.0', generator: 'ui-guide mini3d' },\n      scenes: [{ nodes: [0] }], scene: 0, nodes: [{ mesh: 0, name: '部品' }],\n      meshes: [{ primitives: [{ attributes: { POSITION: 0, NORMAL: 1 }, indices: 2, mode: 4 }] }],\n      accessors: [\n        { bufferView: 0, componentType: 5126, count: pos.length / 3, type: 'VEC3', min, max },   // 5126 = FLOAT\n        { bufferView: 1, componentType: 5126, count: nrm.length / 3, type: 'VEC3' },\n        { bufferView: 2, componentType: 5123, count: idx.length, type: 'SCALAR' },               // 5123 = UNSIGNED_SHORT\n      ],\n      bufferViews: [\n        { buffer: 0, byteOffset: 0, byteLength: pos.byteLength },\n        { buffer: 0, byteOffset: pos.byteLength, byteLength: nrm.byteLength },\n        { buffer: 0, byteOffset: pos.byteLength + nrm.byteLength, byteLength: idx.byteLength },\n      ],\n      buffers: [{ byteLength: bytes.byteLength, uri: 'data:application/octet-stream;base64,' + b64(bytes.buffer) }],\n    };\n  };\n  // --- 読み込み：アクセサの指す範囲を型付き配列として取り出すだけ ---\n  const importGltf = async json => {\n    const bin = await (await fetch(json.buffers[0].uri)).arrayBuffer();\n    const read = (i, Ctor) => { const a = json.accessors[i], bv = json.bufferViews[a.bufferView];\n      return new Ctor(bin, bv.byteOffset, a.count * (a.type === 'VEC3' ? 3 : 1)); };\n    const prim = json.meshes[0].primitives[0];\n    return { pos: read(prim.attributes.POSITION, Float32Array), nrm: read(prim.attributes.NORMAL, Float32Array), idx: read(prim.indices, Uint16Array) };\n  };\n  $('#b140').onclick = async () => {\n    const json = exportGltf(src);\n    const text = JSON.stringify(json, null, 1);\n    $('#j140').textContent = text.replace(/(\"uri\": \"data:[^\"]{40})[^\"]*/, '$1…（base64 が続く）');\n    const geo = await importGltf(json);\n    const old = v.get('loaded'); if (old) v.objects.splice(v.objects.indexOf(old), 1);\n    v.add({ id: 'loaded', geo, color: '#2563eb', position: [1, 0, 0] });\n    v.draw();\n    $('#o140').textContent = `書き出し ${(text.length / 1024).toFixed(1)}KB → 読み込み 頂点 ${geo.pos.length / 3} / 三角形 ${geo.idx.length / 3}（右が読み込んだもの）`;\n  };\n  v.attachOrbit(); v.draw();\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n141","title":"141大規模モデルの性能 描画コールとフレーム時間","what":"54・F9・F10 の 3D 版。3D で最初に効くのは描画コールの数（部品ごとに1回 GPU に命令すると、部品数がそのままコストになる）。対策は①同じ形はまとめて一度に描く（インスタンス化）②画面外を描かない（カリング）③遠くは粗いモデルに差し替える（LOD）。現場のタブレットは GPU が弱いので、必ず実機で測る。","how":"操作：部品数を変えてフレーム時間を見る。数百を超えると描画コールが効いてくる。","html":"<div class=\"stage\" style=\"padding:0\"><canvas class=\"cv\" id=\"c141\"></canvas></div>\n  <div class=\"row\">部品数 <input type=\"range\" id=\"n141\" min=\"10\" max=\"1200\" step=\"10\" value=\"200\"><span class=\"readout\" id=\"o141\">-</span></div>","css":"","js":"(() => {\n  const v = Mini3D.createViewer($('#c141'), { background: '#0f172a' });\n  if (!v) return;\n  const geo = Mini3D.Shapes.box(.18, .18, .18);                 // 形は共有（GPU へのアップロードは1回）\n  const build = n => {\n    v.objects.length = 0;\n    for (let i = 0; i < n; i++) {\n      const a = i * 0.618 * Math.PI * 2, r = .3 + (i / n) * 3.2;\n      v.add({ id: 'p' + i, geo, color: i % 3 ? '#2563eb' : '#94a3b8',\n              position: [Math.cos(a) * r, (i % 12) * .12 - .7, Math.sin(a) * r] });\n    }\n  };\n  let frames = 0, acc = 0, last = performance.now(), raf = 0;\n  const loop = () => {\n    v.camera.azimuth += 0.004; v.draw();\n    const now = performance.now(); acc += now - last; last = now;\n    if (++frames >= 30) { $('#o141').textContent = `部品 ${v.objects.length} / 描画コール ${v.objects.length} 回 / 平均 ${(acc / frames).toFixed(1)} ms/frame`; frames = 0; acc = 0; }\n    raf = requestAnimationFrame(loop);\n  };\n  $('#n141').addEventListener('input', e => build(+e.target.value));\n  build(200);\n  const io = new IntersectionObserver(([e]) => {                 // 見えている間だけ回す（54 の考え方）\n    if (e.isIntersecting && !raf) { last = performance.now(); raf = requestAnimationFrame(loop); }\n    else if (!e.isIntersecting && raf) { cancelAnimationFrame(raf); raf = 0; }\n  });\n  io.observe($('#c141'));\n})();"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n142","title":"142AR で現物と重ねる WebXR / Scene Viewer / Quick Look","what":"現場で「図面の部品が、実際にその場所へ収まるか」を確かめる使い方。Web の AR は単一の API ではなく、端末ごとに別の仕組みへ橋渡しするのが実情：Android は WebXR（ブラウザ内でそのまま）か Scene Viewer（OS のアプリへ渡す）、iOS は Quick Look（.usdz を OS に渡す）。&lt;model-viewer&gt; はこの3つを自動で切り替える。glTF と USDZ の2形式を用意する必要がある点が実務上の最大の注意。","how":"操作：この端末で AR が使えるかを判定する。現場のスマートフォン・タブレットで開くと結果が変わる。","html":"<div class=\"stage\">\n    <table class=\"cmp\" id=\"t142\"></table>\n    <p class=\"note\" style=\"margin-top:8px\">この資料は依存なしを方針としているため <code>&lt;model-viewer&gt;</code> は読み込んでいない。実装時は下のタグを置くだけでよい。</p>\n  </div>","css":"","js":"(() => {\n  const rows = [\n    ['WebXR（immersive-ar）', () => 'xr' in navigator ? navigator.xr.isSessionSupported('immersive-ar').then(v => v ? '使える' : '使えない').catch(() => '判定不可') : Promise.resolve('navigator.xr が無い'), 'Android Chrome など。ブラウザ内で AR が動く'],\n    ['WebXR（immersive-vr）', () => 'xr' in navigator ? navigator.xr.isSessionSupported('immersive-vr').then(v => v ? '使える' : '使えない').catch(() => '判定不可') : Promise.resolve('navigator.xr が無い'), 'ヘッドセット向け'],\n    ['Scene Viewer', () => Promise.resolve(/Android/i.test(navigator.userAgent) ? '経路あり（Android）' : '対象外'), 'Android で OS のビューアに渡す'],\n    ['Quick Look', () => Promise.resolve(/iPhone|iPad|Macintosh/.test(navigator.userAgent) ? '経路あり（iOS/macOS・.usdz が必要）' : '対象外'), 'iOS で OS のビューアに渡す'],\n    ['カメラ許可', () => navigator.permissions ? navigator.permissions.query({ name: 'camera' }).then(p => p.state).catch(() => '判定不可') : Promise.resolve('判定不可'), 'AR にはカメラの許可が要る'],\n    ['安全なコンテキスト', () => Promise.resolve(isSecureContext ? 'HTTPS（または localhost）' : 'HTTP → AR もカメラも使えない'), 'AR は HTTPS 必須'],\n  ];\n  const t = $('#t142');\n  t.innerHTML = '<tr><th>経路</th><th>この端末</th><th>説明</th></tr>' + rows.map(r => `<tr><td>${r[0]}</td><td>判定中…</td><td>${r[2]}</td></tr>`).join('');\n  rows.forEach((r, i) => r[1]().then(val => t.rows[i + 1].cells[1].innerHTML = `<b>${val}</b>`));\n})();"}];
